Table_Dialog_Left_2 = {
  [8520] = "{id=8520,Text='根据大陆卫队的报告，我们在金字塔的深处发现了一些很糟糕的事情',Speaker=1105,}",
  [8521] = "{id=8521,Text='有一个自称为“女神之手”的组织，完全的控制了金字塔深处，在那里进行着一场神秘的仪式',Speaker=1105,}",
  [8522] = "{id=8522,Text='皇室非常重视这次的事件，指派了冒险者公会的最强战力，前往金字塔，当你准备好之后，我们就立刻出发',Speaker=1105,Option='{准备就绪,3}{还未准备好,2}',}",
  [8523] = "{id=8523,Text='当你准备好的时候随时来找我',Speaker=1105,}",
  [8524] = "{id=8524,Text='很好，接下来我将会把大家传送到金字塔深处，到达之后希盖会告诉你下一步的行动计划',Speaker=1105,}",
  [8525] = "{id=8525,Text='现在的你必须比任何人都坚强，神官将会赐予人民幸福与温暖',Speaker=1104,}",
  [8526] = "{id=8526,Text='根据大陆卫队的报告，我们在金字塔的深处发现了一些很糟糕的事情',Speaker=1104,}",
  [8527] = "{id=8527,Text='有一个自称为“女神之手”的组织，完全的控制了金字塔深处，在那里进行着一场神秘的仪式',Speaker=1104,}",
  [8528] = "{id=8528,Text='皇室非常重视这次的事件，指派了冒险者公会的最强战力，前往金字塔，当你准备好之后，我们就立刻出发',Speaker=1104,Option='{准备就绪,3}{还未准备好,2}',}",
  [8529] = "{id=8529,Text='当你准备好的时候随时来找我',Speaker=1104,}",
  [8530] = "{id=8530,Text='很好，接下来莱伊娜丝将会把我们传送到金字塔深处，到达之后希盖会告诉你下一步的行动计划',Speaker=1104,}",
  [8531] = "{id=8531,Text='那么就让我们开始吧，由于我们传送的距离比较长过程中可能会有些不适，请忍耐一下',Speaker=1105,Option='出发！',}",
  [8532] = "{id=8532,Text='冒险者，我们了解到这个组织正在这里通过一些黑暗的魔法转化这里的不死魔物',Speaker=3220,}",
  [8533] = "{id=8533,Text='我们需要搞清楚他们的目的，并且立刻阻止他们的“仪式”',Speaker=3220,}",
  [8534] = "{id=8534,Text='这的任务非常危险，我需要你们与导师们互相配合',Speaker=3220,}",
  [8535] = "{id=8535,Text='伊丝米儿已经潜入深处，请赶快过去与她会和',Speaker=3220,}",
  [8536] = "{id=8536,Text='骑士们救出了他们仪式所需要的孩子们，神射手们把那边被转化的魔物消灭了',Speaker=3223,}",
  [8537] = "{id=8537,Text='而我们要做的就是击败那个守在路口的人，霍格，我想你曾经应该见过他',Speaker=3223,}",
  [8538] = "{id=8538,Text='我曾经在吉芬见到他时，不曾感受到如此的魔力，正面与他交锋一定不是个聪明的办法',Speaker=3223,}",
  [8539] = "{id=8539,Text='我在西边发现一些情报员，袭击他们，获取关于仪式的情报，换上他们的衣服，骗过霍格后，一口气干掉他',Speaker=3223,}",
  [8540] = "{id=8540,Text='一条笔记上模糊的写着“仪式任然不成熟，我们需要更强大的魔法才能控制哪些强大的不死魔物”',}",
  [8541] = "{id=8541,Text='另一条笔记上写着“最终的仪式开始了，如果成功，女神之手将成为世界的主宰！”',}",
  [8542] = "{id=8542,Text='看起来我们的时间不多了，霍格就在不远处，快换上伪装！',Speaker=3223,}",
  [8543] = "{id=8543,Text='最终仪式已经开始，不准打扰！',Speaker=3227,}",
  [8544] = "{id=8544,Text='我有解决仪式不稳定的办法',}",
  [8545] = "{id=8545,Text='是吗?那还慢吞吞的干什么？赶快进去',Speaker=3227,}",
  [8546] = "{id=8546,Text='什么！一个想要造反的信徒？',Speaker=3227,}",
  [8547] = "{id=8547,Text='是你！可恶啊！',Speaker=3227,}",
  [8548] = "{id=8548,Text='冒险者，当你到达深处后，要不惜一切待机打断正在吟唱的祭祀，拜托了，冒险者',Speaker=3223,}",
  [8549] = "{id=8549,Text='住手，无知的冒险者！',Speaker=3228,}",
  [8550] = "{id=8550,Text='打断仪式会造成不堪设想的后果！',Speaker=3228,}",
  [8551] = "{id=8551,Text='无知的人类！你们是无法想象你们正在对抗的是一个多么神圣的存在！',Speaker=3228,}",
  [8552] = "{id=8552,Text='最终仪式失败了，你就自己尝尝恶果吧！',Speaker=3228,}",
  [8553] = "{id=8553,Text='冒险者，这里变得越来越不稳定，我会释放群体传送术，请准备好',Speaker=3225,}",
  [8554] = "{id=8554,Text='是吗？我们会继续调查这个神秘的组织，冒险者，你做的非常好',Speaker=1024,}",
  [8555] = "{id=8555,Text='请回到你的导师那里，你将获得属于你的奖励',Speaker=1024,}",
  [8556] = "{id=8556,Text='果然你配上的十字刺客的称号！你的传奇正在慢慢的谱写，作为你的导师我感到非常骄傲',Speaker=1103,}",
  [8557] = "{id=8557,Text='暗影为你解锁了职业头饰，你可以去微笑小姐那里购买象征荣耀的职业头饰了！',Speaker=1103,}",
  [8558] = "{id=8558,Text='呀~这位客人，您想要邀请的心仪之人目前并不处于我们这个次元哦~想要在一起的话就先打破次元壁吧！',Speaker=1182,}",
  [8726] = "{id=8726,Text='不要太心急，稍等一下，制作一瓶出色的香水是需要时间的。',Speaker=3287,}",
  [8735] = "{id=8735,Text='闻到香味的同时，会让你看到的事物也变得美好一些。',Speaker=3287,}",
  [8743] = "{id=8743,Text='不懂的尊敬大海的人就没有资格驾驭海的力量。年轻人，你感受过深海的恐惧吗？',Speaker=3074,}",
  [8744] = "{id=8744,Text='嘘…你有听到大地的呼吸声吗？来自原始的那股力量正充盈着整个森林。',Speaker=3075,}",
  [8766] = "{id=8766,Text='你必须多加小心，冒险者。到处都是敌人。',Speaker=1567,}",
  [8782] = "{id=8782,Text='不过你要小心啊，天使波利也是很厉害的！这样吧，我教你一个“[c][ffff00]紧急治疗[-][/c]”的技能，嗯……好了，你在你的[c][ffff00]冒险技能[-][/c]中就可以看到这个技能了！快去吧，试试效果！',Speaker=1043,}",
  [8797] = "{id=8797,Text='这么快就回来了？让我来看看你带回来的材料。',Speaker=3288,}",
  [8801] = "{id=8801,Text='天啊，竟然还是这么快！快让我清点一下材料。',Speaker=3288,}",
  [8805] = "{id=8805,Text='很好，让我清点一下材料。',Speaker=3288,}",
  [8819] = "{id=8819,Text='要打开仓库了呢，谢谢您的使用！',Speaker=1679,Option='{好的,2}{下次吧,1}',Emoji=6,Action={actionid=34,num=1},}",
  [8820] = "{id=8820,Text='要打开仓库了呢，谢谢您的使用！',Speaker=1680,Option='{好的,2}{下次吧,1}',Emoji=6,Action={actionid=34,num=1},}",
  [8821] = "{id=8821,Text='要打开仓库了呢，谢谢您的使用！',Speaker=1681,Option='{好的,2}{下次吧,1}',Emoji=6,Action={actionid=34,num=1},}",
  [8823] = "{id=8823,Text='[c][ffff00]卡普拉公司[-][/c]先进的物流技术，可以让您存储的物品在任何地方取用，只要找到[c][ffff00]卡普拉小姐[-][/c]，就能拿到您想要的东西，安全快捷，请放心利用！',Speaker=1679,}",
