  [8836] = "{id=8836,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=1269,Option='知道了！',}",
