  [8845] = "{id=8845,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=1681,Option='知道了！',}",
  [8846] = "{id=8846,Text='进行储存服务手续…好了，确认现在的储存位置，您可以安心进行冒险了！',Speaker=1681,}",
  [8847] = "{id=8847,Text='他可是非常宝贝他的拉比丝呢，你可能需要尽快帮他找到。',Speaker=1187,}",
  [8848] = "{id=8848,Text='（小声）如果不赶快处理的话，以后快递费可就没有折扣了，这可很伤脑筋呢！',Speaker=1187,Option='你说什么？',Emoji=23,}",
  [8851] = "{id=8851,Text='普隆德拉的天空永远美得像一幅画一样，不是吗~',Speaker=1217,}",
  [8890] = "{id=8890,Text='吱吱吱…',Speaker=1423,}",
  [8927] = "{id=8927,Text='想要体验一下翱翔天际的感觉吗？找我就对了！',Speaker=1561,}",
  [8952] = "{id=8952,Text='等等，你就这样去那些危险的地方冒险吗？我建议你还是准备一下比较好。',Speaker=1118,}",
  [8954] = "{id=8954,Text='那么，问题来了！你知道怎么可以找到[c][ffff00]波伊[-][/c]吗？',Speaker=1188,}",
  [8955] = "{id=8955,Text='那么，问题来了！你知道怎么可以找到[c][ffff00]班尼[-][/c]吗？',Speaker=1187,Option='{我不知道,2},{当然知道,3}',}",
  [8959] = "{id=8959,Text='很高兴见到你，冒险者~',Speaker=1265,}",
  [8960] = "{id=8960,Text='很高兴见到你，冒险者~',Speaker=1266,}",
  [8961] = "{id=8961,Text='很高兴见到你，冒险者~',Speaker=1267,}",
  [8962] = "{id=8962,Text='很高兴见到你，冒险者~',Speaker=1268,}",
  [8964] = "{id=8964,Text='恩？你看起来很没精神呢！果然你需要一个本店新推出的[c][ffff00]暖身料理[-][/c]，我们现在免费试吃哦~',Speaker=1265,}",
  [8965] = "{id=8965,Text='恩？你看起来很没精神呢！果然你需要一个本店新推出的[c][ffff00]暖身料理[-][/c]，我们现在免费试吃哦~',Speaker=1266,}",
  [8966] = "{id=8966,Text='恩？你看起来很没精神呢！果然你需要一个本店新推出的[c][ffff00]暖身料理[-][/c]，我们现在免费试吃哦~',Speaker=1267,}",
  [8967] = "{id=8967,Text='恩？你看起来很没精神呢！果然你需要一个本店新推出的[c][ffff00]暖身料理[-][/c]，我们现在免费试吃哦~',Speaker=1268,}",
  [8969] = "{id=8969,Text='那么现在的你，看起来暖洋洋的，祝你冒险愉快咯！~',Speaker=1265,}",
  [8970] = "{id=8970,Text='那么现在的你，看起来暖洋洋的，祝你冒险愉快咯！~',Speaker=1266,}",
  [8971] = "{id=8971,Text='那么现在的你，看起来暖洋洋的，祝你冒险愉快咯！~',Speaker=1267,}",
  [8972] = "{id=8972,Text='那么现在的你，看起来暖洋洋的，祝你冒险愉快咯！~',Speaker=1268,}",
  [8979] = "{id=8979,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=1015,}",
  [8980] = "{id=8980,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=1269,}",
  [8981] = "{id=8981,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=1679,}",
  [8982] = "{id=8982,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=1680,}",
  [8983] = "{id=8983,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=1681,}",
  [8986] = "{id=8986,Text='好吧，但愿不会失败太多次，否则我的魔力恐怕会消耗殆尽…那么现在，我们进入梦境吧！',Speaker=1326,}",
  [9002] = "{id=9002,Text='不过免费的试吃只有一次哦，你想现在品尝吗？',Speaker=1265,Option='{立刻就要吃,2},{等会再来吃,7}',}",
  [9003] = "{id=9003,Text='不过免费的试吃只有一次哦，你想现在品尝吗？',Speaker=1266,Option='{立刻就要吃,2},{等会再来吃,7}',}",
  [9004] = "{id=9004,Text='不过免费的试吃只有一次哦，你想现在品尝吗？',Speaker=1267,Option='{立刻就要吃,2},{等会再来吃,7}',}",
  [9005] = "{id=9005,Text='不过免费的试吃只有一次哦，你想现在品尝吗？',Speaker=1268,Option='{立刻就要吃,2},{等会再来吃,7}',}",
  [9007] = "{id=9007,Text='看来你很满意本店的[c][ffff00]暖身料理[-][/c]啊，是不是要打包一份呢？只需要[c][ffff00]5000zeny[-][/c]哦？',Speaker=1265,Option='{要！！！,3},{下次吧,5}',}",
  [9008] = "{id=9008,Text='看来你很满意本店的[c][ffff00]暖身料理[-][/c]啊，是不是要打包一份呢？只需要[c][ffff00]5000zeny[-][/c]哦？',Speaker=1266,Option='{要！！！,3},{下次吧,5}',}",
  [9009] = "{id=9009,Text='看来你很满意本店的[c][ffff00]暖身料理[-][/c]啊，是不是要打包一份呢？只需要[c][ffff00]5000zeny[-][/c]哦？',Speaker=1267,Option='{要！！！,3},{下次吧,5}',}",
  [9010] = "{id=9010,Text='看来你很满意本店的[c][ffff00]暖身料理[-][/c]啊，是不是要打包一份呢？只需要[c][ffff00]5000zeny[-][/c]哦？',Speaker=1268,Option='{要！！！,3},{下次吧,5}',}",
  [9012] = "{id=9012,Text='随时欢迎你再来哦，免费的试吃随时为你准备',Speaker=1265,}",
  [9013] = "{id=9013,Text='随时欢迎你再来哦，免费的试吃随时为你准备',Speaker=1266,}",
  [9014] = "{id=9014,Text='随时欢迎你再来哦，免费的试吃随时为你准备',Speaker=1267,}",
  [9015] = "{id=9015,Text='随时欢迎你再来哦，免费的试吃随时为你准备',Speaker=1268,}",
  [9017] = "{id=9017,Text='你的钱不够哦，欢迎下次光临…',Speaker=1265,}",
  [9018] = "{id=9018,Text='你的钱不够哦，欢迎下次光临…',Speaker=1266,}",
  [9019] = "{id=9019,Text='你的钱不够哦，欢迎下次光临…',Speaker=1267,}",
  [9020] = "{id=9020,Text='你的钱不够哦，欢迎下次光临…',Speaker=1268,}",
  [9062] = "{id=9062,Text='这两种魔物都异常强大，你如果要去寻找这种材料，我建议你多请一些帮手。',Speaker=1228,}",
  [9067] = "{id=9067,Text='制作中…',Speaker=1228,}",
  [9114] = "{id=9114,Text='很好，让我清点一下材料。',Speaker=3292,}",
  [9117] = "{id=9117,Text='真是没办法呢！冒险者你实在是太优秀了，这么简单就完成了考核！',Speaker=3292,}",
  [9118] = "{id=9118,Text='这是你的考核证明，拿去给索罗·图克吧。他会为你办理晋级事宜的,我还会在这里修养一段时间。',Speaker=3292,}",
  [9124] = "{id=9124,Text='冒险者你回来得这么快，让我清点一下材料吧！',Speaker=1228,}",
  [9136] = "{id=9136,Text='那么它的颜色是',Speaker=3295,Option='{绿色,0},{粉色,0},{黄色,0},{白色,0},{紫色,0},{灰色,0},{红色,0}',}",
  [9138] = "{id=9138,Text='那么它佩戴的头饰是',Speaker=3295,Option='{紫色发蝶,0},{天使发圈,0},{红色小发带,0},{恶魔发圈,0},{花冠,0},{星星发夹,0},{护士帽,0}',}",
  [9284] = "{id=9284,Text='冒险者，我们了解到这个组织正在这里通过一些黑暗的魔法转化这里的不死魔物',Speaker=3220,}",
  [9285] = "{id=9285,Text='我们需要搞清楚他们的目的，并且立刻阻止他们的“仪式”',Speaker=3220,}",
  [9286] = "{id=9286,Text='这的任务非常危险，我需要你们与导师们互相配合',Speaker=3220,}",
  [9287] = "{id=9287,Text='伊丝米儿已经潜入深处，请赶快过去与她会和',Speaker=3220,}",
  [9288] = "{id=9288,Text='骑士们救出了他们仪式所需要的孩子们，神射手们把那边被转化的魔物消灭了',Speaker=3223,}",
  [9289] = "{id=9289,Text='而我们要做的就是击败那个守在路口的人，霍格，我想你曾经应该见过他',Speaker=3223,}",
  [9290] = "{id=9290,Text='我曾经在吉芬见到他时，不曾感受到如此的魔力，正面与他交锋一定不是个聪明的办法',Speaker=3223,}",
  [9291] = "{id=9291,Text='我在西边发现一些情报员，袭击他们，获取关于仪式的情报，换上他们的衣服，骗过霍格后，一口气干掉他',Speaker=3223,}",
  [9292] = "{id=9292,Text='一条笔记上模糊的写着“仪式任然不成熟，我们需要更强大的魔法才能控制哪些强大的不死魔物”',}",
  [9293] = "{id=9293,Text='另一条笔记上写着“最终的仪式开始了，如果成功，女神之手将成为世界的主宰！”',}",
  [9294] = "{id=9294,Text='看起来我们的时间不多了，霍格就在不远处，快换上伪装！',Speaker=3223,}",
  [9295] = "{id=9295,Text='最终仪式已经开始，不准打扰！',Speaker=3227,}",
  [9296] = "{id=9296,Text='我有解决仪式不稳定的办法',}",
  [9297] = "{id=9297,Text='是吗?那还慢吞吞的干什么？赶快进去',Speaker=3227,}",
  [9298] = "{id=9298,Text='什么！一个想要造反的信徒？',Speaker=3227,}",
  [9299] = "{id=9299,Text='是你！可恶啊！',Speaker=3227,}",
  [9300] = "{id=9300,Text='冒险者，当你到达深处后，要不惜一切待机打断正在吟唱的祭祀，拜托了，冒险者',Speaker=3223,}",
  [9301] = "{id=9301,Text='住手，无知的冒险者！',Speaker=3228,}",
  [9302] = "{id=9302,Text='打断仪式会造成不堪设想的后果！',Speaker=3228,}",
  [9303] = "{id=9303,Text='无知的人类！你们是无法想想你们正在对抗的是一个多么神圣的存在！',Speaker=3228,}",
  [9304] = "{id=9304,Text='最终仪式失败了，你就自己尝尝恶果吧！',Speaker=3228,}",
  [9305] = "{id=9305,Text='冒险者，这里变得越来越不稳定，我会释放群体传送术，请准备好',Speaker=3225,}",
  [9306] = "{id=9306,Text='是吗？我们会继续调查这个神秘的组织，冒险者，你做的非常好',Speaker=1024,}",
  [9307] = "{id=9307,Text='请回到你的导师那里，你将获得属于你的奖励',Speaker=1024,}",
  [9308] = "{id=9308,Text='果然你配上的十字刺客的称号！你的传奇正在慢慢的谱写，作为你的导师我感到非常骄傲',Speaker=1103,}",
  [9309] = "{id=9309,Text='暗影为你解锁了职业头饰，你可以去微笑小姐那里购买象征荣耀的职业头饰了！',Speaker=1103,}",
  [9310] = "{id=9310,Text='冒险者，我们了解到这个组织正在这里通过一些黑暗的魔法转化这里的不死魔物',Speaker=3220,}",
  [9311] = "{id=9311,Text='我们需要搞清楚他们的目的，并且立刻阻止他们的“仪式”',Speaker=3220,}",
  [9312] = "{id=9312,Text='这的任务非常危险，我需要你们与导师们互相配合',Speaker=3220,}",
  [9313] = "{id=9313,Text='我们在西边发现一些被绑架的孩子，请赶快救出他们',Speaker=3220,}",
  [9314] = "{id=9314,Text='请尽快干掉那些信徒，防止孩子们发生危险',Speaker=3220,}",
  [9315] = "{id=9315,Text='谢谢你骑士领主，这些孩子受伤了，他们必须马上接受治疗',Speaker=3225,}",
  [9316] = "{id=9316,Text='神官们已经准备就绪了，骑士领主请前往东边与休朗克汇合',Speaker=3225,}",
  [9317] = "{id=9317,Text='伊丝米儿已经带着十字刺客潜入深处了，我们必须抓紧时间',Speaker=3221,}",
  [9318] = "{id=9318,Text='大厅的信徒越来越多了，我们必须正面对抗他们，压制他们，阻止他们集结',Speaker=3221,}",
  [9319] = "{id=9319,Text='快到我这里来，骑士，不要站在那些尸体的身边',Speaker=3225,}",
  [9320] = "{id=9320,Text='根据十字刺客的情报，这些死去的信徒会被转化成“另一种存在”',Speaker=3225,}",
  [9321] = "{id=9321,Text='神官们，到你们大显身手的时候了！',Speaker=3225,}",
  [9322] = "{id=9322,Text='果然你配上的骑士领主的称号！你的传奇正在慢慢的谱写，作为你的导师我感到非常骄傲',Speaker=3221,}",
  [9323] = "{id=9323,Text='勇气为你解锁了职业头饰，你可以去微笑小姐那里购买象征荣耀的职业头饰了！',Speaker=3221,}",
  [9324] = "{id=9324,Text='冒险者，我们了解到这个组织正在这里通过一些黑暗的魔法转化这里的不死魔物',Speaker=3220,}",
  [9325] = "{id=9325,Text='我们需要搞清楚他们的目的，并且立刻阻止他们的“仪式”',Speaker=3220,}",
  [9326] = "{id=9326,Text='这的任务非常危险，我需要你们与导师们互相配合',Speaker=3220,}",
  [9327] = "{id=9327,Text='请找到位于金字塔二层东南方向的杜赫塔，他遇到了一些麻烦',Speaker=3220,}",
  [9328] = "{id=9328,Text='这是我有生以来遇到过的最诡异的魔法力量，它是如此的沉重与邪恶',Speaker=3222,}",
  [9329] = "{id=9329,Text='我必须立刻阻止这个恶魔的转化，如果转化成功了，后果不堪设想',Speaker=3222,}",
  [9330] = "{id=9330,Text='我曾经听雷藏老师提到过类似的情况，冒险者，我必须尝试一下',Speaker=3222,}",
  [9331] = "{id=9331,Text='在突袭这里的时候，我在东边发现一些转化失败的魔物',Speaker=3222,}",
  [9332] = "{id=9332,Text='请用冰系魔法冻结一部分残余的转化魔力，我得借用一下这些恶魔的力量',Speaker=3222,}",
  [9333] = "{id=9333,Text='只有一瞬间，把握机会超魔导士们',Speaker=3222,}",
  [9334] = "{id=9334,Text='我们耗尽了魔力，冒险者剩下的就交给你了，击败这个生物',Speaker=3222,}",
  [9335] = "{id=9335,Text='干的很好！事情有了进展',Speaker=3222,}",
  [9336] = "{id=9336,Text='就在刚才，伊丝米儿发送了信号给我，通道入口的邪恶法师被干掉了',Speaker=3222,}",
  [9337] = "{id=9337,Text='请尽快进入中央通道阻止仪式的进行',Speaker=3222,}",
  [9338] = "{id=9338,Text='果然你配上的超魔导士的称号！你的传奇正在慢慢的谱写，作为你的导师我感到非常骄傲',Speaker=3222,}",
  [9339] = "{id=9339,Text='元素为你解锁了职业头饰，你可以去微笑小姐那里购买象征荣耀的职业头饰了！',Speaker=3222,}",
  [9340] = "{id=9340,Text='冒险者，我们了解到这个组织正在这里通过一些黑暗的魔法转化这里的不死魔物”',Speaker=3220,}",
  [9341] = "{id=9341,Text='我们需要搞清楚他们的目的，并且立刻阻止他们的“仪式”',Speaker=3220,}",
  [9342] = "{id=9342,Text='这的任务非常危险，我需要你们与导师们互相配合',Speaker=3220,}",
  [9343] = "{id=9343,Text='骑士领主们救出了一批孩子，只是他们都很虚弱了',Speaker=3220,}",
  [9344] = "{id=9344,Text='请立刻找到那些孩子们并且治愈他们，他们就在西边，和骑士领主们在一起',Speaker=3220,}",
  [9345] = "{id=9345,Text='我们需要立刻治疗这些孩子，他们的生命力正在衰退',Speaker=3225,}",
  [9346] = "{id=9346,Text='做的很好，冒险者！',Speaker=3225,}",
  [9347] = "{id=9347,Text='东边的骑士领主可能会遇到些麻烦，请赶快过来与我汇合',Speaker=3225,}",
  [9348] = "{id=9348,Text='我在这些信徒的身上发现了一些不太好的情况',Speaker=3225,}",
  [9349] = "{id=9349,Text='小心冒险者！',Speaker=3225,}",
  [9350] = "{id=9350,Text='那是从信徒转化而来的不死魔物，净化他们！神官！',Speaker=3225,}",
  [9351] = "{id=9351,Text='做的很好！事情有了新的进展',Speaker=3225,}",
  [9352] = "{id=9352,Text='就在刚才，伊丝米儿发送了信号给我，通道入口的邪恶法师被干掉了',Speaker=3225,}",
  [9353] = "{id=9353,Text='请尽快进入中央通道阻止仪式的进行',Speaker=3225,}",
  [9354] = "{id=9354,Text='果然你配上的神官的称号！你的传奇正在慢慢的谱写，作为你的导师我感到非常骄傲',Speaker=3225,}",
  [9355] = "{id=9355,Text='圣光为你解锁了职业头饰，你可以去微笑小姐那里购买象征荣耀的职业头饰了！',Speaker=3225,}",
  [9356] = "{id=9356,Text='冒险者，我们了解到这个组织正在这里通过一些黑暗的魔法转化这里的不死魔物',Speaker=3224,}",
  [9357] = "{id=9357,Text='我们需要搞清楚他们的目的，并且立刻阻止他们的“仪式”',Speaker=3224,}",
  [9358] = "{id=9358,Text='这的任务非常危险，我需要你们与导师们互相配合',Speaker=3224,}",
  [9359] = "{id=9359,Text='卡巴克在骑士领主的帮助下突袭了左侧的祭坛，可是他似乎在那里遇到了一些麻烦',Speaker=3224,}",
  [9360] = "{id=9360,Text='冒险者，他就在金字塔二层的西南边，请立刻赶去与他汇合',Speaker=3224,}",
  [9361] = "{id=9361,Text='冒险者，我们遇到了一些强大的魔物，看到那些被转化的米诺斯了吗？',Speaker=3224,}",
  [9362] = "{id=9362,Text='我们得尽快消灭他们，如果十字刺客遇到这些米诺斯那可就糟糕了',Speaker=3224,}",
  [9363] = "{id=9363,Text='这些被转化的魔物力量非常强大，我们得先布置一些陷阱，正面对抗他们也不是一个明智的选择',Speaker=3224,}",
  [9364] = "{id=9364,Text='请按照我给你的指使，把陷阱布置在周围',Speaker=3224,}",
  [9365] = "{id=9365,Text='很好，但即使是有了那些陷阱你任然不能掉以轻心',Speaker=3224,}",
  [9366] = "{id=9366,Text='记住，那些魔物的行动非常缓慢，但是一定不能被接触到',Speaker=3224,}",
  [9367] = "{id=9367,Text='做的很好！事情有了新的进展',Speaker=3224,}",
  [9368] = "{id=9368,Text='就在刚才，伊丝米儿发送了信号给我，通道入口的邪恶法师被干掉了',Speaker=3224,}",
  [9369] = "{id=9369,Text='请尽快进入中央通道阻止仪式的进行',Speaker=3224,}",
  [9370] = "{id=9370,Text='果然你配上的神射手的称号！你的传奇正在慢慢的谱写，作为你的导师我感到非常骄傲',Speaker=3224,}",
  [9371] = "{id=9371,Text='微风为你解锁了职业头饰，你可以去微笑小姐那里购买象征荣耀的职业头饰了！',Speaker=3224,}",
  [9381] = "{id=9381,Text='沙蜂部队是由一些沙漠的原住民组成的自卫部队，是这里唯一拥有战斗能力的组织。',Speaker=3324,}",
  [9382] = "{id=9382,Text='虽然只有20人不到，但是仍然保护着留在苏克拉沙漠中的住民，为了安全起见沙蜂部队的成员每天也只会被安排到2个危险的任务。',Speaker=3324,}",
  [9723] = "{id=9723,Text='冒险者吗，我们已经削弱了这只魔物，请立刻击败它',Speaker=3222,}",
  [9755] = "{id=9755,Text='从右边的传送点出去就可以找到休朗克，快去，他需要支援！',Speaker=3220,}",
  [9801] = "{id=9801,Text='去点首歌吧！',Speaker=2647,}",
  [9802] = "{id=9802,Text='看来你已经点好了呢。',Speaker=2647,}",
  [10001] = "{id=10001,Text='嗯？好像有什么东西过来了！',Emoji=0,}",
  [10002] = "{id=10002,Text='好像还有魔物！',Emoji=0,}",
  [10011] = "{id=10011,Text='呜哇~可恶的人类！快溜！',Speaker=1055,Emoji=0,}",
  [10012] = "{id=10012,Text='够笨的，你有翅膀却不会飞吗?',Emoji=0,}",
  [10013] = "{id=10013,Text='你看我的身材可以飞吗？！更何况人家只是戴了[c][ffff00]天使发圈[-][/c]而已，根本不是天使波利，你认错了啦！',Speaker=1055,Emoji=1,}",
  [10014] = "{id=10014,Text='那…哪里可以找到[c][ffff00]天使波利[-][/c]？',Emoji=10,}",
  [10015] = "{id=10015,Text='人家才不会告诉你~哼，可恶的人类！赶紧溜~',Speaker=1055,Emoji=0,}",
  [10016] = "{id=10016,Text='等一下！…你的[c][ffff00]天使发圈[-][/c]样子不错，可以借我戴下吗？',Emoji=0,}",
  [10017] = "{id=10017,Text='…滚开！',Speaker=1055,Emoji=1,}",
  [10051] = "{id=10051,Text='我是你的引导者，你愿意接受[c][ffff00]元素的指引[-][/c]吗？',Speaker=1102,Emoji=0,}",
  [10052] = "{id=10052,Text='接受元素的指引，你将得到元素的庇佑，操纵一切[c][ffff00]元素之力[-][/c]。',Speaker=1102,Option='成为[c][ffff00]魔法师[-][/c]！',Emoji=0,}",
  [10053] = "{id=10053,Text='有意思，你想成为[c][ffff00]盗贼[-][/c]？',Speaker=1103,Emoji=0,}",
  [10054] = "{id=10054,Text='[c][ffff00]反应、闪躲、高速[-][/c]，这些是盗贼必备的素质，准备好了吗？',Speaker=1103,Option='成为[c][ffff00]盗贼[-][/c]！',Emoji=0,}",
  [10055] = "{id=10055,Text='隐藏在大自然中的[c][ffff00]猎杀者[-][/c]，听起来怎么样？加入我们吧！',Speaker=1104,Emoji=0,}",
  [10056] = "{id=10056,Text='在[c][ffff00]远距离击败[-][/c]对手就是我们弓箭手的[c][ffff00]特点[-][/c]，你也可以做到这些。',Speaker=1104,Option='成为[c][ffff00]弓箭手[-][/c]！',Emoji=0,}",
  [10057] = "{id=10057,Text='我们都是[c][ffff00]神的侍从[-][/c]，沐浴着圣母的恩赐，并传播给世人。来我们身边吧，我的朋友。',Speaker=1105,Emoji=0,}",
  [10058] = "{id=10058,Text='[c][ffff00]侍奉神圣的信仰[-][/c]，是我们为之奋斗一生的伟大职业。我的朋友，你准备好了吗？',Speaker=1105,Option='成为[c][ffff00]服事[-][/c]！',Emoji=0,}",
  [10059] = "{id=10059,Text='很不错的年轻人，你看起来就很有经商的头脑，怎么样？要不要一起[c][ffff00]创造财富[-][/c]？',Speaker=1106,Emoji=0,}",
  [10060] = "{id=10060,Text='拥有坚强的体魄、出色的战力和灵活的头脑，才能成为一个优秀的[c][ffff00]商人[-][/c]。加入我们，这笔买卖肯定不亏！',Speaker=1106,Option='成为[c][ffff00]商人[-][/c]！',Emoji=0,}",
  [550063] = "{id=550063,Text='让我们来看看，会发生什么呢？',Speaker=802235,}",
  [550064] = "{id=550064,Text='里希塔乐镇站到了，请乘客们有序离开。',Speaker=802238,}",
  [550065] = "{id=550065,Text='呼~终于到了！',Speaker=802236,}",
  [550066] = "{id=550066,Text='这里就是里希塔乐镇啊~真是个富足的地方。',Speaker=802267,}",
  [550067] = "{id=550067,Text='在这里，一定能赚很多钱吧！',Speaker=802267,Emoji=13,}",
  [550068] = "{id=550068,Text='娣洁你真是……诶？那不是赛尼亚吗？',Speaker=802265,}",
  [550069] = "{id=550069,Text='嘿！赛尼亚~~~~~',Speaker=802265,}",
  [550070] = "{id=550070,Text='赛尼亚~好久不见！',Speaker=802267,Emoji=17,}",
  [550071] = "{id=550071,Text='庞德！娣洁！你们怎么会在这？',Speaker=802234,}",
  [550072] = "{id=550072,Text='我们是收到了雷根贝勒公司的邀请，来这里参观雷根贝勒公司的总部。',Speaker=802265,}",
  [550073] = "{id=550073,Text='雷根贝勒的邀请函？',Speaker=802234,}",
  [550074] = "{id=550074,Text='不如我们一起去雷根贝勒的总部看看情况吧。',Speaker=802234,}",
  [550075] = "{id=550075,Text='好呀好呀！~',Speaker=802267,}",
  [550076] = "{id=550076,Text='当然可以。',Speaker=802265,}",
  [550077] = "{id=550077,Text='利力！',Speaker=802234,}",
  [550078] = "{id=550078,Text='嘎！',Speaker=802252,}",
  [550079] = "{id=550079,Text='利力，我不想让赛依莲哥哥担心，你替我把信送给他吧。',Speaker=802234,}",
  [550080] = "{id=550080,Text='嘎嗷~',Speaker=802252,Emoji=26,}",
  [550081] = "{id=550081,Text='那我们出发吧！',Speaker=802234,}",
  [550082] = "{id=550082,Text='这么好玩的事居然不叫上我！',Speaker=802262,}",
  [550083] = "{id=550083,Text='不管他们了！我也要好好享受我的假期了！',Speaker=802262,}",
  [550115] = "{id=550115,Text='雷根贝勒公司可真有钱！招待室都这么华丽~',Speaker=802267,}",
  [550116] = "{id=550116,Text='你说是不是呀？庞德？',Speaker=802267,Option='庞德？我？',}",
  [550117] = "{id=550117,Text='对啊……你怎么了？怎么魂不守舍的……',Speaker=802267,}",
  [550118] = "{id=550118,Text='外面这是怎么了？怎么有这么大的烟雾？',Speaker=802267,}",
  [550119] = "{id=550119,Text='（小声）赛依连哥哥他们没事吧……',Speaker=802263,}",
  [550120] = "{id=550120,Text='我们还是趁早离开吧，我担心会牵扯进什么事情里。',Speaker=802267,}",
  [550121] = "{id=550121,Text='天哪！你们看外面！有什么从地下飞上来了！',Speaker=802267,}",
  [550122] = "{id=550122,Text='庞德，快用你刚刚学会了新魔法暗之壁障保护我们！',Speaker=802267,}",
  [550123] = "{id=550123,Text='庞德你真是越来越厉害了！',Speaker=802263,}",
  [550124] = "{id=550124,Text='实在不好意思，让各位受惊了。',Speaker=802240,}",
  [550125] = "{id=550125,Text='我司位于地下的研究所出了一些小小的事故。',Speaker=802240,}",
  [550126] = "{id=550126,Text='那么，我们的参观计划会受到影响吗？',Speaker=802263,}",
  [550127] = "{id=550127,Text='请放心，我们现在可以开始本次的参观活动了。',Speaker=802240,}",
  [550128] = "{id=550128,Text='那……我们可以现在离开么？',Speaker=802263,}",
  [550129] = "{id=550129,Text='当然，如果诸位想离开的话，随时可以从旁边的贵客通道离开.....',Speaker=802240,}",
  [550130] = "{id=550130,Text='（低声）我们快离开这里。',Speaker=802263,}",
  [550131] = "{id=550131,Text='新的时代马上就要拉开序幕了……',Speaker=802240,}",
  [550134] = "{id=550134,Text='这里怎么阴森森的？',Speaker=802294,}",
  [550135] = "{id=550135,Text='是啊，我总觉得有些不安。',Speaker=802293,}",
  [550136] = "{id=550136,Text='呀！这是什么？！',Speaker=802293,}",
  [550137] = "{id=550137,Text='它们好像是冲我们来的！',Speaker=802294,}",
  [550138] = "{id=550138,Text='娣洁！快点！跑起来！',Speaker=802293,}",
  [550139] = "{id=550139,Text='娣洁！！！！！',Speaker=802293,}",
  [550140] = "{id=550140,Text='你们好呀，冒险者们。',Speaker=802254,}",
  [550141] = "{id=550141,Text='你是谁？',Speaker=802234,}",
  [550142] = "{id=550142,Text='是我宝勒世伏大人的秘书，雪依·苏丽娥。',Speaker=802254,}",
  [550143] = "{id=550143,Text='！！！！',Speaker=802293,}",
  [550144] = "{id=550144,Text='娣洁！庞德！快逃！',Speaker=802293,}",
  [550145] = "{id=550145,Text='想逃？一个都别想走！',Speaker=802254,}",
  [550146] = "{id=550146,Text='上吧！宝贝们！把他们献给宝勒世伏大人！',Speaker=802254,}",
  [550147] = "{id=550147,Text='哦？还有点本事。',Speaker=802254,}",
  [550148] = "{id=550148,Text='不过，也就到此为止了！',Speaker=802254,}",
  [550149] = "{id=550149,Text='是……是毒气……',Speaker=802294,}",
  [550150] = "{id=550150,Text='屏住呼吸！！',Speaker=802293,}",
  [550151] = "{id=550151,Text='庞德！！咳咳……咳咳咳咳咳…………',Speaker=802293,}",
  [550152] = "{id=550152,Text='别伤害……我的……伙伴……们……',Speaker=802293,}",
  [550153] = "{id=550153,Text='小妹妹，你自己都保护不了自己了，就别担心别人了。',Speaker=802254,}",
  [550154] = "{id=550154,Text='咳咳咳……咳咳……',Speaker=802293,Option='赛尼亚！！！！',}",
  [550155] = "{id=550155,Text='动作快些，把他们带去地下研究所。',Speaker=802254,}",
  [550156] = "{id=550156,Text='是！',Speaker=802257,}",
  [550157] = "{id=550157,Text='你的意识逐渐模糊，陷入了昏迷之中。',}",
  [550159] = "{id=550159,Text='这里是……哪里……？',}",
  [550160] = "{id=550160,Text='庞德和娣洁紧闭双眼，衣服被拉开，胸口的皮肤有一道被缝合的伤疤。',}",
  [550161] = "{id=550161,Text='唔……赛尼亚……',Speaker=802267,}",
  [550162] = "{id=550162,Text='赛尼亚！你和庞德的胸口怎么都有一道伤疤？',Speaker=802267,Option='你也是',}",
  [550163] = "{id=550163,Text='这是怎么回事！？',Speaker=802267,}",
  [550164] = "{id=550164,Text='呼……呼……呼……呼……',Speaker=802236,}",
  [550165] = "{id=550165,Text='庞德！你没事吧？ ',Speaker=802267,}",
  [550166] = "{id=550166,Text='喂！庞德！庞德！',Speaker=802267,}",
  [550167] = "{id=550167,Text='啊！',Speaker=802267,Option='娣洁！！！',}",
  [550168] = "{id=550168,Text='唔……赛……尼亚……娣洁……',Speaker=802236,}",
  [550169] = "{id=550169,Text='不能伤害她们！不能……',Speaker=802236,}",
  [550170] = "{id=550170,Text='住手……住手啊……！！！',Speaker=802236,Emoji=37,}",
  [550171] = "{id=550171,Text='呼……呼……呼……',Speaker=802267,Option='娣洁？！',}",
  [550172] = "{id=550172,Text='离开我……赛尼亚……越远……越好……',Speaker=802267,}",
  [550173] = "{id=550173,Text='我……快控制不住……自己了……',Speaker=802267,Option='不！！！',}",
  [550174] = "{id=550174,Text='呵，你们谁也逃不了，思念体们。',Speaker=802254,}",
  [550175] = "{id=550175,Text='雪依大人，男性实验体正往一楼逃窜。',Speaker=802284,}",
  [550176] = "{id=550176,Text='研究所的大火引来了很多不必要的注意。',Speaker=802254,}",
  [550177] = "{id=550177,Text='务必将他抓起来，不要引起骚乱。',Speaker=802254,}",
  [550178] = "{id=550178,Text='是！',Speaker=802284,}",
  [550179] = "{id=550179,Text='将她们两个带进实验罐里，观察变化情况。',Speaker=802254,}",
  [550180] = "{id=550180,Text='是！',Speaker=802284,}",
  [550181] = "{id=550181,Text='快逃……啊……赛尼亚……快……',Speaker=802267,}",
  [550182] = "{id=550182,Text='去告诉……你的哥哥……',Speaker=802267,}",
  [550183] = "{id=550183,Text='雷根贝勒的……阴谋……',Speaker=802267,Option='娣洁！！！！！',}",
  [550184] = "{id=550184,Text='……',Speaker=802267,}",
  [550186] = "{id=550186,Text='在那里！！！',Speaker=802256,}",
  [550187] = "{id=550187,Text='擅闯雷根贝勒公司！',Speaker=802256,}",
  [550188] = "{id=550188,Text='当我们警卫部是空气吗？！',Speaker=802256,}",
  [550189] = "{id=550189,Text='拿下！',Speaker=802256,}",
  [550190] = "{id=550190,Text='哼哼。',Speaker=802256,}",
  [550191] = "{id=550191,Text='不会让你逃走的！',Speaker=802256,}",
  [550192] = "{id=550192,Text='啊……',Speaker=802256,}",
  [550193] = "{id=550193,Text='年轻人，关键时刻，还是需要我吧？',Speaker=802262,Option='摩根！！',}",
  [550194] = "{id=550194,Text='离开这里，去里希塔乐原野。',Speaker=802262,}",
  [550195] = "{id=550195,Text='保护好赛尼亚！',Speaker=802262,}",
  [550196] = "{id=550196,Text='真是鲁莽的年轻人啊！',Speaker=802264,}",
  [550197] = "{id=550197,Text='好好的假期，就被你破坏了！',Speaker=802264,Option='说明情况',}",
  [550198] = "{id=550198,Text='庞德果然已经……',Speaker=802264,}",
  [550199] = "{id=550199,Text='在雷根贝勒公司前台的时候，我也看到了赛尼亚。',Speaker=802264,}",
  [550200] = "{id=550200,Text='当时我就确定，她只是赛尼亚的记忆碎片。',Speaker=802264,Option='你说什么？！',}",
  [550201] = "{id=550201,Text='没错吧？赛尼亚……',Speaker=802264,}",
  [550202] = "{id=550202,Text='这是我教给庞德的记忆魔法。',Speaker=802262,Option='赛尼亚……',}",
  [550203] = "{id=550203,Text='碎片还散发着光芒，里面应该还有着赛尼亚的记忆。',Speaker=802262,}",
  [550205] = "{id=550205,Text='[c][ffff00][PlayerName][-][/c]，你在哪里呀？',Speaker=802234,}",
  [550206] = "{id=550206,Text='这里这里~',Speaker=802234,}",
  [550207] = "{id=550207,Text='你总算来了~',Speaker=802234,}",
  [550208] = "{id=550208,Text='从今天开始！我们就要开始冒险啦！',Speaker=802234,}",
  [550209] = "{id=550209,Text='我好兴奋啊！还等什么！我们快走！',Speaker=802234,}",
  [550210] = "{id=550210,Text='你看你看！这里都是波利诶！',Speaker=802234,}",
  [550211] = "{id=550211,Text='好可爱~~',Speaker=802234,}",
  [550212] = "{id=550212,Text='对了！听说波利喜欢青苹果~',Speaker=802234,}",
  [550213] = "{id=550213,Text='给你一个~',Speaker=802234,}",
  [550214] = "{id=550214,Text='天哪！它跟着我们了！真可爱！',Speaker=802234,}",
  [550215] = "{id=550215,Text='走~我们带你一起去冒险！',Speaker=802234,}",
  [550216] = "{id=550216,Text='赛尼亚，[c][ffff00][PlayerName][-][/c]，谢谢你们~',Speaker=802258,}",
  [550217] = "{id=550217,Text='为了荣耀！',Speaker=802259,}",
  [550218] = "{id=550218,Text='赛尼亚！[c][ffff00][PlayerName][-][/c]！',Speaker=802260,}",
  [550219] = "{id=550219,Text='别忘记时刻训练自己！',Speaker=802261,}",
  [550220] = "{id=550220,Text='呀！是宝雅姐姐和维琪姐姐！',Speaker=802234,}",
  [550221] = "{id=550221,Text='我们要一起努力变成更厉害的冒险者！',Speaker=802236,}",
  [550222] = "{id=550222,Text='赛尼亚，和你一起旅行真的很开心。',Speaker=802237,}",
  [550223] = "{id=550223,Text='赛尼亚~',Speaker=802236,}",
  [550224] = "{id=550224,Text='大家！',Speaker=802234,}",
  [550225] = "{id=550225,Text='我要和赛依连哥哥他们一起离开了~',Speaker=802234,}",
  [550226] = "{id=550226,Text='和你在一起的时间总是过得这么快！',Speaker=802234,}",
  [550227] = "{id=550227,Text='等这次的事情解决好了以后~我们再一起冒险呀！',Speaker=802234,Option='{一起,3},{别走,4}',}",
  [550228] = "{id=550228,Text='我们都有必须完成的事情不是吗？',Speaker=802234,}",
  [550229] = "{id=550229,Text='[c][ffff00][PlayerName][-][/c]你又耍小脾气了呢~',Speaker=802234,}",
  [550230] = "{id=550230,Text='赛尼亚！！',Speaker=802255,}",
  [550231] = "{id=550231,Text='塞壬哥哥……',Speaker=802234,}",
  [550232] = "{id=550232,Text='赛尼亚，走啦！',Speaker=802236,}",
  [550233] = "{id=550233,Text='赛尼亚，快来！',Speaker=802237,}",
  [550234] = "{id=550234,Text='赛尼亚，要出发了！',Speaker=802246,}",
  [550235] = "{id=550235,Text='赛尼亚！~别磨蹭了~快过来！',Speaker=802251,}",
  [550236] = "{id=550236,Text='赛尼亚！不要过去！',Speaker=802255,Option='呼唤赛尼亚',}",
  [550237] = "{id=550237,Text='我也要走了……',Speaker=802234,}",
  [550238] = "{id=550238,Text='再见了，我最喜欢的……大家……',Speaker=802234,}",
  [550239] = "{id=550239,Text='不！！！！',Speaker=802255,}",
  [550240] = "{id=550240,Text='赛尼亚！！！！！！',Speaker=802255,}",
  [550250] = "{id=550250,Text='我只能先把你传送到朱诺，那里的飞空艇管理员可以帮你抵达达纳托斯之塔。',Speaker=803230,Option='知道了！',}",
  [550261] = "{id=550261,Text='哎哟！',Speaker=802276,}",
  [550262] = "{id=550262,Text='未来的冒险女王就是我！',}",
  [550263] = "{id=550263,Text='[c][ffff00][PlayerName][-][/c]，我们一起去冒险~',}",
  [550264] = "{id=550264,Text='将来我一定成为一名伟大的战士！',}",
  [550265] = "{id=550265,Text='有你的陪伴，我很开心~',}",
  [550266] = "{id=550266,Text='事情的真相总是掩埋在虚假之中。',}",
  [550267] = "{id=550267,Text='作为冒险者要有探索精神哦~',}",
  [550268] = "{id=550268,Text='相聚的时间总是短暂的。',}",
  [550269] = "{id=550269,Text='等我回来。',}",
  [550270] = "{id=550270,Text='对不起，我失约了……',}",
  [550271] = "{id=550271,Text='再见了，我最喜欢的……',}",
  [550274] = "{id=550274,Text='想要更厉害的武器来找我啊~',Speaker=802242,}",
  [550275] = "{id=550275,Text='你们要变得更强！',Speaker=802291,}",
  [550278] = "{id=550278,Text='我是……赛尼亚？',}",
  [550279] = "{id=550279,Text='我是……庞德？',}",
  [550280] = "{id=550280,Text='我是……娣洁？',}",
  [550285] = "{id=550285,Text='这里是哪里……？我是……谁……？',}",
  [550289] = "{id=550289,Text='这里是南门？',}",
  [550290] = "{id=550290,Text='是赛尼亚的声音！赛尼亚！赛尼亚！',}",
  [550291] = "{id=550291,Text='赛尼亚~[c][ffff00][PlayerName][-][/c]~',}",
  [550293] = "{id=550293,Text='快跟上来！',}",
  [550294] = "{id=550294,Text='[c][ffff00][PlayerName][-][/c]~',}",
  [550312] = "{id=550312,Text='神佑拉赫，希望你在这里有愉快的旅行！',Speaker=806738,}",
  [550317] = "{id=550317,Text='祝…祝你好运',Speaker=806719,}",
  [550322] = "{id=550322,Text='一路顺风，希望下次见面你可以为我讲卢恩王国的事情呢。',Speaker=806720,Emoji=17,}",
  [550331] = "{id=550331,Text='神佑拉赫，希望你在这里有愉快的旅行！',Speaker=806740,}",
  [550332] = "{id=550332,Text='神佑拉赫，希望你在这里有愉快的旅行！',Speaker=806744,}",
  [550333] = "{id=550333,Text='神佑拉赫，希望你在这里有愉快的旅行！',Speaker=806745,}",
  [550336] = "{id=550336,Text='神佑拉赫，为神殿修剪花卉是我的荣幸。',Speaker=806753,}",
  [550345] = "{id=550345,Text='这是哪…我在哪？',Speaker=806768,}",
  [550346] = "{id=550346,Text='这里修的太难看!把上面也修一修！',Speaker=806768,}",
  [550354] = "{id=550354,Text='晶莹剔透的冰花本是纯洁美好之物，可我为什么却在它们的歌谣中听出了丝丝悲凉呢？',Speaker=1058,}",
  [550355] = "{id=550355,Text='黄土，风沙，与细石。贫瘠的土地，恶劣的环境，冒险者，在这片平原里，你一定要小心……',Speaker=1058,}",
  [550356] = "{id=550356,Text='聆听神之歌颂，颂扬神之荣光，能进入圣域神殿的你必定是被神所认可之人。',Speaker=1058,}",
  [550357] = "{id=550357,Text='欢迎来到最接近神明的城市——拉赫，灵魂的信仰将是拉赫最高的荣誉，愿你在这里可以与神明共舞，享受一场别致的冒险。',Speaker=1058,}",
  [550358] = "{id=550358,Text='拉赫的锻造师真是厉害啊！如此精良的长剑我也是第一次见到！',Speaker=806822,}",
  [550361] = "{id=550361,Text='哎！我昨天看康维的丈夫约克在下城区和乔安在...',Speaker=806827,}",
  [550362] = "{id=550362,Text='偷情对吧？我早知道了！只是苦了小康维丝，她才五岁...',Speaker=806826,}",
  [550363] = "{id=550363,Text='真的吗？那康维姐姐不是很可怜？',Speaker=806825,}",
  [550365] = "{id=550365,Text='求求你们，让我进去，我要见我的父亲！',Speaker=806784,}",
  [550377] = "{id=550377,Text='我觉得你的名字不好听，你改一个名字吧！',Speaker=806828,}",
  [550378] = "{id=550378,Text='你的名字也不好听，你怎么不改呢？',Speaker=806829,}",
  [550379] = "{id=550379,Text='这是我妈妈给我取的！',Speaker=806828,}",
  [550380] = "{id=550380,Text='我的也是妈妈取的！',Speaker=806829,}",
  [550381] = "{id=550381,Text='哼！',Speaker=806829,}",
  [550383] = "{id=550383,Text='我跟你说，最近我听到不少人说圣母....',Speaker=806795,}",
  [550384] = "{id=550384,Text='嘘...小点声...',Speaker=806795,}",
  [550386] = "{id=550386,Text='我真的很喜欢你啊莉莉丝，请接受我吧！',Speaker=806845,}",
  [550387] = "{id=550387,Text='我有点感冒，请别太靠近我！',Speaker=806844,}",
  [550388] = "{id=550388,Text='爸爸怎么还不回来....',Speaker=806824,}",
  [550389] = "{id=550389,Text='神佑拉赫...',Speaker=806766,}",
  [550397] = "{id=550397,Text='那个老头好奇怪!听说好像脑袋有什么问题....',Speaker=806858,}",
  [550398] = "{id=550398,Text='嘘！小点声！',Speaker=806859,}",
  [550401] = "{id=550401,Text='来~看这里……茄子！',Speaker=806870,}",
  [550402] = "{id=550402,Text='神佑拉赫，友人，你知道做什么祈祷可以让头发长出来么？',Speaker=806876,}",
  [550403] = "{id=550403,Text='神佑拉赫，我想神灵应该没有思考过生发这个问题。。。',Speaker=806877,}",
  [550408] = "{id=550408,Text='好了，储存已经顺利完成咯，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=806724,}",
