  [550416] = "{id=550416,Text='[c][ffff00]准它公司[-][/c]最新的物流技术，可以让您存储的物品在任何地方取用，只要找到[c][ffff00]准它公司职员[-][/c]，就能拿到您想要的东西，安全快捷，请放心利用！',Speaker=806857,}",
  [550417] = "{id=550417,Text='准它仓库服务一律免费！还请冒险家们多多支持！',Speaker=806724,}",
  [550418] = "{id=550418,Text='准它仓库服务一律免费！还请冒险家们多多支持！',Speaker=806856,}",
  [550419] = "{id=550419,Text='准它仓库服务一律免费！还请冒险家们多多支持！',Speaker=806857,}",
  [550420] = "{id=550420,Text='现在帮你打开仓库了，本次打开会扣除%sZeny，请好好利用！',Speaker=806724,Option='{打开仓库,2},{下次吧,3}',}",
  [550421] = "{id=550421,Text='现在帮你打开仓库了，本次打开会扣除%sZeny，请好好利用！',Speaker=806856,Option='{打开仓库,2},{下次吧,3}',}",
  [550422] = "{id=550422,Text='现在帮你打开仓库了，本次打开会扣除%sZeny，请好好利用！',Speaker=806857,Option='{打开仓库,2},{下次吧,3}',}",
  [550423] = "{id=550423,Text='[c][ffff00]储存服务[-][/c]是由[c][ffff00]准它公司[-][/c]代替冒险家协会提供的服务，利用[c][ffff00]准它公司[-][/c]的服务网络，方便冒险家使用。',Speaker=806724,}",
  [550424] = "{id=550424,Text='[c][ffff00]储存服务[-][/c]是由[c][ffff00]准它公司[-][/c]代替冒险家协会提供的服务，利用[c][ffff00]准它公司[-][/c]的服务网络，方便冒险家使用。',Speaker=806856,}",
  [550425] = "{id=550425,Text='[c][ffff00]储存服务[-][/c]是由[c][ffff00]准它公司[-][/c]代替冒险家协会提供的服务，利用[c][ffff00]准它公司[-][/c]的服务网络，方便冒险家使用。',Speaker=806857,}",
  [550426] = "{id=550426,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=806724,Option='知道了！',}",
  [550427] = "{id=550427,Text='进行储存服务手续…好了，确认现在的储存位置，您可以安心进行冒险了！',Speaker=806856,}",
  [550428] = "{id=550428,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=806857,Option='知道了！',}",
  [550429] = "{id=550429,Text='进行储存服务手续…好了，确认现在的储存位置，您可以安心进行冒险了！',Speaker=806724,}",
  [550430] = "{id=550430,Text='储存后，[c][ffff00]只要使用蝴蝶翅膀，就可以回到这里[-][/c]，非常方便。不过，出门时请不要忘记携带[c][ffff00]蝴蝶翅膀[-][/c]哦~',Speaker=806856,Option='知道了！',}",
  [550431] = "{id=550431,Text='进行储存服务手续…好了，确认现在的储存位置，您可以安心进行冒险了！',Speaker=806857,}",
  [550432] = "{id=550432,Text='好了，储存已经顺利完成喵，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=806724,}",
  [550433] = "{id=550433,Text='好了，储存已经顺利完成喵，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=806856,}",
  [550434] = "{id=550434,Text='好了，储存已经顺利完成喵，旅途愉快，[c][ffff00][PlayerName][-][/c]！',Speaker=806857,}",
  [550463] = "{id=550463,Text='神佑拉赫！',Speaker=806879,}",
  [550467] = "{id=550467,Text='神灵说只有商人才能接受神的杰作，还是请回吧！',Speaker=806879,}",
  [550480] = "{id=550480,Speaker=806879,}",
  [550491] = "{id=550491,Text='神灵一定会祝福你的~',Speaker=806879,Option='切……',Emoji=20,}",
  [550499] = "{id=550499,Text='克里昂，格里高利可是建立我们国家的先祖。',Speaker=806756,}",
  [550529] = "{id=550529,Text='一定要当心神殿地下那些邪恶妖精，它们长相实在是太可怕了，愿你平安！',Speaker=1016,}",
  [550530] = "{id=550530,Text='南门的粉嫩波利，没想到会适应圣域冰洞的气候进化成为冰波利，可别小瞧了它们！',Speaker=1016,}",
  [550531] = "{id=550531,Text='伊达平原的吃人草会在你放松警惕的时候突然向你攻击，所以切记不要松懈！',Speaker=1016,}",
  [550532] = "{id=550532,Text='很高兴见到你！',Speaker=806746,}",
  [550533] = "{id=550533,Text='恩？你看起来很没精神呢！果然你需要一个本店新推出的[c][ffff00]暖身料理[-][/c]，我这里现在可以免费试吃！',Speaker=806746,}",
  [550534] = "{id=550534,Text='不过免费的试吃只有一次哦，你想现在品尝吗？',Speaker=806746,Option='{立刻就要吃,2},{等会再来吃,7}',}",
  [550535] = "{id=550535,Text='看来你很满意本店的[c][ffff00]暖身料理[-][/c]啊，是不是要打包一份呢？只需要[c][ffff00]5000zeny[-][/c]哦？',Speaker=806746,Option='{要！！！,3},{下次吧,5}',}",
  [550536] = "{id=550536,Text='那么现在的你，看起来充满了活力哦，祝你冒险愉快！~',Speaker=806746,}",
  [550537] = "{id=550537,Text='随时欢迎你再来哦，免费的试吃随时为你准备！',Speaker=806746,}",
  [550538] = "{id=550538,Text='你的钱不够哦，欢迎下次光临…',Speaker=806746,}",
  [550539] = "{id=550539,Text='冒险者，很高兴见到你，告诉你个好消息哦！',Speaker=806746,}",
  [550540] = "{id=550540,Text='现在起，限定特典月卡用户每日可免费在本店享用一份高级料理哦。',Speaker=806746,Option='领取高级料理',}",
  [550541] = "{id=550541,Text='是否现在就食用？',Speaker=806746,Option='{现在就吃,2},{等会再来,3}',}",
  [550542] = "{id=550542,Text='那么根据料理的种类，请选择你自己偏好的口味！',Speaker=806746,Option='{暖心料理,4},{灵巧料理B,5},{幸运料理B,6},{体质料理B,7},{智力料理B,8},{敏捷料理B,9},{力量料理B,10}',}",
  [550543] = "{id=550543,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,11},{下次吧,12}',}",
  [550544] = "{id=550544,Text='那么希望这份料理能够让你有个愉快的旅程，下次再见了，冒险者。',Speaker=806746,}",
  [550545] = "{id=550545,Text='很抱歉，你身上的钱似乎有些不够呢……欢迎下次光临。',Speaker=806746,}",
  [550546] = "{id=550546,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,15},{下次吧,12}',}",
  [550547] = "{id=550547,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,16},{下次吧,12}',}",
  [550548] = "{id=550548,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,17},{下次吧,12}',}",
  [550549] = "{id=550549,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,18},{下次吧,12}',}",
  [550550] = "{id=550550,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,19},{下次吧,12}',}",
  [550551] = "{id=550551,Text='怎么样，刚刚的料理是不是很美味呢！作为限定特典月卡用户的特权，只需半价就可以打包一份同样的料理带走哦！是否花费[c][ffff00]12500Zeny[-][/c]来购买呢？',Speaker=806746,Option='{半价购买,20},{下次吧,12}',}",
  [550552] = "{id=550552,Text='请不用担心，专属的料理随时等候你的光临哦！',Speaker=806746,}",
  [550553] = "{id=550553,Text='很抱歉，只有限定特典月卡用户才能享受高级料理哦！',Speaker=806746,}",
  [550557] = "{id=550557,Text='傲慢是所有生物的原罪，看来你惹怒它们了……',Speaker=806883,}",
  [550558] = "{id=550558,Text='别那么快就放松警惕，地狱之旅这才刚刚开始……',Speaker=806883,}",
  [550559] = "{id=550559,Text='嗯~甜腻的味道，是哪只诱人的小家伙来到这里啦？',Speaker=806885,}",
  [550560] = "{id=550560,Text='真是可爱的小猫咪，让姐姐来好好疼爱你一下~',Speaker=806885,}",
  [550561] = "{id=550561,Text='啊！！！！！',Speaker=806885,}",
  [550562] = "{id=550562,Text='即便是再弱小的猫咪，也有着锋利的爪牙！',Speaker=806883,}",
  [550563] = "{id=550563,Text='色欲如同无形的风刃，不知不觉中使你沉沦……',Speaker=806883,}",
  [550564] = "{id=550564,Text='难闻腐朽的人类气息，地狱岂是蝼蚁能来的地方！',Speaker=806884,}",
  [550565] = "{id=550565,Text='可恶的蝼蚁！只有你的死亡才能平息本王的怒火！',Speaker=806884,}",
  [550566] = "{id=550566,Text='愤怒就像心中的一颗种子，你不去平息它，它就会生根发芽……',Speaker=806883,}",
  [550567] = "{id=550567,Text='来啊！看这些价值连城的宝物，触碰它们，快！！！',Speaker=806886,}",
  [550568] = "{id=550568,Text='去死吧！人类！贪婪的奴仆们，吞噬他！！！',Speaker=806886,}",
  [550569] = "{id=550569,Text='不！！我的宝石！我的王冠！我的权杖！！！',Speaker=806886,}",
  [550570] = "{id=550570,Text='贪婪是人类与生俱来的欲望，不能控制贪欲的人终将堕落深渊。',Speaker=806883,}",
  [550571] = "{id=550571,Text='嫉妒！',Speaker=806887,}",
  [550572] = "{id=550572,Text='暴食！',Speaker=806888,}",
  [550573] = "{id=550573,Text='懒惰！',Speaker=806889,}",
  [550574] = "{id=550574,Text='嫉妒使人变得疯狂而不受控制！！！',Speaker=806883,}",
  [550575] = "{id=550575,Text='暴食使人渴望鲜血沉沦欲望！！！',Speaker=806883,}",
  [550576] = "{id=550576,Text='懒惰使人失去本我的灵魂！！！',Speaker=806883,}",
  [550577] = "{id=550577,Text='杀了人类！！！',Speaker=806887,}",
  [550578] = "{id=550578,Text='杀了人类！！！',Speaker=806888,}",
  [550579] = "{id=550579,Text='杀了人类！！！',Speaker=806889,}",
  [550580] = "{id=550580,Text='傲慢、嫉妒、暴怒、懒惰、贪婪、暴食和色欲……',Speaker=806883,}",
  [550581] = "{id=550581,Text='人类的七宗原罪都基于此……',Speaker=806883,}",
  [550582] = "{id=550582,Text='不迷失自我，战胜这七种欲望之人……',Speaker=806883,}",
  [550583] = "{id=550583,Text='神界的大门将为你敞开……',Speaker=806883,}",
  [550584] = "{id=550584,Text='波……波波……波波利……透明的！',Speaker=806606,}",
  [550585] = "{id=550585,Text='波……波波……波波利……凉凉的！',Speaker=806607,}",
  [550586] = "{id=550586,Text='波…波利……最爱……冰……冰洞',Speaker=806608,}",
  [550587] = "{id=550587,Text='凉凉的，透明的，波利是最可爱的……',Speaker=806609,}",
  [550588] = "{id=550588,Text='傲慢是恶魔的天性，它们会向踏入地狱的人展示它们的强大！',Speaker=806883,}",
  [550602] = "{id=550602,Text='B格猫星百年难得一遇的大天才，说的就是我啦！最近我又掌握了一些奇妙的魔法，不过似乎只有完成了二转的冒险者，才能够承载魔法的威力……',Speaker=807074,Emoji=20,}",
  [550608] = "{id=550608,Text='有种怪怪的感觉，时间的流逝好像变慢了...',}",
  [550609] = "{id=550609,Text='这是谁？咦？时间的流动恢复正常了。',}",
  [550648] = "{id=550648,Text='真的输给魔物了么……',}",
  [550649] = "{id=550649,Text='这个光芒是……',}",
  [550650] = "{id=550650,Text='内心不坚定的英灵是不被认可的！',Speaker=807075,}",
  [550709] = "{id=550709,Text='糟了……这么多安保员，必须躲开他们才行。',}",
  [550710] = "{id=550710,Text='这里放着一个特殊的装置……',}",
  [550711] = "{id=550711,Text='哔——哔哔——',Speaker=803841,}",
  [550712] = "{id=550712,Text='【雷根贝勒安全系统 读取开始】',Speaker=803841,}",
  [550713] = "{id=550713,Text='【---请录入您的身份卡片---】',Speaker=803841,}",
  [550714] = "{id=550714,Text='（之前在原野捡到的证件也许有用！）',}",
  [550715] = "{id=550715,Text='哔——哔哔——',Speaker=803841,}",
  [550716] = "{id=550716,Text='【---读取身份ID中---】',Speaker=803841,}",
  [550717] = "{id=550717,Text='【10%——30%——60%——80%——100%】',Speaker=803841,}",
  [550718] = "{id=550718,Text='【读取完毕 身份ID [c][ffff00]6 6 2 5 0[-][/c]】',Speaker=803841,}",
  [550719] = "{id=550719,Text='【身份认证成功  身份等级S  权限开放】',Speaker=803841,}",
  [550720] = "{id=550720,Text='【即将前往所属研究区域[c][ffff00]B731[-][/c] 倒计时开始】',Speaker=803841,}",
  [550721] = "{id=550721,Text='【5】',Speaker=803841,}",
  [550722] = "{id=550722,Text='【4】',Speaker=803841,}",
  [550723] = "{id=550723,Text='【3】',Speaker=803841,}",
  [550724] = "{id=550724,Text='【2】',Speaker=803841,}",
  [550725] = "{id=550725,Text='【1】',Speaker=803841,}",
  [550726] = "{id=550726,Text='这是雷根贝勒的地下研究所……',}",
  [550727] = "{id=550727,Text='杰拉尔说过，这里有一本特殊的笔记。在附近的书架找找看吧。',}",
  [550728] = "{id=550728,Text='《7号实验仓建造说明》',}",
  [550729] = "{id=550729,Text='一本红色笔记，上面标注了[c][ffff00]数字7[-][/c]。',}",
  [550730] = "{id=550730,Text='《科学演算的3种方式》',}",
  [550731] = "{id=550731,Text='一本蓝色笔记，上面标注了数字[c][ffff00]3[-][/c]。',}",
  [550732] = "{id=550732,Text='《研究报告：新能源1号》',}",
  [550733] = "{id=550733,Text='一本绿色笔记，上面标注了数字[c][ffff00]1[-][/c]。',}",
  [550734] = "{id=550734,Text='（731……这几个数字有些眼熟……）',}",
  [550735] = "{id=550735,Text='（这本笔记格外厚。里面似乎藏了什么，但是被密码锁锁住了，打不开。）',}",
  [550736] = "{id=550736,Text='（密码锁上涂着[c][ffff00]红、蓝、绿、紫[-][/c]四种颜色，同时中央写着一个数字15。）',}",
  [550737] = "{id=550737,Text='[c][ffff00]15[-][/c]应该是四种颜色代表数字的总和。之前得到的数字分别是7、3、1，则剩下的数字就是密码。',}",
  [550738] = "{id=550738,Text='那么密码是——',Option='{1,2}{2,2}{3,2}{4,3}',}",
  [550739] = "{id=550739,Text='不不，应该再好好算算。如果输入错误的数字，后果也许不堪设想。',}",
  [550740] = "{id=550740,Text='输入4看看吧……',}",
  [550741] = "{id=550741,Text='紫色的书打开了。里面掉下了一把钥匙……',}",
  [550742] = "{id=550742,Text='房间里似乎出现了什么别的东西。',}",
  [550743] = "{id=550743,Text='出现了三个箱子，还有一本笔记本——',}",
  [550744] = "{id=550744,Text='每次只可以开启一个箱子。',Speaker=803833,}",
  [550745] = "{id=550745,Text='如果尝试打开错误的箱子，会[c][ffff00]引发爆炸[-][/c]。',Speaker=803833,}",
  [550747] = "{id=550747,Text='空缺的部分应该是正确箱子的代号！',}",
  [550748] = "{id=550748,Text='联系之前得到的线索B731，箱子的代号应该是B。',}",
  [550749] = "{id=550749,Text='仔细观察三个箱子上的信息，找到正确的箱子吧。',}",
  [550750] = "{id=550750,Text='我们是ABC，而我不是A。要打开我吗？',Speaker=803844,Option='{打开,6}{不打开,5}',}",
  [550751] = "{id=550751,Text='我们是ABC，我的旁边有B。要打开我吗？',Speaker=803845,Option='{打开,9}{不打开,8}',}",
  [550752] = "{id=550752,Text='我们是ABC，离我最远的箱子是C。要打开我吗？',Speaker=803846,Option='{打开,12}{不打开,11}',}",
  [550753] = "{id=550753,Text='“实验还在继续。真糟糕。”',Speaker=803834,}",
  [550754] = "{id=550754,Text='“他们都疯了。迟早有一天我也会疯掉。”',Speaker=803834,}",
  [550755] = "{id=550755,Text='“没有办法，我把那个东西藏了起来。',Speaker=803834,}",
  [550756] = "{id=550756,Text='“在[c][ffff00]地下一层[-][/c]的右上角，那个只有我能进去的房间里……”',Speaker=803834,}",
  [550757] = "{id=550757,Text='“事到如今，我已经不能回头了。”',Speaker=803834,}",
  [550758] = "{id=550758,Text='“如果未来有人能找到它，希望你用它做点好事……”',Speaker=803834,}",
  [550759] = "{id=550759,Text='笔记到这里就结束了。',}",
  [550760] = "{id=550760,Text='这似乎是什么人的日记……先去里面记录的地方看看吧。',}",
  [550767] = "{id=550767,Text='这里有个巨大的箱子，闪烁着不可思议的光芒。',}",
  [550768] = "{id=550768,Text='那位研究员藏起来的东西，也许就放在里面。',}",
  [550769] = "{id=550769,Text='试试之前得到的钥匙能不能打开它吧。',}",
  [550770] = "{id=550770,Text='打开了！',}",
  [550771] = "{id=550771,Text='能感受到这片碎片中凝聚着巨大的魔力…………',}",
  [550772] = "{id=550772,Text='哔哔——哔哔哔——',Speaker=803847,}",
  [550773] = "{id=550773,Text='有入侵者——有入侵者——',Speaker=803847,}",
  [550774] = "{id=550774,Text='是时候看看这碎片的秘密了……',}",
  [550775] = "{id=550775,Text='身体感觉要被撕裂了…………！！',}",
  [550776] = "{id=550776,Text='唉……',Speaker=803843,}",
  [550777] = "{id=550777,Text='你还是迈出了这禁忌的一步……',Speaker=803843,}",
  [550778] = "{id=550778,Text='刚才窒息的感觉消失了……',}",
  [550779] = "{id=550779,Text='真是的，你刚刚差点就丧命了！',Speaker=803838,Emoji=12,}",
  [550780] = "{id=550780,Text='现在的年轻人，做事怎么如此莽撞！',Speaker=803838,Option='对不起',}",
  [550781] = "{id=550781,Text='算了算了。',Speaker=803838,}",
  [550782] = "{id=550782,Text='你知道你刚才触碰的是什么吗？',Speaker=803838,Option='不知道……',}",
  [550783] = "{id=550783,Text='哼……你要是知道，就绝不会这么草率的去接触了!',Speaker=803838,}",
  [550784] = "{id=550784,Text='那是[c][ffff00]人造伊米尔之心[-][/c]的碎片！让它贸然与人体融合，是会丧命的！',Speaker=803838,}",
  [550785] = "{id=550785,Text='（小声）雷根贝勒近几年做事真是越发离谱了，连这种东西都能搞得出来！',Speaker=803838,}",
  [550786] = "{id=550786,Text='话说回来，你是个基因学者吧？怎么会好端端的跑到这里？',Speaker=803838,Option='讲述经过',}",
  [550787] = "{id=550787,Text='唔……原来是这样。',Speaker=803838,Emoji=7,}",
  [550788] = "{id=550788,Text='星星的指引么……看来这一切都是命运的选择。',Speaker=803838,}",
  [550789] = "{id=550789,Text='听好了，年轻人。',Speaker=803838,}",
  [550790] = "{id=550790,Text='人造伊米尔之心的力量，并非不能为人所用。',Speaker=803838,}",
  [550791] = "{id=550791,Text='关键在于使用的方法是什么。',Speaker=803838,Option='要怎么做',}",
  [550792] = "{id=550792,Text='我可以告诉你如何使用它，但是——',Speaker=803838,}",
  [550793] = "{id=550793,Text='在那之前，我有几个问题想问问你。',Speaker=803838,}",
  [550794] = "{id=550794,Text='准备好了么？',Speaker=803838,Option='准备好了',}",
  [550795] = "{id=550795,Text='……看来你没考虑清楚，那我们就不必再谈了！',Speaker=803838,}",
  [550796] = "{id=550796,Text='嗯，你的脑子还比较清醒嘛。',Speaker=803838,Emoji=9,}",
  [550797] = "{id=550797,Text='我可以帮你，年轻人。',Speaker=803838,}",
  [550798] = "{id=550798,Text='现在人造伊米尔之心碎片的力量极不稳定，已经超过了人体的承受能力。',Speaker=803838,}",
  [550799] = "{id=550799,Text='如果贸然将它与人体相融，就会和宝勒世伏那样——造成不可逆的后果。',Speaker=803838,Option='那要怎么办',}",
  [550800] = "{id=550800,Text='——将它凝练。',Speaker=803838,}",
  [550801] = "{id=550801,Text='剔除碎片中的杂质，再将原本的魔力核心凝练后，就能将它稳定到人类可控的范围内。',Speaker=803838,}",
  [550802] = "{id=550802,Text='虽然这碎片是人造的，但凝练它——在这世界上也没几个人能做得到。',Speaker=803838,}",
  [550803] = "{id=550803,Text='还好你很幸运，遇到了我。',Speaker=803838,Option='您是？',Emoji=9,}",
  [550804] = "{id=550804,Text='呵，我的名字是[c][ffff00]巴特蒙德[-][/c]。',Speaker=803838,}",
  [550805] = "{id=550805,Text='瞧瞧你，这么惊讶做什么？',Speaker=803839,}",
  [550806] = "{id=550806,Text='世人都称我为大贤者，事实上我只是个追求极致智慧的怪人而已。',Speaker=803839,Option='为何会来这里',}",
  [550807] = "{id=550807,Text='呵呵……雷根贝勒曾是我寄托理想的地方，然而现在它已不再是当年的样子了。',Speaker=803839,}",
  [550808] = "{id=550808,Text='我来到研究所，本是想摧毁宝勒世伏那些罪恶的研究。但现在好像一切又有了转机。',Speaker=803839,Option='转机？',}",
  [550809] = "{id=550809,Text='不错。————转机就是你啊，年轻人。',Speaker=803839,}",
  [550810] = "{id=550810,Text='如果人造伊米尔之心可以善加利用，定能成为人类大陆上最强劲的力量之一。',Speaker=803839,}",
  [550811] = "{id=550811,Text='就要看你能否有足够坚韧的意志，承担起这份力量了……',Speaker=803839,}",
  [550812] = "{id=550812,Text='睁大眼睛吧，年轻人。',Speaker=803839,}",
  [550813] = "{id=550813,Text='至高无上的能量即将凝聚于此！',Speaker=803839,}",
  [550814] = "{id=550814,Text='——————————————',Speaker=803839,}",
  [550815] = "{id=550815,Text='混沌中封闭的时间————',Speaker=803839,}",
  [550816] = "{id=550816,Text='虚无中破碎的平衡————',Speaker=803839,}",
  [550817] = "{id=550817,Text='尘世中恒存的魔法————',Speaker=803839,}",
  [550818] = "{id=550818,Text='回溯于万物之始源————',Speaker=803839,}",
  [550819] = "{id=550819,Text='苏醒吧——共鸣吧——',Speaker=803839,}",
  [550820] = "{id=550820,Text='冲破曾经的桎梏————',Speaker=803839,}",
  [550821] = "{id=550821,Text='解脱遗忘的枷锁————',Speaker=803839,}",
  [550822] = "{id=550822,Text='凝固在此刻————',Speaker=803839,}",
  [550823] = "{id=550823,Text='诞生于永恒————',Speaker=803839,}",
  [550824] = "{id=550824,Text='就是现在……到中央去，年轻人！',Speaker=803839,}",
  [550825] = "{id=550825,Text='以你最澄净的姿态，去迎接那股力量吧————！！',Speaker=803839,}",
  [550826] = "{id=550826,Text='这是纯粹伊米尔之心的力量凝聚成的魔法石————',Speaker=803839,}",
  [550827] = "{id=550827,Text='去感受它吧————',Speaker=803839,}",
  [550828] = "{id=550828,Text='身体似乎发生了奇妙的变化……！！',}",
  [550829] = "{id=550829,Text='真是不可思议啊……',Speaker=803839,Emoji=9,}",
  [550830] = "{id=550830,Text='唔，唔。很不错。',Speaker=803839,}",
  [550831] = "{id=550831,Text='让我瞧瞧……现在的你，已经超越普通人类的范畴了。',Speaker=803839,Option='发生了什么',}",
  [550832] = "{id=550832,Text='呵呵……',Speaker=803839,}",
  [550833] = "{id=550833,Text='刚才那块碎片中纯净的力量凝练成了一块纯净魔法石，那便是伊米尔碎片魔力的结合体。',Speaker=803839,}",
  [550834] = "{id=550834,Text='或许可以称它为——[c][ffff00]伊米尔之石[-][/c]。',Speaker=803839,}",
  [550835] = "{id=550835,Text='通过它，你的能力也会得到质的飞跃……生命体的力量，将在你的手中得到传承。',Speaker=803839,}",
  [550836] = "{id=550836,Text='最后，你要切记……',Speaker=803839,}",
  [550837] = "{id=550837,Text='——永远、永远也不要生起多余的贪婪之心。[c][ffff00]你所得到的一切，都是需要付出同等代价的[-][/c]。',Speaker=803839,}",
  [550838] = "{id=550838,Text='世间万物皆遵循此规律，就算微小的生命也是一样。',Speaker=803839,Option='我一定谨记',}",
  [550839] = "{id=550839,Text='嗯，继续努力吧，年轻人。',Speaker=803839,}",
  [550840] = "{id=550840,Text='在未来的某个角落，我们还会再见的。',Speaker=803839,}",
  [550847] = "{id=550847,Text='啊你终于来了，来我给你算。。。测试测试特效朝向！',Speaker=1725,}",
  [550848] = "{id=550848,Text='不知道成功了没有，现在试试进副本看看特效朝向生效了没有吧！',Speaker=1725,Option='{进,6}{进,6}{进,6}{不进！,5}',}",
  [550849] = "{id=550849,Text='不进也得进！',Speaker=1725,}",
  [550850] = "{id=550850,Text='走吧老铁！',Speaker=1725,}",
  [550851] = "{id=550851,Text='穿越到……5.0的副本里去看看吧！',Speaker=1725,}",
  [550852] = "{id=550852,Text='（咒语）干申大那多！走你！',Speaker=1725,}",
  [550853] = "{id=550853,Text='人造伊米尔之心的力量即将涌现……',Speaker=803839,}",
  [550854] = "{id=550854,Text='不必紧张，等波动平息，便以你最澄净的姿态，去迎接那股力量吧————！！',Speaker=803839,}",
  [550859] = "{id=550859,Text='英灵之魂永不熄灭！',Speaker=807077,}",
  [550893] = "{id=550893,Text='开启铸造之乡的钥匙要由你自己来制作！',Speaker=807081,}",
  [550894] = "{id=550894,Text='眼前之人，你可否知道锻造的第一步是什么？',Speaker=807081,Option='{压制模型,2}{熔炼材料,3}{反复锻打,2}',}",
  [550895] = "{id=550895,Text='看来你对锻造了解的还是不够深。',Speaker=807081,}",
  [550896] = "{id=550896,Text='熔炼好材料后，需要做的是？',Speaker=807081,Option='{压制模型,5}{熔炼材料,4}{反复锻打,4}',}",
  [550897] = "{id=550897,Text='当有了初期模型后，需要做的是？',Speaker=807081,Option='{压制模型,6}{熔炼材料,6}{反复锻打,7}',}",
  [550898] = "{id=550898,Text='看来你对锻造还有一些了解。',Speaker=807081,}",
  [550899] = "{id=550899,Text='那就自己锻造出一把通往贝尔宾德的钥匙吧！',Speaker=807081,}",
  [550900] = "{id=550900,Text='反复锻打成品的锻造台。',Speaker=807684,}",
  [550901] = "{id=550901,Text='将稀释材料压制成模型的模型台。',Speaker=807686,}",
  [550902] = "{id=550902,Text='炼制金属的熔炉。',Speaker=807685,}",
  [550903] = "{id=550903,Text='请放入所需的材料。',Speaker=807685,}",
  [550904] = "{id=550904,Text='材料……',}",
  [550905] = "{id=550905,Text='导师给的那枚金属徽章！',}",
  [550906] = "{id=550906,Text='熔炼后的金属液体。',Speaker=807685,}",
  [550907] = "{id=550907,Text='将稀释材料压制成模型的模型台。',Speaker=807686,}",
  [550908] = "{id=550908,Text='共有三种模具，想要压制成的模型是。',Speaker=807686,Option='{月亮,9}{盾牌,9}{钥匙,10}',}",
  [550909] = "{id=550909,Text='这个模型好像不能开启大门。',}",
  [550910] = "{id=550910,Text='得到基础模型钥匙。',Speaker=807686,}",
  [550911] = "{id=550911,Text='锻造基础模型的铁台。',Speaker=807684,}",
  [550912] = "{id=550912,Text='钥匙已成，尝试能否打开通往贝尔宾德的大门吧！',}",
  [550913] = "{id=550913,Text='卡罗！偷偷跑出去的话，达尔先生可是会发脾气的！',Speaker=807079,Emoji=7,}",
  [550914] = "{id=550914,Text='琪亚娜，你可真是个死脑筋！',Speaker=807078,Emoji=25,}",
  [550915] = "{id=550915,Text='只有一小会儿的话，达尔先生是发现不了的。',Speaker=807078,Option='请问…',}",
  [550916] = "{id=550916,Text='哇！！你你你……你是谁？',Speaker=807078,Emoji=1,}",
  [550917] = "{id=550917,Text='卡罗！你没事吧！',Speaker=807079,Emoji=18,}",
  [550918] = "{id=550918,Text='你是谁，你是怎么来到贝尔宾德的？！',Speaker=807079,Option='说明情况',Emoji=7,}",
  [550919] = "{id=550919,Text='你要找达尔先生？',Speaker=807078,Option='是的',}",
  [550920] = "{id=550920,Text='唔……卡罗，看他的样子应该不是坏人。（小声）',Speaker=807079,}",
  [550921] = "{id=550921,Text='就算是坏人，我们估计也打不过他（小声）。',Speaker=807078,Option='……',}",
  [550922] = "{id=550922,Text='那我们还是先带他一起去找达尔先生吧。（小声）',Speaker=807079,Emoji=25,}",
  [550923] = "{id=550923,Text='嗯，到时候达尔先生绝对可以保护我们！（小声）',Speaker=807078,Option='……',Emoji=20,}",
  [550924] = "{id=550924,Text='咳咳……那个……你…你跟我们来！',Speaker=807078,}",
  [550925] = "{id=550925,Text='我们带你去找达尔先生！',Speaker=807079,}",
  [550926] = "{id=550926,Text='卡罗，琪亚娜，你们两个去哪里了？',Speaker=807683,}",
  [550927] = "{id=550927,Text='你是谁？你是怎么来到贝尔宾德的！（警惕）',Speaker=807683,Option='说明情况',Emoji=7,}",
  [550928] = "{id=550928,Text='你竟然是休朗克的学生！那家伙还好么！',Speaker=807683,Option='导师很好',}",
  [550929] = "{id=550929,Text='我就知道那个家伙，没有我在也会好好带领骑士团。',Speaker=807683,Emoji=17,}",
  [550930] = "{id=550930,Text='孩子，你这次来找我是……？',Speaker=807683,Option='至坚之盾',}",
  [550931] = "{id=550931,Text='………',Speaker=807683,Option='达尔先生？',Emoji=14,}",
  [550932] = "{id=550932,Text='孩子，其他事情我都可以帮你。',Speaker=807683,}",
  [550933] = "{id=550933,Text='唯独这个……不行。',Speaker=807683,Option='为什么？',Emoji=25,}",
  [550934] = "{id=550934,Text='卡罗，琪亚娜，你们去其他地方玩。',Speaker=807683,}",
  [550935] = "{id=550935,Text='嗯，达尔先生。',Speaker=807683,}",
  [550936] = "{id=550936,Text='唔…嗯。',Speaker=807078,}",
  [550937] = "{id=550937,Text='贝尔宾德因铸造而闻名于世。',Speaker=807683,}",
  [550938] = "{id=550938,Text='同样也因为铸造……不复存在。',Speaker=807683,Emoji=14,}",
  [550939] = "{id=550939,Text='你那么想知道的话，就触碰这枚指环吧。',Speaker=807683,}",
  [550940] = "{id=550940,Text='这是贝尔宾德最后的记忆。',Speaker=807683,Emoji=14,}",
  [550941] = "{id=550941,Text='贝尔宾德！臣服于梦罗克大人吧！',Speaker=807697,}",
  [550942] = "{id=550942,Text='为大人制造最强大的武器！！',Speaker=807697,Emoji=7,}",
  [550943] = "{id=550943,Text='梦罗克万岁！',Speaker=807697,}",
  [550944] = "{id=550944,Text='贝尔宾德永不屈服于梦罗克！！',Speaker=807696,}",
  [550945] = "{id=550945,Text='贝尔宾德！',Speaker=807696,}",
  [550946] = "{id=550946,Text='既然你们不抓住机会，就不要怪我了！',Speaker=807697,}",
  [550947] = "{id=550947,Text='就此长眠吧！！！',Speaker=807697,}",
  [550948] = "{id=550948,Text='傀儡们！杀光这些人！！！',Speaker=807697,}",
  [550949] = "{id=550949,Text='为了贝尔宾德！！！',Speaker=807696,}",
  [550950] = "{id=550950,Text='为了贝尔宾德！！！',Speaker=807695,}",
  [550951] = "{id=550951,Text='等我知道消息回来时已经晚了。',Speaker=807683,}",
  [550952] = "{id=550952,Text='我唯一能拯救的就是这些活下来的孩子们。',Speaker=807683,}",
  [550953] = "{id=550953,Text='为了这群最后的希望，我发誓再也不锻造任何武器。',Speaker=807683,}",
  [550954] = "{id=550954,Text='而且，我的盾牌也在和傀儡之王的战斗中碎掉了。',Speaker=807683,}",
  [550955] = "{id=550955,Text='所以……我……',Speaker=807683,}",
  [550956] = "{id=550956,Text='达尔先生！达尔先生！',Speaker=807079,Emoji=18,}",
  [550957] = "{id=550957,Text='怎么了琪亚娜？',Speaker=807683,}",
  [550958] = "{id=550958,Text='卡罗！卡罗他……被一个魔物抓走了。',Speaker=807079,}",
  [550959] = "{id=550959,Text='贝尔宾德有空间保护，这里怎么可能有魔物！！',Speaker=807683,Emoji=7,}",
  [550960] = "{id=550960,Text='卡罗……他偷偷跑到外面去了……',Speaker=807079,Emoji=18,}",
  [550961] = "{id=550961,Text='我…我没有拦住他……',Speaker=807079,Emoji=42,}",
  [550962] = "{id=550962,Text='可恶！那个魔物长成什么样子！',Speaker=807683,}",
  [550963] = "{id=550963,Text='它没有皮肤，它……是一个骷髅……',Speaker=807079,Emoji=38,}",
  [550964] = "{id=550964,Text='骷髅？该不会是！！',Speaker=807683,Emoji=7,}",
  [550965] = "{id=550965,Text='对了……它是故意放我回来，它让我把这封信交给达尔先生。',Speaker=807079,Emoji=42,}",
  [550966] = "{id=550966,Text='信件上的内容是……',}",
  [550967] = "{id=550967,Text='迪兰达尔，想救这个孩子就来找我吧！',}",
  [550968] = "{id=550968,Text='落款是一个骷髅样式的图案。',}",
  [550969] = "{id=550969,Text='傀儡之王……',Speaker=807683,Emoji=14,}",
  [550970] = "{id=550970,Text='琪亚娜，你照顾好其他孩子。',Speaker=807683,Emoji=7,}",
  [550971] = "{id=550971,Text='检测一下信封的来源。',Speaker=807683,}",
  [550972] = "{id=550972,Text='找到了，我去救卡罗！',Speaker=807683,}",
  [550973] = "{id=550973,Text='琪亚娜，你照顾好其他孩子。',Speaker=807683,Option='我也一起',Emoji=25,}",
  [550974] = "{id=550974,Text='你……好吧……',Speaker=807683,}",
  [550975] = "{id=550975,Text='就是这里，我们过去！',Speaker=807683,}",
  [550976] = "{id=550976,Text='没了盾牌的你竟然敢来！',Speaker=807697,}",
  [550977] = "{id=550977,Text='真是让我佩服你的勇气呢，迪兰达尔!',Speaker=807697,}",
  [550978] = "{id=550978,Text='快来看看你的老朋友们！',Speaker=807697,}",
  [550979] = "{id=550979,Text='这是……贝尔宾德战死的人……！！',Speaker=807683,}",
  [550980] = "{id=550980,Text='看样子还认得他们，快一起叙叙旧吧！',Speaker=807697,}",
  [550981] = "{id=550981,Text='没想到，你竟然还有个帮手！',Speaker=807697,}",
  [550982] = "{id=550982,Text='不过这在我强大的力量下，都是无用的！！',Speaker=807697,}",
  [550983] = "{id=550983,Text='小心！！！',Speaker=807683,}",
  [550985] = "{id=550985,Text='英灵殿欢迎战士的到来！',Speaker=807082,Option='英灵殿？',}",
  [550986] = "{id=550986,Text='献出热血的战士，在英灵殿中坚守自己的荣耀吧！',Speaker=807082,Option='我要离开！',}",
  [550987] = "{id=550987,Text='离开？',Speaker=807082,}",
  [550988] = "{id=550988,Text='到达英灵殿之人，将永远不能离开！',Speaker=807082,Option='我要离开！',}",
  [550989] = "{id=550989,Text='呵……这阶梯之上就是英灵殿的大门。',Speaker=807082,}",
  [550990] = "{id=550990,Text='近在咫尺又远在天边。',Speaker=807082,}",
  [550991] = "{id=550991,Text='想出去就动用自己的力量吧！',Speaker=807082,}",
  [550992] = "{id=550992,Text='如果在英灵殿中死亡，那么灵魂将是永远的消散。',Speaker=807082,Option='我要离开！',}",
  [550993] = "{id=550993,Text='呵……想要离开这里就得到他们的认可吧！',Speaker=807082,}",
  [550994] = "{id=550994,Text='英灵不朽！',Speaker=807077,}",
  [550995] = "{id=550995,Text='我生与战场，死于战场！',Speaker=807700,}",
  [550996] = "{id=550996,Text='战胜于我，我便认可你的存在！',Speaker=807700,}",
  [550997] = "{id=550997,Text='真正的英灵，内心一定是？',Speaker=807075,Option='{坚定的,2}{骄傲的,3}',}",
  [550998] = "{id=550998,Text='英灵最重要的是？',Speaker=807075,Option='{尊严,5}{实力,6}',}",
  [550999] = "{id=550999,Text='愿你永远坚守英灵之心！',Speaker=807075,}",
  [551000] = "{id=551000,Text='圣剑会决定你是否为真正的勇士！',Speaker=807076,}",
  [551001] = "{id=551001,Text='你可愿以灵魂为赌注，接受圣剑的考验么？',Speaker=807076,Option='愿意',}",
  [551002] = "{id=551002,Text='盾牌已经破碎，你仍要坚持么？',Speaker=807076,Option='仍要坚持！',}",
  [551003] = "{id=551003,Text='英灵不朽！',Speaker=807076,}",
  [551004] = "{id=551004,Text='倔强的灵魂，跟随着英灵的脚步来吧！',Speaker=807082,}",
  [551005] = "{id=551005,Text='坚定内心，不负众望。',Speaker=807082,}",
  [551006] = "{id=551006,Text='面对强大，毫不畏惧。',Speaker=807082,}",
  [551007] = "{id=551007,Text='以身为盾，守护他人。',Speaker=807082,}",
  [551008] = "{id=551008,Text='你将是第一个离开英灵殿的勇士！',Speaker=807082,}",
  [551009] = "{id=551009,Text='英灵不朽！！！',Speaker=807082,}",
  [551010] = "{id=551010,Text='你竟然还活着？！',Speaker=807697,}",
  [551011] = "{id=551011,Text='看来还是我下手太轻了！',Speaker=807697,Option='英灵不朽！',}",
  [551012] = "{id=551012,Text='这个光芒是……不……！！！',Speaker=807697,}",
  [551013] = "{id=551013,Text='傀儡之王…消失了？',Speaker=807683,Option='是的',}",
  [551014] = "{id=551014,Text='咦……这里是？',Speaker=807078,}",
  [551015] = "{id=551015,Text='达尔先生!',Speaker=807078,Emoji=7,}",
  [551016] = "{id=551016,Text='呜呜呜……我再也不乱跑了……',Speaker=807078,Emoji=42,}",
  [551017] = "{id=551017,Text='没事就好……',Speaker=807683,Emoji=30,}",
  [551018] = "{id=551018,Text='谢谢你救了我和卡罗。',Speaker=807683,}",
  [551019] = "{id=551019,Text='很抱歉，我没能帮助你铸造最坚硬的盾牌。',Speaker=807683,}",
  [551020] = "{id=551020,Text='这是……女武神？！！',Speaker=807683,}",
  [551021] = "{id=551021,Text='哇…是神明！！',Speaker=807078,}",
  [551022] = "{id=551022,Text='武器的强大与否取决于人的内心！',Speaker=807082,}",
  [551023] = "{id=551023,Text='内心强大之人，即使没有武器也可以面对强敌。',Speaker=807082,}",
  [551024] = "{id=551024,Text='至坚之盾，即为你的自身！',Speaker=807082,}",
  [551025] = "{id=551025,Text='愿你能以身守护这边大陆！',Speaker=807082,}",
  [551026] = "{id=551026,Text='以身为盾，英灵不朽！！',Speaker=807082,Option='英灵不朽！！',}",
  [551027] = "{id=551027,Text='[c][ffff00][PlayerName][-][/c]，是你帮我解开了内心的枷锁！',Speaker=807683,}",
  [551028] = "{id=551028,Text='我不再依赖于盾牌。我会坚定自己的内心。',Speaker=807683,}",
  [551029] = "{id=551029,Text='永远守护孩子们，守护贝尔宾德。',Speaker=807683,}",
  [551030] = "{id=551030,Text='以身为盾，英灵不朽！',Speaker=807683,}",
  [551031] = "{id=551031,Text='以战为荣，英灵不朽！',Speaker=807082,}",
  [551032] = "{id=551032,Text='只有被认可之人才能前往贝尔宾德！',Speaker=807081,}",
  [551078] = "{id=551078,Text='想要了解苹果酒的酿造过程吗？',Speaker=809482,Option='{想,3}{不想,2}',}",
  [551079] = "{id=551079,Text='是吗？那可真是太可惜了。',Speaker=809482,}",
  [551080] = "{id=551080,Text='酿造苹果酒入门非常简单哦。',Speaker=809482,}",
  [551081] = "{id=551081,Text='一共需要完成三个流程：[c][ffff00]挑选原料[-][/c]，[c][ffff00]搅拌榨汁[-][/c]，[c][ffff00]封装酿造[-][/c]。',Speaker=809482,}",
  [551082] = "{id=551082,Text='听起来是不是很简单，但是每个步骤的学问可大了呢。',Speaker=809482,Emoji=9,}",
  [551083] = "{id=551083,Text='你想要了解酿造苹果酒每个步骤的详情的话，',Speaker=809482,}",
  [551084] = "{id=551084,Text='可以去找我们酒庄相应的负责人哦。',Speaker=809482,}",
  [551085] = "{id=551085,Text='酒庄会不定期举办酿酒体验活动，',Speaker=809482,}",
  [551086] = "{id=551086,Text='届时，欢迎来体验，亲手酿造一瓶苹果酒吧。',Speaker=809482,Emoji=20,}",
  [551087] = "{id=551087,Text='想了解怎么挑选苹果吗？',Speaker=809483,Option='{想,3}{不想,2}',}",
  [551088] = "{id=551088,Text='想了解的话，随时欢迎回来咨询。',Speaker=809484,}",
  [551089] = "{id=551089,Text='目前我们酒庄选用的苹果是只在荒境生长的品种“粉雪”。',Speaker=809485,}",
  [551090] = "{id=551090,Text='它的果实随着成熟时间，从酸开始变得越来越甜。',Speaker=809486,}",
  [551091] = "{id=551091,Text='在不同的生长阶段，它们的果实颜色差别很大。',Speaker=809487,}",
  [551092] = "{id=551092,Text='因为我们挑选不同生长阶段的果实，会严重影响苹果酒的[c][ffff00]酸甜度[-][/c]哦~',Speaker=809488,}",
  [551093] = "{id=551093,Text='[c][ffff00]仍在生长的苹果[-][/c]，果实呈[c][ffff00]金色[-][/c]，适合酿造[c][ffff00]更具酸味[-][/c]的苹果酒。',Speaker=809489,}",
  [551094] = "{id=551094,Text='[c][ffff00]刚好成熟的苹果[-][/c]，果实呈[c][ffff00]红色[-][/c]，适合酿造[c][ffff00]酸甜适中[-][/c]的苹果酒。',Speaker=809490,}",
  [551095] = "{id=551095,Text='[c][ffff00]仍在生长的苹果[-][/c]，果实呈[c][ffff00]紫色[-][/c]，适合酿造[c][ffff00]更具甜味[-][/c]的苹果酒。',Speaker=809491,}",
  [551096] = "{id=551096,Text='根据你想要的苹果酒风味，选择不同的苹果吧~',Speaker=809492,Emoji=20,}",
  [551097] = "{id=551097,Text='想了解怎么加工苹果吗？',Speaker=809484,Option='{想,3}{不想,2}',}",
  [551098] = "{id=551098,Text='明白了。',Speaker=809484,}",
  [551099] = "{id=551099,Text='加工苹果具体来说就是选择榨汁方式。',Speaker=809484,}",
  [551100] = "{id=551100,Text='分为[c][ffff00]带皮榨汁[-][/c]和[c][ffff00]去皮榨汁[-][/c]两种。',Speaker=809484,}",
  [551101] = "{id=551101,Text='[c][ffff00]带皮榨汁[-][/c]会使酿造的苹果酒口感[c][ffff00]更加层次丰富[-][/c]。',Speaker=809484,}",
  [551102] = "{id=551102,Text='[c][ffff00]去皮榨汁[-][/c]会使酿造的苹果酒口感[c][ffff00]更加丝滑[-][/c]。',Speaker=809484,}",
  [551103] = "{id=551103,Text='根据你想要的苹果酒口感，需要选择不同的加工方式。',Speaker=809484,}",
  [551104] = "{id=551104,Text='想了解怎么封装酿造苹果酒吗？',Speaker=809485,Option='{想,3}{不想,2}',}",
  [551105] = "{id=551105,Text='随时欢迎。',Speaker=809485,}",
  [551106] = "{id=551106,Text='封装酿造苹果酒最重要的就是挑选容器。',Speaker=809485,}",
  [551107] = "{id=551107,Text='[c][ffff00]不同的容器[-][/c]会对苹果酒的香气产生巨大的影响。',Speaker=809485,}",
  [551108] = "{id=551108,Text='常用的容器有[c][ffff00]陶罐[-][/c]，玻璃瓶[-][/c]和橡木桶[-][/c]三种。',Speaker=809485,}",
  [551109] = "{id=551109,Text='选择使用陶罐酿造，苹果酒会有[c][ffff00]浓郁的草香和泥土味[-][/c]。',Speaker=809485,}",
  [551110] = "{id=551110,Text='选择使用玻璃瓶酿造，苹果酒会有[c][ffff00]浓郁的果香和花香[-][/c]。',Speaker=809485,}",
  [551111] = "{id=551111,Text='选择使用橡木桶酿造，苹果酒会有[c][ffff00]特殊的橡木香[-][/c]。',Speaker=809485,}",
  [551112] = "{id=551112,Text='根据你想要的苹果酒香气，选择不同的酿造容器吧。',Speaker=809485,}",
  [551122] = "{id=551122,Text='入口微酸沁心/酸酸甜甜/清甜迷人，口感层次丰富/轻柔丝滑，具有浓郁的草香和泥土味/浓郁的果香和花香/特殊的橡木香，',Speaker=809482,}",
  [551159] = "{id=551159,Text='微醺的感觉，刚刚好。',}",
  [551160] = "{id=551160,Text='你居然还能站起来！！',Speaker=807697,}",
  [551161] = "{id=551161,Text='你手中的盾牌都已经破碎！',Speaker=807697,}",
  [551162] = "{id=551162,Text='难道还想着空手与我战斗！',Speaker=807697,}",
  [551163] = "{id=551163,Text='看来还是我下手太轻了！',Speaker=807697,}",
  [551164] = "{id=551164,Text='英灵不朽！',}",
  [551165] = "{id=551165,Text='不……这个光芒是……！！！',Speaker=807697,}",
  [551166] = "{id=551166,Text='这是英灵的力量！！！',Speaker=807697,}",
  [551167] = "{id=551167,Text='咳……咳咳……',Speaker=803828,}",
  [551168] = "{id=551168,Text='傀儡之王…消失了？',Speaker=803828,Option='说明情况',}",
  [551169] = "{id=551169,Text='你……居然在没有盾牌的情况下打败了傀儡之王！！',Speaker=803828,}",
  [551170] = "{id=551170,Text='咦……这里是？',Speaker=807078,}",
  [551171] = "{id=551171,Text='达尔先生!',Speaker=807078,}",
  [551172] = "{id=551172,Text='呜呜呜……我再也不乱跑了……',Speaker=807078,}",
  [551173] = "{id=551173,Text='没事就好……',Speaker=803828,}",
  [551174] = "{id=551174,Text='谢谢你，[c][ffff00][PlayerName][-][/c]！',Speaker=803828,}",
  [551175] = "{id=551175,Text='是你救了我和卡罗！',Speaker=803828,}",
  [551176] = "{id=551176,Text='但是我却没能帮助你铸造最坚硬的盾牌。',Speaker=803828,Option='没关系',}",
  [551177] = "{id=551177,Text='我很内疚……',Speaker=803828,}",
  [551178] = "{id=551178,Text='咦？！你……你身上的光芒是……',Speaker=803828,}",
  [551179] = "{id=551179,Text='坚毅的灵魂啊！',Speaker=807082,}",
  [551180] = "{id=551180,Text='你的所为，吾都看到了！',Speaker=807082,}",
  [551181] = "{id=551181,Text='吾秉承瓦尔哈拉之力，赐予你最坚硬的盾牌！',Speaker=807082,}",
  [551182] = "{id=551182,Text='来吧！接受这份力量吧！',Speaker=807082,}",
  [551183] = "{id=551183,Text='眼前的盾牌闪闪发光，无需怀疑它所具有的强大威力……',}",
  [551184] = "{id=551184,Text='可是，这真的是我要苦苦寻找的答案吗……',}",
  [551185] = "{id=551185,Text='渴求力量的灵魂啊，还在犹豫什么呢，拿起吾赐予你的至坚之盾吧！',Speaker=807082,Option='听从内心的指引',}",
  [551186] = "{id=551186,Text='…………',Speaker=807082,}",
  [551187] = "{id=551187,Text='瓦尔哈拉果然没有选错人！',Speaker=807082,}",
  [551188] = "{id=551188,Text='眼前之人，吾问你！',Speaker=807082,}",
  [551189] = "{id=551189,Text='你是否可以坚定内心不负众望！',Speaker=807082,}",
  [551190] = "{id=551190,Text='你是否可以面对强大毫不畏惧！',Speaker=807082,}",
  [551191] = "{id=551191,Text='你是否可以以身为盾守护他人！',Speaker=807082,}",
  [551192] = "{id=551192,Text='坚毅的灵魂啊，跟随着英灵的脚步迎接瓦尔哈拉之力吧！',Speaker=807082,}",
  [551193] = "{id=551193,Text='瓦尔哈拉之力将照耀真正的英灵！',Speaker=807082,}",
  [551194] = "{id=551194,Text='武器的强大与否取决于人的内心！',Speaker=807082,}",
  [551195] = "{id=551195,Text='至坚之盾，即为你的自身！',Speaker=807082,}",
  [551196] = "{id=551196,Text='愿你能以身守护这边大陆！',Speaker=807082,}",
  [551197] = "{id=551197,Text='以身为盾，英灵不朽！！',Speaker=807082,Option='英灵不朽！',}",
  [551198] = "{id=551198,Text='失去盾牌还能拥有如此强大的力量！',Speaker=807082,}",
  [551199] = "{id=551199,Text='英灵都被你所震撼！',Speaker=807082,}",
  [551200] = "{id=551200,Text='愿你用这份力量守护你想守护的人！',Speaker=807082,}",
  [551201] = "{id=551201,Text='……看来你没考虑清楚，那我们就不必再谈了！',Speaker=807082,}",
  [551206] = "{id=551206,Text='但请注意若不注意击败了正常的荒野之鼠，会扣除一个徽记哦。',Speaker=809486,}",
  [551208] = "{id=551208,Text='可是我的熊猫波利玩偶被一只灰森灵抢走了。',Speaker=809487,Emoji=42,}",
  [551209] = "{id=551209,Text='它“咻”的一下就逃跑了，等我追过去，',Speaker=809487,}",
  [551210] = "{id=551210,Text='它“啪”的一声变成了和枫叶森灵一模一样的样子。',Speaker=809487,}",
  [551211] = "{id=551211,Text='冒险者，帮帮我可以吗？',Speaker=809487,Option='{交给我吧,3}{我还有事,2}',Emoji=42,}",
  [551212] = "{id=551212,Text='小熊猫，你在哪？',Speaker=809487,Emoji=42,}",
  [551213] = "{id=551213,Text='看来这就是偷走雪羽玩偶的灰森灵！',}",
  [551214] = "{id=551214,Text='灰森灵企图逃跑！',}",
  [551215] = "{id=551215,Text='灰森灵一脸得意的样子。',}",
  [551216] = "{id=551216,Text='灰森灵被准确的识破了。',}",
  [551217] = "{id=551217,Text='那是我的小熊猫！谢谢你！ଘ(੭ˊᵕˋ)੭* ੈ✩‧₊˚',Speaker=809487,}",
  [551218] = "{id=551218,Text='嗯....你已经获得20个徽记了吗？',Speaker=809486,Option='{获得了,98}{查询徽记,96}{还没有,97}',}",
  [551219] = "{id=551219,Text='嗯...我看看，你已经达成目标了！',Speaker=809486,}",
  [551220] = "{id=551220,Text='谢谢你的帮助，我这就送你出去~',Speaker=809486,}",
  [551221] = "{id=551221,Text='嗯...我看看，你还没有获得足够的徽记哟！~',Speaker=809486,}",
  [551222] = "{id=551222,Text='消灭变异的荒野之鼠，获得[c][ffff00]20[-][/c]个它们的徽记就行了。需要注意的是，如果消灭了1只正常的荒野之鼠，会被[c][ffff00]扣1徽记[-][/c]哟~',Speaker=809486,}",
  [551223] = "{id=551223,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]1[-][/c]',Speaker=809486,}",
  [551224] = "{id=551224,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]2[-][/c]',Speaker=809486,}",
  [551225] = "{id=551225,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]3[-][/c]',Speaker=809486,}",
  [551226] = "{id=551226,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]4[-][/c]',Speaker=809486,}",
  [551227] = "{id=551227,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]5[-][/c]',Speaker=809486,}",
  [551228] = "{id=551228,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]6[-][/c]',Speaker=809486,}",
  [551229] = "{id=551229,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]7[-][/c]',Speaker=809486,}",
  [551230] = "{id=551230,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]8[-][/c]',Speaker=809486,}",
  [551231] = "{id=551231,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]9[-][/c]',Speaker=809486,}",
  [551232] = "{id=551232,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]10[-][/c]',Speaker=809486,}",
  [551233] = "{id=551233,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]11[-][/c]',Speaker=809486,}",
  [551234] = "{id=551234,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]12[-][/c]',Speaker=809486,}",
  [551235] = "{id=551235,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]13[-][/c]',Speaker=809486,}",
  [551236] = "{id=551236,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]14[-][/c]',Speaker=809486,}",
  [551237] = "{id=551237,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]15[-][/c]',Speaker=809486,}",
  [551238] = "{id=551238,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]16[-][/c]',Speaker=809486,}",
  [551239] = "{id=551239,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]17[-][/c]',Speaker=809486,}",
  [551240] = "{id=551240,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]18[-][/c]',Speaker=809486,}",
  [551241] = "{id=551241,Text='嗯...我看看，你的当前徽记的个数是：[c][ffff00]19[-][/c]',Speaker=809486,}",
  [551242] = "{id=551242,Text='嗯...我看看，你已经获得[c][ffff00]20[-][/c]个徽记了。',Speaker=809486,}",
  [551243] = "{id=551243,Text='箱子里冒出了一团毒烟，咳咳~应该不是在这个箱子里……',}",
  [551244] = "{id=551244,Text='熊猫波利真是太可爱了！⁽⁽ଘ( ˊᵕˋ )ଓ⁾⁾',Speaker=809487,Emoji=8,}",
  [551250] = "{id=551250,Text='看来这就是偷走雪羽玩偶的灰森灵！',}",
  [551251] = "{id=551251,Text='灰森灵企图逃跑！',}",
  [551252] = "{id=551252,Text='灰森灵一脸得意的样子。',}",
  [551253] = "{id=551253,Text='灰森灵被准确的识破了。',}",
  [551254] = "{id=551254,Text='那是我的小熊猫！谢谢你！ଘ(੭ˊᵕˋ)੭* ੈ✩‧₊˚',Speaker=809487,}",
  [551258] = "{id=551258,Text='嗯...我看看，你还没有获得徽记哦！快去消灭[c][ffff00]变异的荒野之鼠[-][/c]，获得它们的[c][ffff00]徽记[-][/c]吧。',Speaker=809486,Option='我知道了',}",
  [551259] = "{id=551259,Text='想要了解苹果酒的酿造过程吗？',Speaker=809482,Option='{想,2}{不想,3}',}",
  [551260] = "{id=551260,Text='是吗？那可真是太可惜了。',Speaker=809482,}",
  [551261] = "{id=551261,Text='酿造苹果酒入门非常简单哦。',Speaker=809482,}",
  [551262] = "{id=551262,Text='一共需要完成三个流程：[c][ffff00]挑选原料[-][/c]，[c][ffff00]搅拌榨汁[-][/c]，[c][ffff00]封装酿造[-][/c]。',Speaker=809482,}",
  [551263] = "{id=551263,Text='听起来是不是很简单，但是每个步骤的学问可大了呢。',Speaker=809482,}",
  [551264] = "{id=551264,Text='你想要了解酿造苹果酒每个步骤的详情的话，',Speaker=809482,}",
  [551265] = "{id=551265,Text='可以去找我们酒庄相应的负责人哦。',Speaker=809482,}",
  [551266] = "{id=551266,Text='酒庄会不定期举办酿酒体验活动，',Speaker=809482,}",
  [551267] = "{id=551267,Text='届时，欢迎来体验，亲手酿造一瓶苹果酒吧。',Speaker=809482,}",
  [551268] = "{id=551268,Text='想了解怎么挑选苹果吗？',Speaker=809483,Option='{想,2}{不想,3}',}",
  [551269] = "{id=551269,Text='想了解的话，随时欢迎回来咨询。',Speaker=809483,}",
  [551270] = "{id=551270,Text='目前我们酒庄选用的苹果是只在荒境生长的品种[c][ffff00]“粉雪”[-][/c]。',Speaker=809483,}",
  [551271] = "{id=551271,Text='它的果实随着成熟时间，从酸开始变得越来越甜。',Speaker=809483,}",
  [551272] = "{id=551272,Text='在不同的生长阶段，它们的[c][ffff00]果实颜色[-][/c]差别很大。',Speaker=809483,}",
  [551273] = "{id=551273,Text='因为我们挑选不同生长阶段的果实，会严重影响苹果酒的[c][ffff00]酸甜度[-][/c]哦~',Speaker=809483,}",
  [551274] = "{id=551274,Text='[c][ffff00]仍在生长的苹果[-][/c]，果实呈[c][ffff00]金色[-][/c]，适合酿造[c][ffff00]更具酸味[-][/c]的苹果酒。',Speaker=809483,}",
  [551275] = "{id=551275,Text='[c][ffff00]刚好成熟的苹果[-][/c]，果实呈[c][ffff00]红色[-][/c]，适合酿造[c][ffff00]酸甜适中[-][/c]的苹果酒。',Speaker=809483,}",
  [551276] = "{id=551276,Text='[c][ffff00]生长过熟的苹果[-][/c]，果实呈[c][ffff00]紫色[-][/c]，适合酿造[c][ffff00]更具甜味[-][/c]的苹果酒。',Speaker=809483,}",
  [551277] = "{id=551277,Text='根据你想要的苹果酒风味，选择不同的苹果吧~',Speaker=809483,}",
  [551278] = "{id=551278,Text='想了解怎么加工苹果吗？',Speaker=809484,Option='{想,2}{不想,3}',}",
  [551279] = "{id=551279,Text='明白了。',Speaker=809484,}",
  [551280] = "{id=551280,Text='加工苹果具体来说就是选择[c][ffff00]榨汁方式[-][/c]。',Speaker=809484,}",
  [551281] = "{id=551281,Text='分为[c][ffff00]带皮榨汁[-][/c]和[c][ffff00]去皮榨汁[-][/c]两种。',Speaker=809484,}",
  [551282] = "{id=551282,Text='[c][ffff00]带皮榨汁[-][/c]会使酿造的苹果酒口感[c][ffff00]更加层次丰富[-][/c]。',Speaker=809484,}",
  [551283] = "{id=551283,Text='[c][ffff00]去皮榨汁[-][/c]会使酿造的苹果酒口感[c][ffff00]更加丝滑[-][/c]。',Speaker=809484,}",
  [551284] = "{id=551284,Text='根据你想要的苹果酒口感，需要选择不同的加工方式。',Speaker=809484,}",
  [551285] = "{id=551285,Text='想了解怎么封装酿造苹果酒吗？',Speaker=809485,Option='{想,2}{不想,3}',}",
  [551286] = "{id=551286,Text='随时欢迎。',Speaker=809485,}",
  [551287] = "{id=551287,Text='封装酿造苹果酒最重要的就是挑选容器。',Speaker=809485,}",
  [551288] = "{id=551288,Text='[c][ffff00]不同的容器[-][/c]会对苹果酒的[c][ffff00]香气[-][/c]产生巨大的影响。',Speaker=809485,}",
  [551289] = "{id=551289,Text='常用的容器有陶罐，玻璃瓶和橡木桶三种。',Speaker=809485,}",
  [551290] = "{id=551290,Text='选择使用陶罐酿造，苹果酒会有[c][ffff00]浓郁的草香和泥土味[-][/c]。',Speaker=809485,}",
  [551291] = "{id=551291,Text='选择使用玻璃瓶酿造，苹果酒会有[c][ffff00]浓郁的果香和花香[-][/c]。',Speaker=809485,}",
  [551292] = "{id=551292,Text='选择使用橡木桶酿造，苹果酒会有[c][ffff00]特殊的橡木香[-][/c]。',Speaker=809485,}",
  [551293] = "{id=551293,Text='根据你想要的苹果酒香气，选择不同的酿造容器吧。',Speaker=809485,}",
  [551294] = "{id=551294,Text='我没有默认对话！',Speaker=1727,}",
  [551295] = "{id=551295,Text='访问我成功后看看任务引导框有什么变化就行了。',Speaker=1727,}",
  [551296] = "{id=551296,Text='谢谢你，我又有烟抽了！',Speaker=1727,}",
  [551297] = "{id=551297,Text='谢谢你，我也不知道谢你什么，反正就是谢谢你。',Speaker=1727,}",
  [551319] = "{id=551319,Text='那我们准备开始仪式吧。',Speaker=811091,Option='怎么做',}",
  [551320] = "{id=551320,Text='我会把你带回来的元素裂片按照特定的位置布成法阵，然后精炼出其中的元素精魄。',Speaker=811091,Option='然后呢',}",
  [551321] = "{id=551321,Text='元素精魄之间会产生共鸣，随后水之精魄将会引来大雨。那么，我就开始了！',Speaker=811091,}",
  [551322] = "{id=551322,Text='风灵，赐我生机与活力！',Speaker=811091,}",
  [551323] = "{id=551323,Text='水灵，赐我冷静与睿智！',Speaker=811091,}",
  [551324] = "{id=551324,Text='火灵，赐我激情与勇气！',Speaker=811091,}",
  [551325] = "{id=551325,Text='土灵，赐我坚韧与执着！',Speaker=811091,}",
  [551326] = "{id=551326,Text='雷灵，赐我锋锐与凌厉！',Speaker=811091,}",
  [551327] = "{id=551327,Text='吠！这是属于我族的宝贝！你们休想据为己用！',Speaker=811098,}",
  [551328] = "{id=551328,Text='它拿走了雷之裂片！快阻止它！',Speaker=811091,}",
  [551329] = "{id=551329,Text='吠吠吠！没用！雷之裂片给了我力量！你们赢不了我！',Speaker=811098,}",
  [551330] = "{id=551330,Text='它拥有雷灵护体，我们无法对他造成伤害！！',Speaker=811091,Option='怎么办？',}",
  [551331] = "{id=551331,Text='那个犬妖站的位置就是仪式中雷之裂片应该摆放的地点...冒险者，去困住它！我要强行进行仪式！',Speaker=811091,}",
  [551332] = "{id=551332,Text='都说了没有用！吠吠吠！',Speaker=811098,Emoji=5,}",
  [551333] = "{id=551333,Text='好机会，就是现在！',Speaker=811091,}",
  [551334] = "{id=551334,Text='神圣的元素精灵们啊，干涸的大地已满是裂痕，枯萎的树木已遍布山野。卑微的仆人向您发出援救之请求，助我打破这僵局！！',Speaker=811091,}",
  [551335] = "{id=551335,Text='可恶啊吠！你把我的碎片弄掉了！！',Speaker=811098,Emoji=1,}",
  [551336] = "{id=551336,Text='成功了！雷之精魄也凝练完成，马上就会下雨了！',Speaker=811091,Option='太好了',}",
  [551337] = "{id=551337,Text='那犬妖已经没有雷之裂片的保护了，冒险者，消灭它！',Speaker=811091,}",
  [551338] = "{id=551338,Text='放马过来吧吠！我才不会把一个小小的冒险者放在眼里呢！',Speaker=811098,}",
  [551339] = "{id=551339,Text='暂停一下啊吠！为什么我全身的毛发都竖起来了吠！',Speaker=811098,}",
  [551340] = "{id=551340,Text='好痛啊吠！我觉得我的全身都麻痹了吠吠吠吠！',Speaker=811098,}",
  [551341] = "{id=551341,Text='魔物消灭了，祈雨也成功了！',Speaker=811091,Option='太好了',}",
  [551342] = "{id=551342,Text='咦？这是什么？元素的余波中有什么东西...',Speaker=811091,}",
  [551343] = "{id=551343,Text='元素裂片接触到雨水后，化成了一条白色的小蛇，多可爱的小家伙啊！',Speaker=811091,Option='怎么回事',}",
  [551344] = "{id=551344,Text='一定是因为元素的能量过于庞大，祈雨之后汇聚在一起，诞生了新的灵体。',Speaker=811091,}",
  [551345] = "{id=551345,Text='多亏了你这个小家伙才能诞生，而且它看起来很喜欢你，请你把它带在身边吧。',Speaker=811091,Option='谢谢',}",
  [551416] = "{id=551416,Text='谢谢你！',Speaker=811107,}",
  [551446] = "{id=551446,Text='干涸的大地已——',Speaker=811091,}",
  [551447] = "{id=551447,Text='神圣的元素精灵们啊，',Speaker=811091,}",
  [551448] = "{id=551448,Text='干涸的大地已满是裂痕，',Speaker=811091,}",
  [551449] = "{id=551449,Text='枯萎的树木已遍布山野，',Speaker=811091,}",
  [551450] = "{id=551450,Text='卑微的仆人向您发出援救之请求，',Speaker=811091,}",
  [551451] = "{id=551451,Text='助我打破这炎之僵局！！',Speaker=811091,}",
  [551452] = "{id=551452,Text='新的道路仍遍布着迷雾与荆棘，你，可曾有退意？',Speaker=807082,}",
  [551453] = "{id=551453,Text='瓦尔哈拉之力将照耀真正的英灵！',Speaker=807082,}",
  [551454] = "{id=551454,Text='昨日的卫士啊，请铭记你此刻崭新的责任与荣耀—',Speaker=807082,}",
  [551455] = "{id=551455,Text='自此之日始，汝名，世界圣盾！',Speaker=807082,}",
  [551456] = "{id=551456,Text='你居然拒绝了你一直追寻的至坚之盾？',Speaker=807082,}",
  [551457] = "{id=551457,Text='难道你赤手与魔物战斗么？！',Speaker=807082,Option='以身为盾！',}",
  [551458] = "{id=551458,Text='……呵呵……',Speaker=807082,}",
  [551459] = "{id=551459,Text='我祈求——昭示你的正义之心！',Speaker=807082,}",
  [551460] = "{id=551460,Text='我祈求——昭示你的守护之心！',Speaker=807082,}",
  [551461] = "{id=551461,Text='我祈求——昭示你的奉献之心！',Speaker=807082,}",
  [551462] = "{id=551462,Text='昨日的卫士啊，你的意志既已由神灵见证——',Speaker=807082,}",
  [551463] = "{id=551463,Text='你强大的力量之源必将由此而生！',Speaker=807082,}",
  [551464] = "{id=551464,Text='力量之源既已造就，新生之时终将到来！',Speaker=807082,}",
  [551465] = "{id=551465,Text='我祈求——起源之风！',Speaker=807082,}",
  [551541] = "{id=551541,Text='麻烦您快过来！',Speaker=815045,Emoji=18,}",
  [551542] = "{id=551542,Text='您看的怎么样了？',Speaker=815045,}",
  [551543] = "{id=551543,Text='您知道我的孩子到底是哪里出了问题么！',Speaker=815045,Option='{身体,3}{八音盒,5}{周围家具,4}',}",
  [551544] = "{id=551544,Text='我检查过我孩子的身体没有问题！',Speaker=815045,}",
  [551545] = "{id=551545,Text='我家里的家具都没有换过！',Speaker=815045,}",
  [551546] = "{id=551546,Text='八音盒？难道伤害我孩子的是这个东西？！',Speaker=815045,}",
  [551547] = "{id=551547,Text='我这就把这个东西毁掉！',Speaker=815045,Emoji=12,}",
  [551548] = "{id=551548,Text='妈…妈妈……',Speaker=815046,}",
  [551549] = "{id=551549,Text='翠丝!你终于醒过来了！！',Speaker=815045,}",
  [551550] = "{id=551550,Text='妈妈……八音盒里面有……怪物……',Speaker=815046,Emoji=24,}",
  [551551] = "{id=551551,Text='翠丝不怕，妈妈已经把怪物赶走了！',Speaker=815045,}",
  [551552] = "{id=551552,Text='我一会就去找索伦多算账！',Speaker=815045,}",
  [551553] = "{id=551553,Text='居然敢制作致幻的玩具！',Speaker=815045,Emoji=12,}",
  [551554] = "{id=551554,Text='真是太可恶了……',Speaker=815045,Option='致幻的八音盒？',}",
  [551555] = "{id=551555,Text='对啊，一定是这个八音盒让我的孩子产生了幻觉！',Speaker=815045,}",
  [551556] = "{id=551556,Text='多亏了你救了我的孩子。',Speaker=815045,}",
  [551557] = "{id=551557,Text='等翠丝完全好了，我们就去影枫司道谢！',Speaker=815045,Option='没事的',}",
  [551575] = "{id=551575,Text='那又能说明什么？',Speaker=815047,}",
  [551586] = "{id=551586,Text='你在说什么东西啊？',Speaker=815040,}",
  [551600] = "{id=551600,Text='啾！啊啾啾——',Speaker=9348,}",
  [551601] = "{id=551601,Text='（这个声音……是那只鸟儿……）',}",
  [551602] = "{id=551602,Text='（之前的小鸟正载着自己飞翔。而眼前……竟然是一处无法望向尽头的通道？！）',}",
  [551603] = "{id=551603,Text='……醒醒、醒醒，冒险者！',Speaker=9349,Option='摩根？！',}",
  [551604] = "{id=551604,Text='是我！我不是用魔法凝聚了一缕意识跟你溜进来了么——先不说这些，你快看前面是谁？！',Speaker=9349,}",
  [551605] = "{id=551605,Text='（前面的人影……是莎拉·艾琳！！）',Emoji=12,}",
  [551606] = "{id=551606,Text='想不到你还真跟上来了，死缠烂打的家伙。',Speaker=816376,Option='别想逃走！',}",
  [551607] = "{id=551607,Text='呵呵。逃走？你在说什么胡话呢？',Speaker=816376,}",
  [551608] = "{id=551608,Text='记不记得我曾说过，并不想和你动手？但是现在，不好意思，我反悔了。',Speaker=816376,Option='……',}",
  [551609] = "{id=551609,Text='[c][ffff00]——我啊，最讨厌死缠烂打的虫子。[-][/c]',Speaker=816376,}",
  [551610] = "{id=551610,Text='（惊恐）啾啾啾！！！！！',Speaker=9348,}",
  [551611] = "{id=551611,Text='（不好！莎拉·艾琳的那把刀……正凝聚着令人战栗的魔力！）',}",
  [551612] = "{id=551612,Text='……别担心，冒险者。我还在呢。',Speaker=9349,Option='摩根！！',}",
  [551613] = "{id=551613,Text='大惊小怪。我这不是分了一缕意识跟你过来了吗？',Speaker=9349,Option='有办法吗',}",
  [551614] = "{id=551614,Text='嗯。我会尝试找到她攻击中的空隙。你只要集中精神，突破空隙，她就无法应对！',Speaker=9349,}",
  [551615] = "{id=551615,Text='冒险者，看到空中的[c][ffff00]红色魔法光晕[-][/c]了吗？！那就是她的魔力空隙！',Speaker=9349,}",
  [551616] = "{id=551616,Text='在魔法光晕最明亮的时候——就是从[c][ffff00]红色转为金色[-][/c]的瞬间，你要立刻攻击这空隙！',Speaker=9349,}",
  [551617] = "{id=551617,Text='（哆嗦）呃咕……啾啾……',Speaker=9348,Emoji=15,}",
  [551618] = "{id=551618,Text='（嘶，好痛……！没能避开对面的攻击……）',}",
  [551619] = "{id=551619,Text='别灰心，小家伙！我们再来一次！',Speaker=9349,}",
  [551620] = "{id=551620,Text='啾啾啾啾啾~',Speaker=9348,Emoji=2,}",
  [551621] = "{id=551621,Text='做得好！就是这样，继续迎接她的攻击吧！',Speaker=9349,}",
  [551622] = "{id=551622,Text='哼，你以为这样就结束了？看看这个！',Speaker=816376,}",
  [551623] = "{id=551623,Text='躲躲闪闪，像什么样子！真是可笑……',Speaker=816376,}",
  [551624] = "{id=551624,Text='有两下子……但想要赢过我，还是太天真了！',Speaker=816376,}",
  [551625] = "{id=551625,Text='啧，你除了会躲来躲去，还能做什么？！',Speaker=816376,}",
  [551626] = "{id=551626,Text='——在呼啸的海浪中碎裂吧！',Speaker=816376,}",
  [551627] = "{id=551627,Text='可恶！',Speaker=816376,}",
  [551628] = "{id=551628,Text='算你侥幸！',Speaker=816376,}",
  [551629] = "{id=551629,Text='啧……你这家伙，还真是不死心。',Speaker=816376,Option='绝不让你逃走！',}",
  [551630] = "{id=551630,Text='我倒是很好奇，你接下来能撑过几招？',Speaker=816376,Emoji=5,}",
  [551631] = "{id=551631,Text='不好！[c][ffff00][PlayerName][-][/c]，小心些！',Speaker=9349,}",
  [551632] = "{id=551632,Text='——到此为止了，冒险者！',Speaker=816376,}",
  [551633] = "{id=551633,Text='（哆嗦）咿啾啾啾啾——！！！！！！！！',Speaker=9348,Emoji=40,}",
  [551634] = "{id=551634,Text='怎么，现在知道害怕了？晚了！',Speaker=816376,}",
  [551635] = "{id=551635,Text='……糟了。这个女人没有我们想象的那么好对付！她这是要开始使用雷电魔法了！',Speaker=9349,Option='我们该怎么办！',}",
  [551636] = "{id=551636,Text='别慌。我来想想……',Speaker=9349,Option='没时间啦！！',}",
  [551637] = "{id=551637,Text='嘘，有了！这一回，我会尝试将她的魔力[c][ffff00]集中到一处[-][/c]……然后你呢，就要找机会将这股力量[c][ffff00]打回她的身上[-][/c]去！',Speaker=9349,}",
  [551638] = "{id=551638,Text='啧，这是吓得发呆了？我可不管你在打什么鬼主意！有什么遗愿，就来和这道雷光说吧！',Speaker=816376,Emoji=12,}",
  [551639] = "{id=551639,Text='莎拉艾琳 霹雷',}",
  [551640] = "{id=551640,Text='！！来了来了！！集中精神，你瞧见了吗？我把她的力量都汇集在[c][ffff00]红色的魔法光晕[-][/c]里了！',Speaker=9349,}",
  [551641] = "{id=551641,Text='就是现在，[c][ffff00]在光晕消失前将这股力量反击回去[-][/c]！！！',Speaker=9349,}",
  [551642] = "{id=551642,Text='（颤抖）呸呸呸啾！呸啾！',Speaker=9348,Emoji=15,}",
  [551643] = "{id=551643,Text='（呃……！被雷劈的滋味可真不好受……）',}",
  [551644] = "{id=551644,Text='没事没事，稳住！咱们再来一次！',Speaker=9349,}",
  [551645] = "{id=551645,Text='咕啾！！！！',Speaker=9348,Emoji=17,}",
  [551646] = "{id=551646,Text='不错不错，就是这样！你很熟练嘛！',Speaker=9349,}",
  [551647] = "{id=551647,Text='要小心，她接下来应该会有更强烈的攻击……',Speaker=9349,}",
  [551648] = "{id=551648,Text='呵呵，听见这雷电的咆哮了么？',Speaker=816376,}",
  [551649] = "{id=551649,Text='没用的，别挣扎了……不觉得自己很可悲么？',Speaker=816376,}",
  [551650] = "{id=551650,Text='——雷光啊，将这一切焚毁殆尽吧！！',Speaker=816376,}",
  [551651] = "{id=551651,Text='有意思……怎么会有你这样不知好歹的家伙？',Speaker=816376,}",
  [551652] = "{id=551652,Text='这东躲西藏的样子，真是恶心！',Speaker=816376,}",
  [551653] = "{id=551653,Text='切……',Speaker=816376,}",
  [551654] = "{id=551654,Text='呃……',Speaker=816376,}",
  [551655] = "{id=551655,Text='不过如此…！',Speaker=816376,}",
  [551656] = "{id=551656,Text='（哆嗦哆嗦）呃啾啾啾啾啾呜哇！！！！！！！！！！！',Speaker=9348,Emoji=42,}",
  [551657] = "{id=551657,Text='（可、可恶……没有力气了！）',}",
  [551658] = "{id=551658,Text='糟糕透顶！我得赶紧想个办法把你弄到安全的地方……',Speaker=9349,}",
  [551659] = "{id=551659,Text='你呀！还有的学呢！',Speaker=9349,}",
  [551660] = "{id=551660,Text='……你可真是个不让人放心的家伙。这回一定要集中精神，迎接她的攻击！',Speaker=9349,}",
  [551661] = "{id=551661,Text='然后继续之前的节点',}",
  [551662] = "{id=551662,Text='……哼。算你还有点本事。但那又如何？',Speaker=816376,Option='你想干嘛！',}",
  [551663] = "{id=551663,Text='ab都继续',}",
  [551664] = "{id=551664,Text='我想干嘛？呵呵，我不想干嘛，只是到了[c][ffff00]目的地[-][/c]而已。',Speaker=816376,}",
  [551665] = "{id=551665,Text='（目的地？！果真这个古怪的通道是某个地方的入口！）',}",
  [551666] = "{id=551666,Text='留点神，冒险者。可不能让她一个人跑了！',Speaker=9349,}",
  [551667] = "{id=551667,Text='啧……你现在一定在想不能让我单独离开，对不对？',Speaker=816376,}",
  [551668] = "{id=551668,Text='很可惜，你的愿望就要落空了……',Speaker=816376,}",
  [551669] = "{id=551669,Text='（突然间，摩根的魔法气息微弱了起来……！！）',}",
  [551670] = "{id=551670,Text='这、这是怎么回事？！意念魔法要消失了——',Speaker=9349,Option='摩根！！',}",
  [551671] = "{id=551671,Text='……怎么会这样，我的魔法正在被排斥！看来这个“目的地”，只对你一个人敞开啊。',Speaker=9349,}",
  [551672] = "{id=551672,Text='唉，终究我是无法陪着你继续走下去了。一个人千万小心，[c][ffff00][PlayerName][-][/c]！',Speaker=9349,}",
  [551673] = "{id=551673,Text='（摩根留下的意念魔法，渐渐消失了……）',}",
  [551674] = "{id=551674,Text='……呵呵，看来你的护身符已经失效了嘛。',Speaker=816376,Option='莎拉·艾琳！！',}",
  [551675] = "{id=551675,Text='别生气，很快你就不用再见到我了。',Speaker=816376,Option='什么意思！',}",
  [551676] = "{id=551676,Text='什么意思？……哈哈……自然就是，这个意思——',Speaker=816376,}",
  [551677] = "{id=551677,Text='（可恶……决不能就在这里结束……！！！）',}",
  [551678] = "{id=551678,Text='（还有很多重要的事情……必须完成……）',}",
  [551679] = "{id=551679,Text='哼……',Speaker=816376,}",
  [551680] = "{id=551680,Text='无趣。我可不想再跟你浪费时间了。',Speaker=816376,Option='你在害怕',}",
  [551681] = "{id=551681,Text='害怕？呵呵。懒得跟你多说。不想死，就趁早从这里滚开！',Speaker=816376,}",
  [551682] = "{id=551682,Text='（小声）她急了她急了！',Speaker=9349,}",
  [551683] = "{id=551683,Text='（不能让莎拉·艾琳带着伊米尔之心碎片离开。继续追……！）',Speaker=9349,Emoji=18,}",
  [551684] = "{id=551684,Text='（叹气）真是难缠。虫子的生命力都这么顽强么。',Speaker=816376,Emoji=14,}",
  [551685] = "{id=551685,Text='她又急了！我们别停下，追上去！',Speaker=9349,Option='好！',}",
  [551686] = "{id=551686,Text='（应声）啾啾——',Speaker=9348,Emoji=7,}",
  [551687] = "{id=551687,Text='……啧。这鸟都飞的精疲力尽了吧。还不肯停下？',Speaker=816376,}",
  [551688] = "{id=551688,Text='那就别怪我不客气了————',Speaker=816376,}",
  [551689] = "{id=551689,Text='（唔……雪翼鸟的风息稳定了原本的魔法立场。此处的魔力波动逐渐变得平稳了……）',}",
  [551690] = "{id=551690,Text='哼。别得意，这才刚刚开始！',Speaker=816376,}",
  [551691] = "{id=551691,Text='你这家伙，还不放弃吗……！',Speaker=816376,}",
  [551692] = "{id=551692,Text='（小声）唔……没想到会如此棘手……',Speaker=816376,}",
  [551693] = "{id=551693,Text='唔！可恶……！',Speaker=816376,}",
  [551694] = "{id=551694,Text='（唔……雪翼鸟的风息稳定了原本的魔法立场。此处的魔力波动逐渐变得平稳了……）',Speaker=816708,}",
  [551695] = "{id=551695,Text='听见这风雷的咆哮了么？它，就是为你敲响死亡的丧钟！',Speaker=816376,}",
  [551696] = "{id=551696,Text='恭喜你，年轻人，你已经踏出了成为魔剑士的第一步。',Speaker=816708,}",
  [551697] = "{id=551697,Text='在战斗中勇往直前、不要迷茫，终有一天你也会成为和我一样的勇士。',Speaker=816708,}",
  [551698] = "{id=551698,Text='你回来啦！特训的结果怎么样呢？',Speaker=816700,Option='递交',Emoji=17,}",
  [551699] = "{id=551699,Text='希格德莉法 播放表情 7',Speaker=816700,}",
  [551700] = "{id=551700,Text='号外号外，王立克里图拉学院又开始招新了，诚邀各位新老冒险者入学。',Speaker=816699,Option='克里图拉学院？',}",
  [551701] = "{id=551701,Text='是的，王立克里图拉学院是一所面向整片米德加尔特大陆，致力于帮助冒险者成长的学院。',Speaker=816699,}",
  [551702] = "{id=551702,Text='虽然您是一位有经验的冒险者，我们仍旧热情地欢迎您加入学院。',Speaker=816699,}",
  [551703] = "{id=551703,Text='学院可以为您的当前职业提供深造，或者针对您不熟悉的职业进行速成特训。',Speaker=816699,}",
  [551704] = "{id=551704,Text='【学院任务过程中，玩家可以获得一次快速职业3转机会，并选择是否使用。使用此机会后，角色将快速升级到base lv100、job lv60。】',Speaker=816699,Option='{我想入学,99},{再等一等,99}',}",
  [551705] = "{id=551705,Text='没问题。等您有空了，再做决定也不迟。',Speaker=816699,}",
  [551706] = "{id=551706,Text='好的。不过我还需要提醒您：【每个账号仅有一次快速3转机会。使用后同一账号下其他角色再无快速3转资格，也无法体验完整学院剧情。】',Speaker=816699,}",
  [551707] = "{id=551707,Text='您确定要以当前角色和当前职业进入王立克里图拉学院吗？',Speaker=816699,Option='{确定,99},{再考虑下,99}',}",
  [551708] = "{id=551708,Text='好的，您拿定主意后可以再来找我。',Speaker=816699,}",
  [551709] = "{id=551709,Text='好的，那么我就将您的姓名录入本届新生名单了。',Speaker=816699,}",
  [551710] = "{id=551710,Text='您可以在普隆德拉东门，搭乘马车前往学院。',Speaker=816699,}",
  [551711] = "{id=551711,Text='您好，我们现在就启程前往学院吗？',Speaker=816700,Option='{好,99},{再等等,99}',}",
  [551712] = "{id=551712,Text='没问题。我会一直在这里等您的。',Speaker=816700,}",
  [551713] = "{id=551713,Text='气泡：入学的新生们，请到我这里来！',Speaker=816701,}",
  [551714] = "{id=551714,Text='欢迎来到王立克里图拉学院，被命运选召的勇者。\n我是你的接引人希格德莉法，你可以叫我莉法。',Speaker=816701,Option='被选召的勇士？',Emoji=17,}",
  [551715] = "{id=551715,Text='哦？原来你不知道吗？',Speaker=816701,}",
  [551716] = "{id=551716,Text='你的身体里有着「命运的加护」，它能使你具备与众不同的潜质。',Speaker=816701,}",
  [551717] = "{id=551717,Text='看——',Speaker=816701,}",
  [551718] = "{id=551718,Text='这三只金鸟是命运女神的使者，它围绕着你飞翔，正是你被命运选召的证明。',Speaker=816701,}",
  [551719] = "{id=551719,Text='你将获得常人没有的能力，也背负着旁人无法想象的使命。',Speaker=816701,}",
  [551720] = "{id=551720,Text='不太明白也没关系。我会引导你在这所学院中找到答案的。',Speaker=816701,Emoji=30,}",
  [551721] = "{id=551721,Text='但在这之前，先跟着我简单了解一下学院吧~',Speaker=816701,}",
  [551722] = "{id=551722,Text='王立克里图拉学院原本是仅向卢恩贵族开放的皇家勇者学院，后来经过第29任校长居伊·克里图拉的改革，才发展成如今面向整片大陆的冒险者学院。',Speaker=816701,}",
  [551723] = "{id=551723,Text='在这里，你不仅能习得丰富的冒险知识，还能选择自己心仪的职业。学院还专门设有勇者试练塔，供新生挑战自我。',Speaker=816701,}",
  [551724] = "{id=551724,Text='学院也很重视学生们的文化娱乐生活。圣咏礼堂会不定期安排小型音乐会或戏剧表演，盛大的校庆汇演就在这里举行。',Speaker=816701,}",
  [551725] = "{id=551725,Text='学院一览到这里就结束了，我们回到中心广场再聊吧。',Speaker=816701,}",
  [551726] = "{id=551726,Text='快乐的入学阶段结束了，是时候来些铁与血的体验了！',Speaker=816701,Emoji=5,}",
  [551727] = "{id=551727,Text='哈哈，你这是什么表情啦~\n新手接受训练可是天经地义的哦~',Speaker=816701,}",
  [551728] = "{id=551728,Text='装备上这把武器，快去找阿历克塞教官报道吧。',Speaker=816701,}",
  [551729] = "{id=551729,Text='【以下任务为基础战斗教学，任务过程中玩家可再次与希格德莉法对话，跳过教学步骤。】',Speaker=816701,Option='{好的,2},{我不想特训,3}',}",
  [551730] = "{id=551730,Text='阿历克塞在学院野外的新手训练场上，从学院西门出去，你就能看到他了。',Speaker=816701,}",
  [551731] = "{id=551731,Text='唔，好吧。作为被命运选召的勇者，应当不会被简单的战斗难倒。',Speaker=816701,}",
  [551732] = "{id=551732,Text='嚯！小新人，你也来参加训练吗？',Speaker=816707,Option='解释',}",
  [551733] = "{id=551733,Text='希格德莉法让你来的……原来你就是那位特殊的新生啊。',Speaker=816707,Emoji=11,}",
  [551734] = "{id=551734,Text='唔……瞧这紧实的肌肉、敏锐的目光，真让人有狠、狠、操、练的欲望啊！',Speaker=816707,}",
  [551735] = "{id=551735,Text='哈哈，别害怕啊。毕竟在下不是魔鬼，不过说说而已！',Speaker=816707,Emoji=17,}",
  [551736] = "{id=551736,Text='基础招式的运用还是很简单的：普通攻击伤害低、出招快；重击伤害高，出招慢。',Speaker=816707,}",
  [551737] = "{id=551737,Text='你去魔物园中用森波利练练手吧，等掌握了这部分技巧，我再教你新的内容。',Speaker=816707,}",
  [551738] = "{id=551738,Text='这么快就掌握了？不愧是命运选中的勇士啊。',Speaker=816707,}",
  [551739] = "{id=551739,Text='接下来我将教会你新的内容——自动战斗。',Speaker=816707,}",
  [551740] = "{id=551740,Text='在面对更多魔物、更长时间战斗的时候，你可以选择这种模式。',Speaker=816707,}",
  [551741] = "{id=551741,Text='但沉迷挂机的同时，一定要留意周围的情况，要是撞见惹不起的魔物，可是会当场去世的哦~',Speaker=816707,}",
  [551742] = "{id=551742,Text='哈哈哈哈——你怎么又被吓到了？我只是随口一说而已。\n快去实战演练一下吧！',Speaker=816707,}",
  [551743] = "{id=551743,Text='不错不错，自动战斗你也学会了。',Speaker=816707,}",
  [551744] = "{id=551744,Text='经过这么多训练，你是不是感到自己收获颇多呢？',Speaker=816707,}",
  [551745] = "{id=551745,Text='分配升级所获得的素质点，能够进一步提高你的战斗力。',Speaker=816707,}",
  [551746] = "{id=551746,Text='到底是被命运选召的勇士，学什么都很快啊。',Speaker=816707,}",
  [551747] = "{id=551747,Text='我这里已经没有什么可指点你的了，请前往魔药园接受伊莱·雪耳博士的教学吧。',Speaker=816707,}",
  [551748] = "{id=551748,Text='请问……伊莱·雪耳博士在吗？',}",
  [551749] = "{id=551749,Text='喵~呜~\n我就是伊莱·雪耳，有什么事吗？',Speaker=816709,}",
  [551750] = "{id=551750,Text='会、会说话的猫咪！',}",
  [551751] = "{id=551751,Text='不对哦~我是能够沟通自然的多兰族啦喵，和普通猫咪可不一样呢！\n你是来接受训练吧？',Speaker=816709,Option='是的',}",
  [551752] = "{id=551752,Text='阿历克塞传授你正面战斗的技巧，而我则要教授你辨识草药和采集的方法。',Speaker=816709,Emoji=25,}",
  [551753] = "{id=551753,Text='请从魔药田里采集两株薄荷草吧，注意它们会和辛辣草混合在一起生长，不要认错喵~',Speaker=816709,}",
  [551754] = "{id=551754,Text='请问……伊莱·雪耳博士在吗？',}",
  [551755] = "{id=551755,Text='喵~呜~我就是伊莱·雪耳！\n能在这里遇到多兰族同族，真是一件幸事呀！',Speaker=816709,Emoji=17,}",
  [551756] = "{id=551756,Text='可爱的后辈，你叫什么名字呢？',Speaker=816709,Option='自我介绍',}",
  [551757] = "{id=551757,Text='[c][ffff00][PlayerName][-][/c]吗？真是个好名字呢喵。\n寒暄就到这里吧，我们继续特训吧。',Speaker=816709,}",
  [551758] = "{id=551758,Text='阿历克塞传授你正面战斗的技巧，而我则要教授你辨识草药和采集的方法。',Speaker=816709,}",
  [551759] = "{id=551759,Text='请从魔药田里采集两株薄荷草吧，注意它们会和辛辣草混合在一起生长，不要认错喵~',Speaker=816709,}",
  [551760] = "{id=551760,Text='地面有一顶无主的帽子，是谁遗失了它吗？',}",
  [551761] = "{id=551761,Text='欸！！！为什么突然就开始攻击我了啊！？',}",
  [551762] = "{id=551762,Text='小笨蛋，快停手，别再激怒它们了喵！\n使用装死躺到地上，直到我喊你再站起来。',Speaker=816709,}",
  [551763] = "{id=551763,Text='尊敬的巨型学院曼陀罗们，请听我一言：喵喵呜呜咪~',Speaker=816709,}",
  [551764] = "{id=551764,Text='哔啵哔哔啵？',Speaker=816716,Emoji=19,}",
  [551765] = "{id=551765,Text='嗷呜嗷呜？',Speaker=816709,Emoji=8,}",
  [551766] = "{id=551766,Text='哔啵！',Speaker=816716,Emoji=2,}",
  [551767] = "{id=551767,Text='没事了，[c][ffff00][PlayerName][-][/c]。你可以起来啦喵。',Speaker=816709,}",
  [551768] = "{id=551768,Text='真是个冒失的小家伙呀，竟然触动了巨型学院曼陀罗的逆鳞。',Speaker=816709,}",
  [551769] = "{id=551769,Text='学院帽是它们最宝贝的东西，任何擅动的人都会受到冷酷的攻击。',Speaker=816709,}",
  [551770] = "{id=551770,Text='幸好我和它们有些交情，才能让你免于无穷无尽的追杀。',Speaker=816709,Option='这么恐怖嘛！',}",
  [551771] = "{id=551771,Text='当然啦，英雄的冒险之旅不止荣誉，还充斥着各种危险呢。',Speaker=816709,}",
  [551772] = "{id=551772,Text='这些素材就送给你压惊咯喵，以后你可得小心一些哦~',Speaker=816709,}",
  [551773] = "{id=551773,Text='你的新手特训已经结束了，向希格德莉法领取下一步指引吧。',Speaker=816709,}",
  [551774] = "{id=551774,Text='你回来啦！特训的过程还顺利吗？',Speaker=816701,Option='{很简单,2},{很刺激,3}',Emoji=17,}",
  [551775] = "{id=551775,Text='我就知道，作为被选中的勇士，你肯定能够轻松过关。',Speaker=816701,Emoji=20,}",
  [551776] = "{id=551776,Text='哦~还没毕业就经历了如此惊险的事件，不愧是被命运选中的勇者！',Speaker=816701,}",
  [551777] = "{id=551777,Text='在开始下一个阶段的引导前，我还有件小任务需要你完成。\n那就是——制作个性头饰。',Speaker=816701,}",
  [551778] = "{id=551778,Text='对每位实力与颜值并存的冒险者来说，头饰都是不可或缺的东西。',Speaker=816701,}",
  [551779] = "{id=551779,Text='两位志愿者已经迫不及待地想为你推荐样式了，快来见见他们吧。',Speaker=816701,}",
  [551780] = "{id=551780,Text='英俊潇洒的维托。',Speaker=816704,}",
  [551781] = "{id=551781,Text='人见人爱的希达',Speaker=816705,}",
  [551782] = "{id=551782,Text='为你献上入学的礼物。',Speaker=816735,}",
  [551783] = "{id=551783,Text='我头顶上的蛋壳帽是用大嘴鸟的蛋壳做的，坚实耐用。\n戴上它，你就会拥有整座学院最“铁”的头。',Speaker=816704,}",
  [551784] = "{id=551784,Text='选我选我。你看我的波利帽如此粉嫩Q弹、多可爱呀。\n戴上它的人都会受到波利的祝福哦~',Speaker=816705,}",
  [551785] = "{id=551785,Text='[c][ffff00][PlayerName][-][/c]，你更喜欢哪一种头饰呢？',Speaker=816701,Option='{新手蛋壳帽,2},{粉嫩的波利,3}',}",
  [551786] = "{id=551786,Text='哈，和我一样有眼光！',Speaker=816704,}",
  [551787] = "{id=551787,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=816704,}",
  [551788] = "{id=551788,Text='我就知道你会选我的！粉嫩波利万岁！',Speaker=816705,}",
  [551789] = "{id=551789,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=816705,}",
  [551790] = "{id=551790,Text='欢迎你，亲爱的冒险者。请问你有什么需求呢？',Speaker=816706,Option='{头饰制作,99},{购买图纸,99},{出售,99}',}",
  [551791] = "{id=551791,Text='好看，很适合你呢！',Speaker=816704,Emoji=20,}",
  [551792] = "{id=551792,Text='高光时刻，一起来合影留念吧~',Speaker=816705,Emoji=39,}",
  [551793] = "{id=551793,Text='在开始下一个阶段的引导前，我还有件小任务需要你完成。\n那就是——制作个性头饰。',Speaker=816701,}",
  [551794] = "{id=551794,Text='对每位实力与颜值并存的冒险者来说，头饰都是不可或缺的东西。\n两位志愿者已经迫不及待地想为你推荐样式了，快来见见他们吧。',Speaker=816701,}",
  [551795] = "{id=551795,Text='英俊潇洒的维托。',Speaker=816704,}",
  [551796] = "{id=551796,Text='人见人爱的希达',Speaker=816705,}",
  [551797] = "{id=551797,Text='为你献上入学的礼物。',Speaker=816735,}",
  [551798] = "{id=551798,Text='我头顶上的蛋壳帽是用大嘴鸟的蛋壳做的，坚实耐用。\n戴上它，你就会拥有整座学院最“铁”的头。',Speaker=816704,}",
  [551799] = "{id=551799,Text='选我选我。你看我的波利帽如此粉嫩Q弹、多可爱呀。\n戴上它的人都会受到波利的祝福哦~',Speaker=816705,}",
  [551800] = "{id=551800,Text='[c][ffff00][PlayerName][-][/c]，你更喜欢哪一种头饰呢？',Speaker=816701,Option='{新手蛋壳帽,99},{粉嫩的波利,99}',}",
  [551801] = "{id=551801,Text='哈，和我一样有眼光！',Speaker=816704,}",
  [551802] = "{id=551802,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=816704,}",
  [551803] = "{id=551803,Text='我就知道你会选我的！粉嫩波利万岁！',Speaker=816705,}",
  [551804] = "{id=551804,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=816705,}",
  [551805] = "{id=551805,Text='欢迎你，亲爱的冒险者。请问你有什么需求呢？',Speaker=816706,Option='{头饰制作,99},{购买图纸,99},{出售,99}',}",
  [551806] = "{id=551806,Text='好看，很适合你呢！',Speaker=816704,Emoji=20,}",
  [551807] = "{id=551807,Text='高光时刻，一起来合影留念吧~',Speaker=816705,Emoji=39,}",
  [551808] = "{id=551808,Text='接下来，你要前往职业大厅选择冒险职业。至于具体过程……请允许我留作惊喜保密。',Speaker=816701,}",
  [551809] = "{id=551809,Text='毕竟有人已经在那里等你很久啦！更多的疑惑就留给TA来解答吧~',Speaker=816701,}",
  [551810] = "{id=551810,Text='咕咕咕、咕咕……',Speaker=816736,}",
  [551811] = "{id=551811,Text='这是什么情况？为什么我的眼前一片漆黑？',}",
  [551812] = "{id=551812,Text='咕咕！当然是为了衬托我！',Speaker=816736,}",
  [551813] = "{id=551813,Text='举世无双、独一无二，集可爱、活泼、神秘、睿智于一身的——',Speaker=816736,Option='{鸽子,99},{帽子精,99}',}",
  [551814] = "{id=551814,Text='讨厌啦！！！我才不是鸽子呢！',Speaker=816736,}",
  [551815] = "{id=551815,Text='过分！！！帽子精是什么鬼啦！',Speaker=816736,}",
  [551816] = "{id=551816,Text='太令咕咕伤心了。我在这里盼星星盼月亮地等着冒险者，他（她）却用语言伤害我的心。',Speaker=816736,Emoji=42,}",
  [551817] = "{id=551817,Text='你失去我了，我自闭了！',Speaker=816736,}",
  [551818] = "{id=551818,Text='真的没反应了呢……',}",
  [551819] = "{id=551819,Text='小家伙~',}",
  [551820] = "{id=551820,Text='我有名字的，我叫奥尔加，哼！',Speaker=816736,Emoji=12,}",
  [551821] = "{id=551821,Text='奥尔加~原谅我吧！',}",
  [551822] = "{id=551822,Text='呼~你、你就不会说得更有诚意一点吗？',Speaker=816710,Emoji=25,}",
  [551823] = "{id=551823,Text='全世界最聪明、最可爱的奥尔加，我知道错了！',}",
  [551824] = "{id=551824,Text='好吧，勉勉强强原谅你了咕！',Speaker=816710,}",
  [551825] = "{id=551825,Text='睁大眼睛看好，我是王立克里图拉学院的魔法小精灵！！！',Speaker=816710,}",
  [551826] = "{id=551826,Text='咕咕，回神啦回神啦，傻乎乎的冒险者！',Speaker=816710,Emoji=5,}",
  [551827] = "{id=551827,Text='重新自我介绍一下：我是克里图拉的学院精灵，奥尔加·古埃·咕，负责指导初心者们选择自己的冒险职业。',Speaker=816710,}",
  [551828] = "{id=551828,Text='我手里的这份卷轴，是由普隆德拉冒险者协会与吉芬魔法塔联合出品的魔法问卷。\n用心做完之后，你就能了解自己最适合什么职业啦。快来试试看吧~',Speaker=816710,Option='{好,3},{再等一会儿,2}',}",
  [551829] = "{id=551829,Text='好吧。反正我已经等你那么久啦，也不多这么一会儿咕。',Speaker=816710,}",
  [551830] = "{id=551830,Text='咕咕，那我们就开始咯~',Speaker=816710,}",
  [551831] = "{id=551831,Text='咕咕……你居然是这么想的吗？',Speaker=816710,}",
  [551832] = "{id=551832,Text='让我康康你选了什么~',Speaker=816710,}",
  [551833] = "{id=551833,Text='哦~你选了这一个选项啊。',Speaker=816710,}",
  [551834] = "{id=551834,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551835] = "{id=551835,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551836] = "{id=551836,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551837] = "{id=551837,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551838] = "{id=551838,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551839] = "{id=551839,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551840] = "{id=551840,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551841] = "{id=551841,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551842] = "{id=551842,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551843] = "{id=551843,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551844] = "{id=551844,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551845] = "{id=551845,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551846] = "{id=551846,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551847] = "{id=551847,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551848] = "{id=551848,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551849] = "{id=551849,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551850] = "{id=551850,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551851] = "{id=551851,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551852] = "{id=551852,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551853] = "{id=551853,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
