  [551923] = "{id=551923,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551924] = "{id=551924,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551925] = "{id=551925,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551926] = "{id=551926,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551927] = "{id=551927,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=816710,}",
  [551928] = "{id=551928,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=816710,}",
  [551929] = "{id=551929,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551930] = "{id=551930,Text='你去寻找符文骑士的导师：惩戒魔剑达尔克吧！他会帮你转职为剑士的。',Speaker=816710,}",
  [551931] = "{id=551931,Text='还有还有，如果你想选择其他职业也没有问题。',Speaker=816710,Option='知道了',}",
  [551932] = "{id=551932,Text='学院鼓励每一位冒险者自由发展，只要和对应的职业导师沟通，同样可以进行转职哦。',Speaker=816710,}",
  [551933] = "{id=551933,Text='去吧去吧，进阶成为职业的冒险家吧 ！',Speaker=816710,}",
  [551934] = "{id=551934,Text='惩戒魔剑，在此候命。',Speaker=816770,Option='我来转职',}",
  [551935] = "{id=551935,Text='符文骑士与龙为友，使用长枪利剑守护队友、与魔物战斗，在团队中承担输出和防御的职能。',Speaker=816770,}",
  [551936] = "{id=551936,Text='你确定要将符文骑士作为自己的职业目标吗？',Speaker=816770,Option='{确定,3},{再考虑一下,2}',}",
  [551937] = "{id=551937,Text='嗯，职业选择是一件大事，值得慎重考虑。',Speaker=816770,}",
  [551938] = "{id=551938,Text='好，那我现在就为你转职成剑士。',Speaker=816770,}",
  [551939] = "{id=551939,Text='平心静气，摒弃所有的杂念。',Speaker=816710,}",
  [551940] = "{id=551940,Text='将意志注入誓言之书，获得它的承认。',Speaker=816770,}",
  [551941] = "{id=551941,Text='恭喜你，年轻人，你已经踏出了成为符文骑士的第一步。',Speaker=816770,}",
  [551942] = "{id=551942,Text='在战斗中勇往直前、不要迷茫，终有一天你也会成为和我一样的勇士。',Speaker=816770,}",
  [551943] = "{id=551943,Text='你的下一站是职业大厅，至于具体做什么……请允许我留作惊喜保密。',Speaker=816701,}",
  [551944] = "{id=551944,Text='毕竟有人已经在那里等你很久啦！更多的疑惑就留给TA来解答吧~',Speaker=816701,}",
  [551945] = "{id=551945,Text='咕咕咕、咕咕……',Speaker=816736,}",
  [551946] = "{id=551946,Text='这是什么情况？为什么我的眼前一片漆黑？',}",
  [551947] = "{id=551947,Text='咕咕！当然是为了衬托我！',Speaker=816736,}",
  [551948] = "{id=551948,Text='活泼可爱、举世无双的学院小精灵——奥尔加！',Speaker=816736,}",
  [551949] = "{id=551949,Text='来自远方的冒险者咕，我这里有一份神奇的魔法卷轴。\n完成之后，可以揭示你最适合选择什么冒险职业哦~',Speaker=816736,Option='可我转职过了',}",
  [551950] = "{id=551950,Text='什——么——！！！',Speaker=816710,}",
  [551951] = "{id=551951,Text='那、那我在这里盼星星盼月亮地等你，还有什么意义！',Speaker=816710,}",
  [551952] = "{id=551952,Text='我的青春，终究是错付了，呜呜呜呜……',Speaker=816710,}",
  [551953] = "{id=551953,Text='没反应了呢……',}",
  [551954] = "{id=551954,Text='奥尔加~奥尔加~\n别把我关在黑暗里。',}",
  [551955] = "{id=551955,Text='就不！我生气、我难过，我要你和我一起悼念我逝去的青春。',Speaker=816710,Emoji=42,}",
  [551956] = "{id=551956,Text='很抱歉辜负了你的等待，但我过去也不知道你的存在呀……',Emoji=16,}",
  [551957] = "{id=551957,Text='话是这么说，但我还是有点伤心……你再安慰安慰我！',Speaker=816710,Emoji=24,}",
  [551958] = "{id=551958,Text='最最善良可爱的奥尔加，虽然我们过去错过了，但以后还能做朋友呀~',}",
  [551959] = "{id=551959,Text='好吧……看在你这么诚心的份上，我就原谅你吧！',Speaker=816710,}",
  [551960] = "{id=551960,Text='咕咕，回神啦回神啦，傻乎乎的冒险者！',Speaker=816710,Emoji=5,}",
  [551961] = "{id=551961,Text='怎么样，这里很漂亮，很恢弘吧？',Speaker=816710,}",
  [551962] = "{id=551962,Text='可惜你的第一次转职没有在这里进行……不过就像你说的那样，我们以后还可以做朋友哒~',Speaker=816710,}",
  [551963] = "{id=551963,Text='现在你可以随便逛一逛职业大厅，或者返回学院广场。',Speaker=816710,Option='那我走啦',}",
  [551964] = "{id=551964,Text='嗯嗯，暂时再见啦，[c][ffff00][PlayerName][-][/c]！',Speaker=816710,}",
  [551965] = "{id=551965,Text='以后回到学院，还要记得来摸摸我哦~',Speaker=816710,}",
  [551966] = "{id=551966,Text='[c][ffff00][PlayerName][-][/c]，又见面了，职业大厅里的一切都顺利吗？',Speaker=816701,Option='描述',Emoji=17,}",
  [551967] = "{id=551967,Text='嗯嗯，我知道了。\n谢谢你包容奥尔加的调皮，也恭喜你转职成功。',Speaker=816701,Emoji=39,}",
  [551968] = "{id=551968,Text='好希望和你再相处一段时间，可惜……分别的时刻到呀。',Speaker=816701,Option='{这么快？,99},{好突然！,99}',}",
  [551969] = "{id=551969,Text='我也舍不得你呀，但你还有使命需要完成。',Speaker=816701,}",
  [551970] = "{id=551970,Text='记得我最开始说的话吗？我们所在的这片米德加尔特大陆看似和平，实则危机四伏。',Speaker=816701,}",
  [551971] = "{id=551971,Text='在这种情况下，拥有潜质的年轻人被命运感召，踏上拯救世界的旅行。',Speaker=816701,}",
  [551972] = "{id=551972,Text='命运将你引导向学院，接受知识的传承。而往后的冒险之旅，还要你自己闯荡。',Speaker=816701,}",
  [551973] = "{id=551973,Text='[c][ffff00][PlayerName][-][/c]，前往普隆德拉的南门吧。',Speaker=816701,}",
  [551974] = "{id=551974,Text='这是我能给你的最后的指引，也是我们暂时的告别。',Speaker=816701,}",
  [551975] = "{id=551975,Text='总有一天，我会从他人口中再听到你的名字。那必将是世人把你的事迹传唱。',Speaker=816701,}",
  [551976] = "{id=551976,Text='[c][ffff00][PlayerName][-][/c]，前往白云深处的罗扎纳吧。',Speaker=816701,}",
  [551977] = "{id=551977,Text='这是我能给你的最后的指引，也是我们暂时的告别。',Speaker=816701,}",
  [551978] = "{id=551978,Text='总有一天，我会从他人口中再听到你的名字，那必将是世人把你的事迹传唱。',Speaker=816701,}",
  [551979] = "{id=551979,Text='[c][ffff00][PlayerName][-][/c]，又见面了，职业大厅里的一切都顺利吗？',Speaker=816701,Option='描述',Emoji=17,}",
  [551980] = "{id=551980,Text='嗯嗯，我知道了。\n谢谢你包容奥尔加的调皮，也恭喜你转职成功。',Speaker=816701,Emoji=39,}",
  [551981] = "{id=551981,Text='好希望和你再相处一段时间，可惜……分别的时刻到呀。',Speaker=816701,Option='{这么快？,99},{好突然！,99}',}",
  [551982] = "{id=551982,Text='我也舍不得你呀，但你还有使命需要完成。',Speaker=816701,}",
  [551983] = "{id=551983,Text='记得我最开始说的话吗？我们所在的这片米德加尔特大陆看似和平，实则危机四伏。',Speaker=816701,}",
  [551984] = "{id=551984,Text='在这种情况下，拥有潜质的年轻人被命运感召，踏上拯救世界的旅行。',Speaker=816701,}",
  [551985] = "{id=551985,Text='命运将你引导向学院，接受知识的传承。而往后的冒险之旅，还要你自己闯荡。',Speaker=816701,}",
  [551986] = "{id=551986,Text='[c][ffff00][PlayerName][-][/c]，前往普隆德拉的南门吧。',Speaker=816701,}",
  [551987] = "{id=551987,Text='这是我能给你的最后的指引，也是我们暂时的告别。',Speaker=816701,}",
  [551988] = "{id=551988,Text='总有一天，我会从他人口中再听到你的名字。那必将是世人把你的事迹传唱。',Speaker=816701,}",
  [551989] = "{id=551989,Text='[c][ffff00][PlayerName][-][/c]，前往白云深处的罗扎纳吧。',Speaker=816701,}",
  [551990] = "{id=551990,Text='这是我能给你的最后的指引，也是我们暂时的告别。',Speaker=816701,}",
  [551991] = "{id=551991,Text='总有一天，我会从他人口中再听到你的名字，那必将是世人把你的事迹传唱。',Speaker=816701,}",
  [551992] = "{id=551992,Text='我将把你送往普隆德拉南门（或者罗扎纳）。',Speaker=816701,}",
  [551993] = "{id=551993,Text='你准备好了吗？',Speaker=816701,Option='{准备好了,99},{再等等,99}',}",
  [551994] = "{id=551994,Text='好的，我随时在这里等你哒~',Speaker=816701,}",
  [551995] = "{id=551995,Text='……真遗憾啊，我们错过了见证你成长的机会。',Speaker=816701,}",
  [551996] = "{id=551996,Text='可同时，你又让我感到很欣慰。',Speaker=816701,}",
  [551997] = "{id=551997,Text='你早已成长为了合格的勇士，足以肩负起命运的重托：\n你解决了米德加尔特大陆上的许多危机，而今后也将继续守护它的安宁。',Speaker=816701,}",
  [551998] = "{id=551998,Text='英雄啊，你的学院之旅已经结束了，但你的使命还在前方等待你。',Speaker=816701,}",
  [551999] = "{id=551999,Text='请像自由的风一样远行飞翔吧！',Speaker=816701,}",
  [552000] = "{id=552000,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
