  [552055] = "{id=552055,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552056] = "{id=552056,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552057] = "{id=552057,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552058] = "{id=552058,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552059] = "{id=552059,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552060] = "{id=552060,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552061] = "{id=552061,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552062] = "{id=552062,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552063] = "{id=552063,Text='[c][ffff00][PlayerName][-][/c]，一会儿没见，你都成为剑士了。\n想必选择职业的过程都很顺利吧。',Speaker=816701,Option='{很顺利,2},{有点小情况,3}',Emoji=17,}",
  [552064] = "{id=552064,Text='唔，奥尔加竟然做了这样的事吗？\n一会儿我会好好教育它的。',Speaker=816701,Emoji=12,}",
  [552065] = "{id=552065,Text='嗯，我就知道你没问题的。',Speaker=816701,}",
  [552066] = "{id=552066,Text='目前为止，你已经完成了所有的初学者任务，可在在学院中自由活动、暂时放松一下。',Speaker=816701,}",
  [552067] = "{id=552067,Text='王立克里图拉学院是一个崇尚自由、包罗万象的地方，你一定能发现很多有趣的细节。',Speaker=816701,}",
  [552068] = "{id=552068,Text='另外，遇到有人求助时，也请不要拒绝。帮助他人是学院的传统，也是许多传奇冒险的开始。',Speaker=816701,}",
  [552069] = "{id=552069,Text='被命运选中的勇者，可不要错过属于自己的机缘哦~',Speaker=816701,}",
  [552070] = "{id=552070,Text='别扒拉我，我要用眼泪在地上写7个大大的“惨”字。',Speaker=816715,Option='你怎么了？',Emoji=24,}",
  [552071] = "{id=552071,Text='你看不出来吗？我在经受爱情的折磨啊！',Speaker=816715,}",
  [552072] = "{id=552072,Text='我的发小兼恋人又生气了，却连原因都不想告诉我。\n她一定是厌倦我了，毕竟她是那么优秀，而我只是个学院吊尾车。',Speaker=816715,Emoji=24,}",
  [552073] = "{id=552073,Text='我们的感情走到了尽头，我的人生已经没有希望了！',Speaker=816715,Option='别那么悲观啊',}",
  [552074] = "{id=552074,Text='说、说得也对！咸鱼还要翻身呢，被甩之前，我总得挣扎一下。',Speaker=816715,}",
  [552075] = "{id=552075,Text='这位学弟，你能代我打探一下她生气的原因吗？\n辛妮娅很喜欢新生，应该会向你透露一些线索。',Speaker=816715,Option='{好的,8},{我还有事,6}',}",
  [552076] = "{id=552076,Text='这位学妹，你能代我打探一下她生气的原因吗？\n辛妮娅很喜欢新生，应该会向你透露一些线索。',Speaker=816715,Option='{好的,5},{我还有事,6}',}",
  [552077] = "{id=552077,Text='呃……那我在这里等你一会儿？帮人帮到底嘛，拜托你了！',Speaker=816715,}",
  [552078] = "{id=552078,Text='太感谢了！辛妮娅就坐在紫藤树餐厅里。最漂亮的那个女孩就是她！',Speaker=816715,}",
  [552079] = "{id=552079,Text='垃圾雷纳德，气死我了，气死我了！',Speaker=816714,Option='学姐你好呀？',}",
  [552080] = "{id=552080,Text='嗯，有新生？',Speaker=816755,Emoji=8,}",
  [552081] = "{id=552081,Text='不好意思，让你看到我失态了。\n是需要什么帮助吗？',Speaker=816714,}",
  [552082] = "{id=552082,Text='原来是担心我啊？真是个可爱的小家伙！',Speaker=816714,}",
  [552083] = "{id=552083,Text='其实也不是什么严重的事情啦。\n就是有个混蛋，明明答应过我会好好学习，却连书都没有开过，就把书还回了藏书馆去。',Speaker=816714,Emoji=12,}",
  [552084] = "{id=552084,Text='而且、而且……',Speaker=816714,}",
  [552085] = "{id=552085,Text='那本书里还有我难得写的情书啦！承载了我的鼓励和心意！',Speaker=816714,Emoji=12,}",
  [552086] = "{id=552086,Text='然而雷纳德那个白痴根本没有收到！',Speaker=816714,}",
  [552087] = "{id=552087,Text='真是气死我啦！啊啊啊——！！！',Speaker=816714,}",
  [552088] = "{id=552088,Text='真相居然是这样吗？那本书里还夹着辛妮娅的情书！',Speaker=816715,Emoji=1,}",
  [552089] = "{id=552089,Text='是我的错，不仅让她失望，还错失了她的心意。',Speaker=816715,}",
  [552090] = "{id=552090,Text='不行，我得挽回这一切！',Speaker=816715,}",
  [552091] = "{id=552091,Text='辛妮娅的情书不能留在藏书馆里。\n如果让别人看到这封情书还宣扬出去，一定会令她为难的。',Speaker=816715,}",
  [552092] = "{id=552092,Text='[c][ffff00][PlayerName][-][/c]，请和我一起找回辛妮娅的情书吧！',Speaker=816715,Option='好',}",
  [552093] = "{id=552093,Text='谢谢你，[c][ffff00][PlayerName][-][/c]，今天你就是我异父异母的亲兄弟（姐妹）了！',Speaker=816715,}",
  [552094] = "{id=552094,Text='我们这就出发去皇家藏书馆吧！',Speaker=816715,}",
  [552095] = "{id=552095,Text='在我印象里，辛妮娅为我借的应该是一本历史书。\n我们分头搜寻吧，但愿它还没被人借走。',Speaker=816715,}",
  [552096] = "{id=552096,Text='是这本吗？还是那一本？',Speaker=816715,}",
  [552097] = "{id=552097,Text='“千年前，魔王梦罗克连同龙族一起向神族与巨人族发起战争，试图夺取九界的统治权。',Speaker=816711,}",
  [552098] = "{id=552098,Text='最后神族与巨人族险胜，迫使梦罗克逃往异世界。',Speaker=816711,}",
  [552099] = "{id=552099,Text='而为了拯救因战争而危在旦夕的天地树，始祖巨人依米尔牺牲自己，用自己的血肉重铸了九界。',Speaker=816711,}",
  [552100] = "{id=552100,Text='之后重伤的神王奥丁也遭受魔狼芬里尔的偷袭，至今下落不明……',Speaker=816711,}",
  [552101] = "{id=552101,Text='从此，诸神时代落幕，人类登上历史的舞台。”',Speaker=816711,}",
  [552102] = "{id=552102,Text='没有找到辛妮娅的情书。',}",
  [552103] = "{id=552103,Text='“相传，王立克里图拉学院的改建有神族参与。为弥补诸神黄昏中折损的英灵，一位女武神受命下凡，引领具有潜质的冒险者们。',Speaker=816713,}",
  [552104] = "{id=552104,Text='群星跟着她一起降落，形成了普隆德拉东门的星泪湖。而这位女武神至今仍潜伏在学院中，不断观察、培养着新生们……”',Speaker=816713,}",
  [552105] = "{id=552105,Text='没有找到辛妮娅的情书。',}",
  [552106] = "{id=552106,Text='“……勇士们挫败了巴风特复活魔王梦罗克的阴谋，保卫了米德加尔特大陆的和平。',Speaker=816712,}",
  [552107] = "{id=552107,Text='但是，一切都还没有结束……',Speaker=816712,}",
  [552108] = "{id=552108,Text='一个名为女神之手的组织在阴暗中伸出邪恶的双手，为掠夺散落在世界各地的伊米尔之心碎片，不择手段。',Speaker=816712,}",
  [552109] = "{id=552109,Text='有一件事情已经毋庸置疑：我们应当阻止女神之手，守护米德加尔特大陆的和平。”',Speaker=816712,}",
  [552110] = "{id=552110,Text='找到辛妮娅的情书啦！',}",
  [552111] = "{id=552111,Text='怎么样，找到辛妮娅的情书了吗？',Speaker=816715,}",
  [552112] = "{id=552112,Text='太好了，找回情书，辛妮娅应该能原谅我了。',Speaker=816715,}",
  [552113] = "{id=552113,Text='[c][ffff00][PlayerName][-][/c]，我先回紫藤树餐厅了啦！',Speaker=816715,}",
  [552114] = "{id=552114,Text='[c][ffff00][PlayerName][-][/c]，我刚刚突然想到：\n就这么两手空空地跑去道歉，会不会显得很没诚意啊？',Speaker=816715,Option='{是有点,2},{不至于吧,3}',}",
  [552115] = "{id=552115,Text='果然，你也是这样认为的。',Speaker=816715,}",
  [552116] = "{id=552116,Text='可能吧……但不做些什么，总觉得心里过意不去。',Speaker=816715,}",
  [552117] = "{id=552117,Text='这样吧，辛妮娅很喜欢星泪湖畔的月光花，我们一起采集月光花，送给她做赔礼怎么样？',Speaker=816715,Option='{没问题,5},{这是你的事,6}',}",
  [552118] = "{id=552118,Text='呜哇！你真是一个绝世大好人，我和辛妮娅修成正果的时候，绝对会请你来参加婚礼的！',Speaker=816715,}",
  [552119] = "{id=552119,Text='诶，别、别这么绝情嘛！我们可是刚刚相认过的亲兄弟（姐弟）啊！那地方我一个人不敢去啊！',Speaker=816715,Emoji=18,}",
  [552120] = "{id=552120,Text='算我求你啦，不会花费很多时间的，事后我请你在紫藤树餐厅吃饭呀~',Speaker=816715,}",
  [552121] = "{id=552121,Text='好吧……',}",
  [552122] = "{id=552122,Text='万分感谢，那我们现在就去星泪湖畔吧！',Speaker=816715,}",
  [552123] = "{id=552123,Text='过了这座桥，就是星泪湖北岸，月光花就生长在那边的林地里。',Speaker=816715,}",
  [552124] = "{id=552124,Text='不过，采集鲜花的时候，请不要离我太远……\n如果我喊救命，一定要赶来救我啊！',Speaker=816715,Option='啥？',Emoji=37,}",
  [552125] = "{id=552125,Text='你没听说过学院恐的怖故事吗？就是、就是学院里有个可怕的魔兽，专门惩罚不好好学习、到野外摸鱼的学生。',Speaker=816715,}",
  [552126] = "{id=552126,Text='我的一个哥们儿，就因为拖欠论文三周，被它挂到了树上。',Speaker=816715,}",
  [552127] = "{id=552127,Text='因为和辛妮娅闹矛盾，我也两天没去上课了。我有预感，它也会找上我的……',Speaker=816715,Option='那我们回去？',Emoji=37,}",
  [552128] = "{id=552128,Text='不、不行！为了挽回辛妮娅，我不能就这么放弃！',Speaker=816715,}",
  [552129] = "{id=552129,Text='呃啊啊啊——我豁出去啦——！！！',Speaker=816715,Emoji=23,}",
  [552130] = "{id=552130,Text='啊啊啊啊啊——！！！魔兽真的出现啦！！！',Speaker=816715,}",
  [552131] = "{id=552131,Text='[c][ffff00][PlayerName][-][/c]，救命啊！！！！！',Speaker=816715,}",
  [552132] = "{id=552132,Text='呜呼~不听话的坏孩子，被我抓到咯~',Speaker=816718,Emoji=5,}",
  [552133] = "{id=552133,Text='啊啊啊……辛妮娅、[c][ffff00][PlayerName][-][/c]，快来救我啊！',Speaker=816715,}",
  [552134] = "{id=552134,Text='快放开他！',}",
  [552135] = "{id=552135,Text='咦~居然还有一个，而且闻起来比第一个更可口！',Speaker=816718,Emoji=5,}",
  [552136] = "{id=552136,Text='我改变主意了，换你来陪我玩吧！',Speaker=816718,}",
  [552137] = "{id=552137,Text='呜呜呜……\n我、我会搬救兵过来的！[c][ffff00][PlayerName][-][/c]，在这之前你一定要撑住！',Speaker=816715,Emoji=18,}",
  [552138] = "{id=552138,Text='呜呼，你的身上居然还有命运女神的加护！\n难怪闻起来这么香！',Speaker=816718,}",
  [552139] = "{id=552139,Text='不过，它现在是我的了——啊呜！',Speaker=816718,}",
  [552140] = "{id=552140,Text='呜呼呼呼呼，过去的克鲁鲁已经不在了，现在的我是——大魔王克鲁鲁！',Speaker=816718,}",
  [552141] = "{id=552141,Text='愚蠢的两脚兽，多谢你的馈赠。作为回礼，我将带给这座学院更多难忘的噩梦！',Speaker=816718,}",
  [552142] = "{id=552142,Text='[c][ffff00][PlayerName][-][/c]，快醒醒，你可不能沉睡在黑夜里。',Speaker=816737,}",
  [552143] = "{id=552143,Text='这里是？',}",
  [552144] = "{id=552144,Text='这里是揭示命运的幻境，夹杂着过去、现在和未来的幻影。你眼前这颗樱花树，昭示着即将到来的危机：',Speaker=816737,}",
  [552145] = "{id=552145,Text='“彩虹碎片自天空坠落，大地和神木显出异变。漫长的黑夜不见尽头，唯有真正的勇士才能带回黎明。”',Speaker=816737,}",
  [552146] = "{id=552146,Text='如今，危机悄然靠近。\n而你，预言中的命运之风，也已经出现。',Speaker=816737,}",
  [552147] = "{id=552147,Text='……可我被打败了。',Emoji=16,}",
  [552148] = "{id=552148,Text='哈哈，别灰心。\n一时的挫折并不意味着失败，人都是会成长的呀。',Speaker=816737,}",
  [552149] = "{id=552149,Text='来，站起来！\n重拾你的勇气、信心和决心，逃离黑暗，重返光明吧！',Speaker=816737,}",
  [552150] = "{id=552150,Text='重拾我，勇敢地迎接命运。',Speaker=816732,}",
  [552151] = "{id=552151,Text='重拾我，无悔地迎接命运。',Speaker=816733,}",
  [552152] = "{id=552152,Text='重拾我，坚定地迎接命运。',Speaker=816734,}",
  [552153] = "{id=552153,Text='勇气、信念、决心都找回来了。',Speaker=816737,}",
  [552154] = "{id=552154,Text='我们快前往下一重梦境吧！',Speaker=816737,}",
  [552155] = "{id=552155,Text='[c][ffff00][PlayerName][-][/c]，快看。\n那边的天空是白色的，梦境的出口就在那个方向。',Speaker=816737,}",
  [552156] = "{id=552156,Text='不自量力的蝼蚁，竟敢反抗我。',Speaker=816720,}",
  [552157] = "{id=552157,Text='大魔王梦罗克！',Emoji=1,}",
  [552158] = "{id=552158,Text='[c][ffff00][PlayerName][-][/c]，大胆地往前走。这里交给我们，而你属于未来！',Speaker=816721,}",
  [552159] = "{id=552159,Text='为了阿斯加德！',Speaker=816722,}",
  [552160] = "{id=552160,Text='为了米德加尔特！',Speaker=816754,}",
  [552161] = "{id=552161,Text='站住，把伊米尔之心的碎片交出来！',Speaker=816726,}",
  [552162] = "{id=552162,Text='不然，就成为我的傀儡哦~',Speaker=816725,}",
  [552163] = "{id=552163,Text='这莫非是，女神之手？',}",
  [552164] = "{id=552164,Text='[c][ffff00][PlayerName][-][/c]，这里由我们顶住。你一定要返回现世，你一定要阻止她们！',Speaker=816727,}",
  [552165] = "{id=552165,Text='放弃吧，愚蠢的两脚兽。你连我都战胜不了，还妄想拯救世界？',Speaker=816718,}",
  [552166] = "{id=552166,Text='失去命运的加护，你只是个再平庸不过的凡人。',Speaker=816718,Option='{那又如何！,2},{别小看我！,2}',}",
  [552167] = "{id=552167,Text='我还有勇气、信念和决心！',}",
  [552168] = "{id=552168,Text='我还有前人的期望和嘱托和必须完成的使命。',}",
  [552169] = "{id=552169,Text='让开！',}",
  [552170] = "{id=552170,Text='魔兽消失了。\n原来它只是个幻象。',}",
  [552171] = "{id=552171,Text='[c][ffff00][PlayerName][-][/c]，你做的很好。我就知道你能够突破自我的。',Speaker=816737,}",
  [552172] = "{id=552172,Text='走吧，快回去吧，大家都在等待你呢。',Speaker=816737,}",
  [552173] = "{id=552173,Text='呜呜呜，[c][ffff00][PlayerName][-][/c]，你醒醒啊咕！\n我们才刚交上朋友，你就要离我而去吗？',Speaker=816710,Emoji=42,}",
  [552174] = "{id=552174,Text='呜哇——是我跑得太慢了，没能赶回来支援你。[c][ffff00][PlayerName][-][/c]，你好惨啊~~~',Speaker=816715,Emoji=42,}",
  [552175] = "{id=552175,Text='……喂喂，[c][ffff00][PlayerName][-][/c]只是昏过去，又不是死掉了！\n你们稍微克制一下啊。',Speaker=816707,Emoji=10,}",
  [552176] = "{id=552176,Text='咪呜，你们看，冒险者这不就醒来了吗~',Speaker=816709,}",
  [552177] = "{id=552177,Text='雷纳德带我们找到你的时候，你一动不动地躺在地上，吓坏大家咯喵。',Speaker=816709,}",
  [552178] = "{id=552178,Text='不过还好，虽然被抢走了「命运的加护」，但你的身体没有大碍呢。\n经过我的治疗，已经完全恢复了。',Speaker=816709,Option='{恶魔的下落,99},{被抢夺的力量,99}',}",
  [552179] = "{id=552179,Text='咪呜，这个我们有在处理啦。',Speaker=816709,Emoji=18,}",
  [552180] = "{id=552180,Text='希格德莉法通过魔法追踪到了恶魔的老巢，已经带领护卫队前去讨伐了。\n但是……',Speaker=816709,}",
  [552181] = "{id=552181,Text='但是？',Emoji=8,}",
  [552182] = "{id=552182,Text='但是过程不怎么顺利。在你昏迷期间，我们收到一条简短的求援信息，随后就和护卫队彻底失联。',Speaker=816707,}",
  [552183] = "{id=552183,Text='恐怕「命运的加护」壮大了恶魔的力量，光靠先遣队无法战胜它。',Speaker=816707,Option='{我也来帮忙,99},{我也要战斗,99}',}",
  [800038] = "{id=800038,Text='当当当~亲爱的里莫森爷爷，欢迎你的到来！',Speaker=816083,}",
  [800039] = "{id=800039,Text='你们是？',Speaker=816076,}",
  [800040] = "{id=800040,Text='我们是你忠诚的老朋友！',Speaker=816083,}",
  [800041] = "{id=800041,Text='请让我们来给您唱首歌儿吧~啦啦啦啦啦~',Speaker=816083,}",
  [800042] = "{id=800042,Text='接下来是焰火表演哦！',Speaker=816083,}",
  [800043] = "{id=800043,Text='砰砰砰！请尽情欣赏！',Speaker=816083,}",
  [800044] = "{id=800044,Text='再见了里莫森爷爷，最美好的祝福献给你！',Speaker=816080,}",
  [800045] = "{id=800045,Text='记得常回来看看我们哦！',Speaker=816078,}",
  [800046] = "{id=800046,Text='再见，再见！',Speaker=816079,}",
  [800062] = "{id=800062,Text='前方发现混沌踪迹！',Speaker=816117,}",
  [800063] = "{id=800063,Text='队长请下达命令！',Speaker=816118,}",
  [800064] = "{id=800064,Text='你们负责断后！（对你）冒险者，该我们出场了！',Speaker=816116,}",
  [800065] = "{id=800065,Text='我正将自己的力量注入你体内，混沌巨兽极其强大，但是龙息守备定能驱散阴影！',Speaker=816116,}",
  [800066] = "{id=800066,Text='使用绝技[c][ffff00]苍龙破魇[-][/c]！在被敌人发现前迅速出击！',Speaker=816116,}",
  [800067] = "{id=800067,Text='注意混沌[c][ffff00]极为强大[-][/c]！切莫被敌人发现！',Speaker=816116,}",
  [800068] = "{id=800068,Text='你成功了!勇士。',Speaker=816116,}",
  [800078] = "{id=800078,Text='梦魇之火就在面前。',Speaker=816119,}",
  [800079] = "{id=800079,Text='都怪我太大意，没能彻底消灭它。',Speaker=816119,}",
  [800080] = "{id=800080,Text='跟随我先前留下的标记，可以绕开火焰。',Speaker=816119,}",
  [800081] = "{id=800081,Text='一定请务必小心，[c][ffff00]不要碰到紫色的邪火[-][/c]。',Speaker=816119,}",
  [800082] = "{id=800082,Text='你成功了……',Speaker=816119,}",
  [800085] = "{id=800085,Text='干的好！但是不要松懈，前方还有更多目标！',Speaker=816116,}",
  [800095] = "{id=800095,Text='总有一天，我要成为洛阳的大英雄！',Speaker=816186,}",
  [800119] = "{id=800119,Text='你似乎来到了拉扎罗的回忆片段里……',}",
  [800120] = "{id=800120,Text='嘿，哈！',Speaker=816190,}",
  [800121] = "{id=800121,Text='哈哈哈，我的实力似乎越来越强了呢。',Speaker=816190,}",
  [800122] = "{id=800122,Text='我的同伴们已经没有人打得过我了，看来,我要确立一个新的追赶目标了。',Speaker=816190,}",
  [800123] = "{id=800123,Text='唔……洛阳的守护神古恩大人我可不敢攀比，那就——乌洛大人吧！',Speaker=816190,}",
  [800124] = "{id=800124,Text='哈哈哈早晚有一天，我要成为像乌洛那样的大英雄！',Speaker=816190,}",
  [800125] = "{id=800125,Text='不，或许，我会比他还要强大！',Speaker=816190,Emoji=17,}",
  [800126] = "{id=800126,Text='哼，狂妄的家伙，竟敢对乌洛哥哥不敬。',Speaker=816188,}",
  [800127] = "{id=800127,Text='本小姐要给你点厉害尝尝!',Speaker=816188,}",
  [800128] = "{id=800128,Text='呜呜呜呜呜……',Speaker=816190,}",
  [800129] = "{id=800129,Text='（惊恐）乌洛大人万岁，乌洛大人万岁！',Speaker=816190,}",
  [800155] = "{id=800155,Text='怎么打败',}",
  [800159] = "{id=800159,Text='有道理',}",
  [800162] = "{id=800162,Text='当然',}",
  [800166] = "{id=800166,Text='完美无瑕',}",
  [800168] = "{id=800168,Text='满脸问号',}",
  [800245] = "{id=800245,Text='辉夜！我从不死鸟的身体里找到了这个！',Speaker=816218,Emoji=17,}",
  [800246] = "{id=800246,Text='这是什么？',Speaker=816217,}",
  [800247] = "{id=800247,Text='是不死灵药！如果吃了这个，我们都会长生不老！',Speaker=816218,}",
  [800248] = "{id=800248,Text='我们会永远在一起……',Speaker=816218,}",
  [800249] = "{id=800249,Text='宗布……我感觉……我好像在变轻……',Speaker=816217,Emoji=7,}",
  [800250] = "{id=800250,Text='我、我站不住了！',Speaker=816217,Emoji=8,}",
  [800251] = "{id=800251,Text='辉夜朝着天空飞去，离地面越来越远……',}",
  [800252] = "{id=800252,Text='不！辉夜！',Speaker=816218,}",
  [800253] = "{id=800253,Text='辉夜！！！',Speaker=816218,}",
  [800261] = "{id=800261,Text='记得就好！阿卡娜的入侵，那可真是一场惨烈的战役啊。',Speaker=817158,}",
  [800262] = "{id=800262,Text='（瞪了你一眼）真搞不明白你的脑袋瓜里都装了些什么。',Speaker=817158,Emoji=14,}",
  [800263] = "{id=800263,Text='之前彩虹桥意外坠落，碎片四散到了大陆各地。掉到天津町的那枚碎片呢，就异变成了这棵御神樱。',Speaker=817158,}",
  [800264] = "{id=800264,Text='随后呢，一个自称是阿卡娜的古怪女人，带着张牙舞爪的精灵族入侵了米德加尔特……看着就是来抢走彩虹桥碎片的。',Speaker=817158,}",
  [800265] = "{id=800265,Text='（耸耸肩）……最后我们自然是把阿卡娜打跑了。但也付出了很大的代价。',Speaker=817158,Option='是这样啊',}",
  [800266] = "{id=800266,Text='很高兴见到你，冒险者~',Speaker=1265,}",
  [800267] = "{id=800267,Text='恩？你看起来很没精神呢！果然你需要一个本店新推出的[c][ffff00]暖身料理[-][/c]，我们现在免费试吃哦~',Speaker=1265,}",
  [800268] = "{id=800268,Text='不过免费的试吃只有一次哦，你想现在品尝吗？',Speaker=1265,Option='{立刻就要吃,2},{等会再来吃,7}',}",
  [800269] = "{id=800269,Text='看来你很满意本店的[c][ffff00]暖身料理[-][/c]啊，是不是要打包一份呢？只需要[c][ffff00]5000zeny[-][/c]哦？',Speaker=1265,}",
  [800270] = "{id=800270,Text='那么现在的你，看起来暖洋洋的，祝你冒险愉快咯！~',Speaker=1265,}",
  [800271] = "{id=800271,Text='随时欢迎你再来哦，免费的试吃随时为你准备',Speaker=1265,}",
  [800272] = "{id=800272,Text='你的钱不够哦，欢迎下次光临…',Speaker=1265,}",
  [800274] = "{id=800274,Text='要打开仓库了呢，谢谢您的使用！',Speaker=823480,Option='{好的,2}{下次吧,1}',Emoji=6,Action={actionid=34,num=1},}",
  [800277] = "{id=800277,Text='现在帮你打开仓库了，请好好利用！',Speaker=823480,Option='{打开仓库,2},{下次吧,3}',}",
  [800300] = "{id=800300,Text='这里的执念气息太重了，已经影响到了周围的事物。',}",
  [800301] = "{id=800301,Text='必须尽快循着执念气息的轨迹找到源头！',}",
  [800302] = "{id=800302,Text='罗杰！这个逆子，非要去当什么海上战士！',Speaker=825163,}",
  [800303] = "{id=800303,Text='身为巴尔特家族之人应当与利益为重，为家族带来更多的价值，难道我这个傻儿子不明白吗！',Speaker=825163,}",
  [800304] = "{id=800304,Text='哼！我是不会同意他出海的，他休想得到我的认可！',Speaker=825163,Emoji=12,}",
  [800305] = "{id=800305,Text='那是阿莱尔，他的愤怒使得他的执念气息更强了！',}",
  [800306] = "{id=800306,Text='情绪精灵在保护阿莱尔，不让人靠近！',}",
  [800307] = "{id=800307,Text='阿莱尔的情绪目前很不稳定，看来此时不是与他交谈的好时机。',}",
  [800308] = "{id=800308,Text='如果能找到那名叫罗杰的青年，或许能获取什么线索。',}",
  [800330] = "{id=800330,Text='冒险者我感受到了幽灵的气息，请阻止它们！',}",
  [800331] = "{id=800331,Text='冒险者坚持住！',}",
  [800332] = "{id=800332,Text='我探测到灵魂晶石的气息了！',Emoji=17,}",
  [800333] = "{id=800333,Text='通过望远镜观测到灵魂晶石就在附近，不过具体的位置还没有找到，冒险者也帮忙寻找吧！',Speaker=825162,}",
  [800334] = "{id=800334,Text='找到灵魂晶石了，回去告诉罗杰吧！',}",
  [800335] = "{id=800335,Text='这么快就回来了？是找到灵魂晶石了吗？',Speaker=825162,Option='找到了',}",
  [800336] = "{id=800336,Text='太好了！！',Speaker=825162,Emoji=17,}",
  [800337] = "{id=800337,Text='既然找到了灵魂晶石，那我们回去找弗加洛完成交易吧！',Speaker=825162,Option='出发',}",
  [800411] = "{id=800411,Text='第一道是考验你们的灵巧性，“[c][ffff00]通过面前的障碍吧。[-][/c]”。',Speaker=825169,}",
  [800412] = "{id=800412,Text='第三道是考验你们的准确性，“[c][ffff00]需要完整无误的击中目标！[-][/c]”',Speaker=825169,}",
  [800413] = "{id=800413,Text='有点意思，你们的实力有点出乎我的预料！',Speaker=825169,}",
  [800414] = "{id=800414,Text='是我小看了你们，来一场真正的对决吧！',Speaker=825169,}",
  [800415] = "{id=800415,Text='使出全部的实力吧！',}",
  [800416] = "{id=800416,Text='冒险者，我们一起打败他！',}",
  [800417] = "{id=800417,Text='只有打败他才能得到父亲的认可！',Speaker=825162,}",
  [800418] = "{id=800418,Text='你们的实力真让我惊讶！',Speaker=825169,}",
  [800430] = "{id=800430,Text='我熟读巴尔特家族的历史，先祖是先成名于威震四海的海盗，而后建立的巴尔特家族，我认为年轻一辈应该先去了解、熟知海域的各种危险，不经磨砺哪能成为真正的巴尔特家族成员！',Speaker=825162,}",
  [800431] = "{id=800431,Text='我觉得先祖也是这样想的，只是一直以来，我们只关注利益，而忽略了敢于冒险的精神。',Speaker=825162,}",
  [800433] = "{id=800433,Text='在海上可以“[c][ffff00]观察远处事物[-][/c]”的那件先祖遗物，或许可以让父亲明白我的努力！',Speaker=825162,}",
  [800434] = "{id=800434,Text='这是族内大师弗加洛使用的望远镜，我已经获得了大师的认可，他承认我是一名优秀的海上测量师。',Speaker=825162,}",
  [800438] = "{id=800438,Text='在海上可以“[c][ffff00]掌控方向[-][/c]”的那件先祖遗物，或许可以让父亲明白我的优秀。',Speaker=825162,}",
  [800440] = "{id=800440,Text='这一切都是为了完成那个目标，是那个理想在驱使着我前进！',Speaker=825162,}",
  [800442] = "{id=800442,Text='在海上可以“[c][ffff00]自保杀敌[-][/c]”的那件先祖遗物，或许可以让父亲明白我的强大。',Speaker=825162,}",
  [800468] = "{id=800468,Text='这里执念的气息太严重了，已经影响了周围的环境。',}",
  [800469] = "{id=800469,Text='必须尽快循着执念气息的轨迹找到源头！',}",
  [800470] = "{id=800470,Text='乔治家族的高层为什么如此的愚蠢！',Speaker=825211,}",
  [800471] = "{id=800471,Text='明明有强大的力量，却不统治其他王室，要做一个缩头乌龟！',Speaker=825211,Emoji=12,}",
  [800472] = "{id=800472,Text='先祖看到如今的乔治家族，会失望至极吧！',Speaker=825211,}",
  [800473] = "{id=800473,Text='那是杰尔曼，他的愤怒使得他的执念气息更强了！',}",
  [800474] = "{id=800474,Text='愤怒的情绪精灵在保护杰尔曼，不让人靠近！',}",
  [800475] = "{id=800475,Text='乔治家族太愚蠢！',Speaker=825211,}",
  [800476] = "{id=800476,Text='先祖死不瞑目！',Speaker=825211,}",
  [800477] = "{id=800477,Text='杰尔曼因为无法掌控自己的力量，导致力量暴走，现在不要接近他！',Speaker=825212,}",
  [800478] = "{id=800478,Text='你和我先离开这里，我再和你详细说明情况。',Speaker=825212,}",
  [800491] = "{id=800491,Text='请你为当年建国的功臣，赋予对应的官职',Speaker=825213,}",
  [800492] = "{id=800492,Text='我为乔治家族浴血奋战多年，斩杀强敌无数，今天授衔之日，我应该获得应有的官职。',Speaker=825217,Option='{授衔骑士团团长,4},{授衔大贤者,2},{授衔外交官,3}',}",
  [800493] = "{id=800493,Text='每当家族遇到困难时，我用自己的智慧多次帮家族化险为夷，我坚信王室不会亏待我的！',Speaker=825218,Option='{授衔骑士团团长,2},{授衔大贤者,4},{授衔外交官,3}',}",
  [800494] = "{id=800494,Text='每当家族对峙其他国家时，我挺身而出，维护了国家利益，我坚信王室会对我的付出有所回报。',Speaker=825219,Option='{授衔骑士团团长,2},{授衔大贤者,3},{授衔外交官,4}',}",
  [800495] = "{id=800495,Text='王室英明，日后我必鞠躬尽瘁保护王室，尽全力对抗外敌。',Speaker=825217,}",
  [800496] = "{id=800496,Text='大贤者这个职位恐怕并不适合我。',Speaker=825217,}",
  [800497] = "{id=800497,Text='从来没涉及过外交官相关的知识，这个职位并不适合我。',Speaker=825217,}",
  [800498] = "{id=800498,Text='我不擅长武力，这个职位并不适合我。',Speaker=825218,}",
  [800499] = "{id=800499,Text='王室英明，日后我必鞠躬尽瘁保护王室，用其智慧团结王室，发展文明。',Speaker=825218,}",
  [800500] = "{id=800500,Text='外交官相关的工作我不擅长，这个职位不适合我。',Speaker=825218,}",
  [800501] = "{id=800501,Text='我不擅长武力，这个职位并不适合我。',Speaker=825219,}",
  [800502] = "{id=800502,Text='我并不具备贤者的能力，这个职位不适合我。',Speaker=825219,}",
  [800503] = "{id=800503,Text='王室英明，日后我必鞠躬尽瘁维护国家利益。',Speaker=825219,}",
  [800504] = "{id=800504,Text='第二道考验，得到其他家族人的认可，并达成合作。',Speaker=825213,}",
  [800505] = "{id=800505,Text='从来没听过你们家族的名号，想必实力并不怎么样啊，想要和我们达成合作，还得看你们能力如何！',Speaker=825220,Emoji=5,}",
  [800506] = "{id=800506,Text='这样吧，如果你们能和我们王室的强者打个平手，我就承认你们有资格和我们交易。',Speaker=825220,Option='来吧',}",
  [800507] = "{id=800507,Text='你们有几斤几两就由我来试试吧！',Speaker=63298,}",
  [800508] = "{id=800508,Text='可恶，小看你们了！',Speaker=63298,}",
  [800509] = "{id=800509,Text='我……我小看你们了，对你们表示抱歉。',Speaker=825220,Emoji=16,}",
  [800534] = "{id=800534,Text='感受到了熟悉的气息，先上前查看。',}",
  [800535] = "{id=800535,Text='这是玛丽娜的魔力痕迹，或许顺着痕迹，就可以找到她。',}",
  [800536] = "{id=800536,Text='嘿嘿，这人类细皮嫩肉的，应该很好吃，兄弟们，今儿个开荤！',Speaker=63299,}",
  [800537] = "{id=800537,Text='同意，同意！好久没有吃人类了！',Speaker=63299,}",
  [800538] = "{id=800538,Text='你……你们要做什么！',Speaker=825214,Emoji=24,}",
  [800539] = "{id=800539,Text='不要过来！',Speaker=825214,Emoji=24,}",
  [800540] = "{id=800540,Text='住手！',}",
  [800541] = "{id=800541,Text='哪里冒出来不长眼的家伙，竟然扫本大爷的兴致，兄弟们给我干掉他！',Speaker=63299,}",
  [800542] = "{id=800542,Text='可恶，你会后悔的！你给我等着！',Speaker=63299,}",
  [800543] = "{id=800543,Text='你没事吧？有没有受伤？',Emoji=26,}",
  [800544] = "{id=800544,Text='我……我还好。',Speaker=825214,Emoji=38,}",
  [800545] = "{id=800545,Text='你为什么会在这里？',}",
  [800546] = "{id=800546,Text='我是偷偷的从家里跑出来的，主要是想帮家里收集一些水晶石，减轻家里的负担。',Speaker=825214,}",
  [800547] = "{id=800547,Text='找到水晶石后，返程的路上遇到了这些怪物，幸好你及时出现，否则我就回不去了……呜呜……',Speaker=825214,Emoji=24,}",
  [800548] = "{id=800548,Text='没事的，有我在，我会保护你。',Emoji=30,}",
  [800549] = "{id=800549,Text='谢……谢谢你！',Speaker=825214,Emoji=38,}",
  [800550] = "{id=800550,Text='我送你回去吧，路上说不定还会遇到其他危险。',}",
  [800551] = "{id=800551,Text='那就拜托你了！',Speaker=825214,}",
  [800552] = "{id=800552,Text='安全的地点距离这里不远，顺着魔力痕迹就可以到达安全地点了。',}",
  [800553] = "{id=800553,Text='老大，就是这个该死的家伙，若不是他，我早就把鲜美的大餐送到您面前了！',Speaker=63299,}",
  [800554] = "{id=800554,Text='就是这个家伙吗？看起来也不怎么样阿，兄弟们给我做掉他！',Speaker=63300,}",
  [800555] = "{id=800555,Text='又是你们啊，你们真的好烦！不过既然来了，就别回去了！',Emoji=19,}",
  [800556] = "{id=800556,Text='你跟在我的后面，不要乱跑。',}",
  [800557] = "{id=800557,Text='我知道了！',Speaker=825214,}",
  [800558] = "{id=800558,Text='可恶，我好后悔！',Speaker=63300,}",
  [800559] = "{id=800559,Text='“苍蝇”被我拍死了，我们继续赶路吧！',}",
  [800560] = "{id=800560,Text='好，好的！（这人太帅了）',Speaker=825214,Emoji=17,}",
  [800561] = "{id=800561,Text='这里应该很安全了，附近不会有怪物出没。',}",
  [800562] = "{id=800562,Text='谢谢……方便告诉我你的名字吗？',Speaker=825214,Option='杰尔曼',}",
  [800563] = "{id=800563,Text='我记住你的名字了，以后或许还会再见的。',Speaker=825214,Emoji=2,}",
  [800584] = "{id=800584,Text='第一道试炼为极限速杀，你需要击败出现的所有敌人。',Speaker=825215,}",
  [800585] = "{id=800585,Text='准备好了，就去感受试炼之石，开启试炼吧。',Speaker=825215,}",
  [800586] = "{id=800586,Text='你武道之心很稳，看来是我小瞧了你，不过下一道考验就没那么简单了。',Speaker=825215,}",
  [800587] = "{id=800587,Text='接下来的考验为洞察之眼，你需要观察敌人，找出多余的怪物，进行斩杀。',Speaker=825215,Option='如果找错了呢？',}",
  [800588] = "{id=800588,Text='嘿嘿，到时候你就知道了。',Speaker=825215,Emoji=5,}",
  [800589] = "{id=800589,Text='元素之力，生生不息。',Speaker=63313,}",
  [800590] = "{id=800590,Text='武力和眼力都很不错，我承认你是一个不错的对手。',Speaker=825215,}",
  [800591] = "{id=800591,Text='不过也就到此为止了，接下来你的对手是我，做好觉悟了吧？',Speaker=825215,Option='准备好了',}",
  [800592] = "{id=800592,Text='尽全力来战斗吧！',Speaker=825215,}",
  [800593] = "{id=800593,Text='战斗才刚刚开始！',Speaker=825215,}",
  [800594] = "{id=800594,Text='你的实力真是让人感到意外，竟然能压我一头。',Speaker=825215,Emoji=20,}",
  [800595] = "{id=800595,Text='按照之前说的，守护之戒就是你的了，希望你能将这枚戒指的荣誉传承下去。',Speaker=825215,}",
  [800596] = "{id=800596,Text='已经拿到了守护之戒，将戒指带回给劳伦斯吧。',}",
  [800613] = "{id=800613,Text='我需要让你能看到未来之路，所以要在你的身上布置一道魔力阵法。',Speaker=825216,}",
  [800614] = "{id=800614,Text='好了，这样你就可以看到预兆之石了。',Speaker=825216,}",
  [800615] = "{id=800615,Text='另外我可以告诉你乔治家族存在的理念，你根据理念寻找出先祖期望的未来。',Speaker=825216,Option='请说',}",
  [800616] = "{id=800616,Text='乔治家族存在的理念为：“[c][ffff00]命运不会停泊于无能者的港湾[-][/c]”。',Speaker=825216,Option='我知道了',}",
  [800617] = "{id=800617,Text='接下来去寻找你的答案吧。',Speaker=825216,}",
  [800618] = "{id=800618,Text='从散落的莹光晶体中里看到了一行文字：“[c][ffff00]未来将繁荣昌盛[-][/c]”。',}",
  [800619] = "{id=800619,Text='从散落的瑕光晶体中里看到了一行文字：“[c][ffff00]未来将一统王室[-][/c]”。',}",
  [800620] = "{id=800620,Text='从散落的无光晶体中里看到了一行文字：“[c][ffff00]未来将成为孤独的存在[-][/c]”。',}",
  [800621] = "{id=800621,Text='已经得到预兆体对未来道路的暗示，回去找普斯顿大贤者吧。',}",
  [800622] = "{id=800622,Text='你看到了诸多未来的启示，对[c][ffff00]命运不会停泊于无能者的港湾[-][/c]，这句先祖理念是否有了自己的理解？',Speaker=825216,Option='是的',}",
  [800623] = "{id=800623,Text='既然如此，那么将的答案告诉我吧。',Speaker=825216,Option='{未来将繁荣昌盛,5},{未来将一统王室,3},{未来将成为孤独的存在,4}',}",
  [800624] = "{id=800624,Text='你回答的不错，未来繁荣昌盛才是先祖想看到的未来，看来你已经完全理解了乔治家族存在的意义。',Speaker=825216,Emoji=39,}",
  [800625] = "{id=800625,Text='很可惜，这并不是先祖想看到的未来，你再想想吧。',Speaker=825216,Emoji=19,}",
  [800626] = "{id=800626,Text='这与乔治家族的愿景完全相反，你再好好想想。',Speaker=825216,Emoji=19,}",
  [800627] = "{id=800627,Text='黄宝石之心已经认可了你，我已经感受到了它的共鸣之力，我这就把它交给你。',Speaker=825216,}",
  [800628] = "{id=800628,Text='我已经把黄宝石之心交给你，快去做你应该做的事情吧！',Speaker=825216,}",
  [800636] = "{id=800636,Text='承载建国和外交理念的那件标志，可以证明这一点。',Speaker=825212,}",
  [800639] = "{id=800639,Text='不……那件承载着强烈爱意的礼物或许可以证明。',Speaker=825212,}",
  [800643] = "{id=800643,Text='能证明荣誉的那件物品或许能让他找回信心。',Speaker=825212,}",
  [800646] = "{id=800646,Text='能代表家族存在理念的，也只有那个东西了。',Speaker=825212,}",
  [800653] = "{id=800653,Text='元素之力，生生不息。',Speaker=63314,}",
  [800654] = "{id=800654,Text='元素之力，生生不息。',Speaker=63315,}",
  [800655] = "{id=800655,Text='元素之力，生生不息。',Speaker=63316,}",
  [800656] = "{id=800656,Text='罗杰你这个不听话的逆子！',}",
  [800657] = "{id=800657,Text='逆子休想得到我的认可！',}",
  [800660] = "{id=800660,Text='第二道考验，“[c][ffff00]屏幕出现光圈后及时点击，[-][/c]”就算通过考验！',Speaker=825169,}",
  [800661] = "{id=800661,Text='看来你身手还不错，是我看走眼了。',Speaker=825169,}",
  [800662] = "{id=800662,Text='冒险者加油，已经找到线索了！',}",
  [800670] = "{id=800670,Text='请狠狠的教训这个无理的家伙。',Speaker=825218,}",
  [800671] = "{id=800671,Text='这个家伙太可恶了！',Speaker=825218,}",
  [800672] = "{id=800672,Text='竟然敢小瞧我们，等着被教训吧。',Speaker=825219,}",
  [800673] = "{id=800673,Text='加油！打爆他！',Speaker=825219,}",
  [800705] = "{id=800705,Text='这里居然会产生这么强的执念之力，甚至环境都被改变。',}",
  [800706] = "{id=800706,Text='我得找到执念之力的源头，但需要先找到执念轨迹！',}",
  [800707] = "{id=800707,Text='一群迂腐的老顽固！',Speaker=825262,}",
  [800708] = "{id=800708,Text='雷根弗莱格真是顽固不化！',Speaker=825262,}",
  [800709] = "{id=800709,Text='武力这种老掉牙的东西竟仍在推崇，这个时代有足够的智慧才能拥有一切！',Speaker=825262,}",
  [800710] = "{id=800710,Text='我要你们…你们所有人，都为这种迂腐付出代价！',Speaker=825262,}",
  [800711] = "{id=800711,Text='糟了，保尔夫的愤怒让执念之力爆发了！',}",
  [800712] = "{id=800712,Text='执念精灵在阻止别人靠近保尔夫！',}",
  [800713] = "{id=800713,Text='只有我才配管理家族！',Speaker=825262,}",
  [800714] = "{id=800714,Text='保尔夫现在深陷执念当中，贸然接近会受伤的！',Speaker=825263,}",
  [800715] = "{id=800715,Text='我们换个地方，我来为你讲明情况。',Speaker=825263,}",
  [800729] = "{id=800729,Text='试炼者，你的任务是完成我们三个的不同考验。第一个是我的武力试炼。',Speaker=825267,}",
  [800730] = "{id=800730,Text='现在，向我证明你的力量吧！',Speaker=825267,}",
  [800731] = "{id=800731,Text='消灭力量守护兽的分身',Speaker=825267,}",
  [800732] = "{id=800732,Text='消灭再次出现的力量守护兽分身',Speaker=825267,}",
  [800733] = "{id=800733,Text='消灭又一次出现的力量守护兽分身',Speaker=825267,}",
  [800734] = "{id=800734,Text='试炼通过，力量水晶出现了',Speaker=825267,}",
  [800735] = "{id=800735,Text='一名强者不仅要有无尽的力量，也要有极快的速度与反应力。准备好接受我的考验了吗？',Speaker=825268,Option='{准备好了,3} {再等一下,2}',}",
  [800736] = "{id=800736,Text='试炼通过，速度水晶出现了',Speaker=825268,}",
  [800737] = "{id=800737,Text='精确的找出弱点，一击制胜也是强者所需的能力。准备好接受我的考验了吗？',Speaker=825269,Option='{准备好了,15} {再等一下,14}',}",
  [800738] = "{id=800738,Text='击中精准分身',Speaker=825269,}",
  [800739] = "{id=800739,Text='试炼通过，精准水晶出现了',Speaker=825269,}",
  [800740] = "{id=800740,Text='你通过了三场试炼，已经取得了召唤武力之剑的资格。现在，拿出三颗水晶启动法阵吧！',Speaker=825267,}",
  [800741] = "{id=800741,Text='武力之剑已经出现，上前将其拿出',Speaker=825267,}",
  [800757] = "{id=800757,Text='爱葛妮斯怎么会被花妖包围！？我得过去救她！',}",
  [800758] = "{id=800758,Text='保护爱葛妮斯不死亡，消灭来袭的花妖',Speaker=825263,}",
  [800759] = "{id=800759,Text='保护爱葛妮斯不死亡，消灭再次来袭的花妖',Speaker=825263,}",
  [800760] = "{id=800760,Text='居然还有这么多的敌人，我已经没力气了……',}",
  [800761] = "{id=800761,Text='难道到这里就结束了吗……',}",
  [800762] = "{id=800762,Text='（怀里的欧石楠在发光！）',}",
  [800763] = "{id=800763,Text='遇到了强大的敌人，你是否愿意为了守护他人对抗敌人？',Speaker=825279,Option='{愿意,3}  {不愿意,2}',}",
  [800764] = "{id=800764,Text='这不是我想要的答案。',Speaker=825279,Emoji=31,}",
  [800765] = "{id=800765,Text='哪怕可能会付出生命？',Speaker=825279,Option='{义不容辞！,5} {还是算了…,4}',}",
  [800766] = "{id=800766,Text='这不是我想要的答案。',Speaker=825279,Emoji=31,}",
  [800767] = "{id=800767,Text='（没想到，这样才能获得真正的欧石楠…！）',}",
  [800768] = "{id=800768,Text='我好像听到了脚步声…',Speaker=825263,Option='是敌人？',Emoji=18,}",
  [800769] = "{id=800769,Text='是谁欺负小白鸽！看我不揍扁他！',Speaker=825264,Emoji=12,}",
  [800790] = "{id=800790,Text='保尔夫去哪了？他明明一直在这来着，不会是被谁带走了吧！',Speaker=825263,Option='分头寻找吧',Emoji=8,}",
  [800791] = "{id=800791,Text='好的，那我们分头找一下，见到保尔夫见机行事吧。',Speaker=825263,}",
  [800792] = "{id=800792,Text='（没有人经过的痕迹，不在这边。）',}",
  [800793] = "{id=800793,Text='（也不在这边……等等，这是什么？）',}",
  [800794] = "{id=800794,Text='（好浓的执念气息，但这痕迹去向怎么像是爱葛妮斯的方向？）',Emoji=1,}",
  [800795] = "{id=800795,Text='哈哈哈哈哈！你们都要被我毁掉！',Speaker=825262,Option='怎么会这样！？',}",
  [800796] = "{id=800796,Text='保尔夫已经彻底被执念控制了……冒险者小心！',Speaker=825263,}",
  [800797] = "{id=800797,Text='（不是说保尔夫不屑用武力吗，怎么会这么强？）',}",
  [800798] = "{id=800798,Text='不就是武力吗？我也有！凭什么不认可我……我要毁了一切！',Speaker=825262,}",
  [800799] = "{id=800799,Text='唉…我先带你们两个离开吧，保尔夫现在的状态你们是唤醒不了他的。',Speaker=825265,}",
  [800800] = "{id=800800,Text='老头子来了还想走？你也要被我毁掉！',Speaker=825262,}",
  [800801] = "{id=800801,Text='传送魔法，启动！',Speaker=825265,}",
  [800806] = "{id=800806,Text='这里是雷根弗莱格家族的秘境，努力寻找到家训的意义吧！',Speaker=825265,}",
  [800807] = "{id=800807,Text='观察突然出现的石碑',Speaker=825265,}",
  [800808] = "{id=800808,Text='（石碑暗淡无光，似乎需要什么东西启动）',}",
  [800809] = "{id=800809,Text='想启动石碑，先打败我们！',Speaker=825276,}",
  [800810] = "{id=800810,Text='击败出现的执念幽灵',Speaker=825265,}",
  [800811] = "{id=800811,Text='（好像还不够……）',}",
  [800812] = "{id=800812,Text='叫破喉咙也没人救你！',Speaker=825276,}",
  [800814] = "{id=800814,Text='是否要救小男孩呢？',Option='{要救,7} {不管,6}',}",
  [800815] = "{id=800815,Text='（因为你的见死不救，考验失败）',Option='尝试救出小男孩',}",
  [800816] = "{id=800816,Text='多管闲事！',Speaker=825276,}",
  [800817] = "{id=800817,Text='谢谢你！这是别人让我给你的，你快拿着吧~',Speaker=825278,Emoji=14,}",
  [800818] = "{id=800818,Text='（石碑显现出文字来。）',}",
  [800819] = "{id=800819,Text='武力能够抵御敌人，能够拯救弱者，但又能对别人造成伤害。',}",
  [800820] = "{id=800820,Text='故特立此家训，[c][ffff00]武力是为了保护弱者、保护家人乃至于保护国家而存在。[-][/c]',}",
  [800821] = "{id=800821,Text='任何违反这一家训的家族成员都要受到惩罚！',}",
  [800822] = "{id=800822,Text='（看来这就是雷根弗莱格家训的核心内容了，我也完成任务了。）',}",
  [800826] = "{id=800826,Text='这下所有的物品都齐了，冒险者你先稍作休息，等休息好之后我们就出发。',Speaker=825263,Option='好的',Emoji=20,}",
  [800831] = "{id=800831,Text='关于武力的意义，可以用这把剑证明。',Speaker=825263,}",
  [800834] = "{id=800834,Text='海尔穆特的心灵，乃至于家族理念的真谛，可以用这件物品证明。',Speaker=825263,}",
  [800837] = "{id=800837,Text='这件事，家族早就体现在了这件物品当中。',Speaker=825263,}",
  [800869] = "{id=800869,Text='很遗憾失败了，从新再来吧！',Speaker=825169,}",
  [800870] = "{id=800870,Text='这里执念的气息太严重了，已经影响了周围的环境。',}",
  [800871] = "{id=800871,Text='必须尽快循着执念气息的轨迹找到源头！',}",
  [800872] = "{id=800872,Text='尤尔根！你为什么不乖乖听我的话！',Speaker=825290,Emoji=12,}",
  [800873] = "{id=800873,Text='参加竞选当上国王统治国家是所有人的追求，为什么你会放弃！',Speaker=825290,Emoji=12,}",
  [800874] = "{id=800874,Text='你到底在想什么！我的尤尔根！',Speaker=825290,Emoji=12,}",
  [800875] = "{id=800875,Text='那是赛琳娜，他的愤怒使得他的执念气息更强了！',}",
  [800876] = "{id=800876,Text='你为什么不理解我的用心！',Speaker=825290,}",
  [800877] = "{id=800877,Text='你到底在想什么！',Speaker=825290,}",
  [800878] = "{id=800878,Text='赛琳娜已经被执念侵蚀了神智，看来此时无法与她正常交流。',}",
  [800879] = "{id=800879,Text='找到赛琳娜口中的尤尔根，或许可以从他口中了解事情的来龙去脉。',}",
  [800907] = "{id=800907,Text='闻到了绘画原料的气味，少女应该在距离此地不远，追寻气味去寻找源头吧。',}",
  [800908] = "{id=800908,Text='尤尔根？',Speaker=825296,}",
  [800909] = "{id=800909,Text='你这家伙还敢来找我！',Speaker=825296,}",
  [800910] = "{id=800910,Text='嗨罗琳！你最近还好吗？',Speaker=825291,}",
  [800911] = "{id=800911,Text='好你个头！！上次明明和我约好一起看烟花，结果你人呢？',Speaker=825296,Emoji=12,}",
  [800912] = "{id=800912,Text='我等你了你一晚上，结果你放了我鸽子！',Speaker=825296,}",
  [800913] = "{id=800913,Text='…………（尤尔根记起来好像确实是有这么一回事）',Speaker=825291,}",
  [800914] = "{id=800914,Text='啊哈哈！看在我这么美丽的份儿上，你就忘了吧！我这不是来找你了！',Speaker=825291,}",
  [800915] = "{id=800915,Text='我对你这个家伙我真的是好无语呀！',Speaker=825296,Emoji=15,}",
  [800916] = "{id=800916,Text='话说你来找我有什么事吗？',Speaker=825296,}",
  [800917] = "{id=800917,Text='我打算利用家族特质的绘画原料来为自己制作一幅自画像。',Speaker=825291,}",
  [800918] = "{id=800918,Text='所以我就来找你了，因为我知道你应该有。',Speaker=825291,}",
  [800919] = "{id=800919,Text='哦……原来是这样……',Speaker=825296,}",
  [800920] = "{id=800920,Text='这样，原料我可以给你，不过你要答应我一件事。',Speaker=825296,}",
  [800921] = "{id=800921,Text='你说，只要我能做到就一定会帮你！',Speaker=825291,}",
  [800922] = "{id=800922,Text='上次你放了我鸽子，这次就别想逃跑了。',Speaker=825296,Emoji=5,}",
  [800923] = "{id=800923,Text='现在，立刻，马上，我要和你看一场烟花大会，然后给我拍一张照片，否则我不给你原料。',Speaker=825296,}",
  [800924] = "{id=800924,Text='我上哪去弄烟花啊！',Speaker=825291,Emoji=1,}",
  [800925] = "{id=800925,Text='那我不管，没烟花看，就莫得原料。哼哼！！',Speaker=825296,Emoji=40,}",
  [800926] = "{id=800926,Text='这家伙提出的要求可真离谱，我上哪弄烟火去！',Speaker=825291,Emoji=42,}",
  [800927] = "{id=800927,Text='冒险者，你说你想到办法了？',Speaker=825291,Option='用魔法代替烟花',}",
  [800928] = "{id=800928,Text='哎呀，我怎么没想到呢？还是冒险者聪明，嘿嘿！',Speaker=825291,}",
  [800929] = "{id=800929,Text='冒险者你能制造出能持续很久的魔法吗？',Speaker=825291,Option='试试看',}",
  [800930] = "{id=800930,Text='布置好了持续性魔法，去找罗琳吧！',}",
  [800931] = "{id=800931,Text='很好，这样就可以满足爱丽丝的要求了。',Speaker=825291,}",
  [800932] = "{id=800932,Text='哦？你们竟然想到用持续性魔法代替烟花，挺不赖的嘛。',Speaker=825296,}",
  [800933] = "{id=800933,Text='既然这样，你这个家伙就陪我看一次烟花，顺便拍个照片吧！',Speaker=825296,}",
  [800934] = "{id=800934,Text='绚丽的光效，好美呀！',}",
  [800935] = "{id=800935,Text='我也这么觉得。',}",
  [800936] = "{id=800936,Text='尤尔根是笨蛋！',}",
  [800937] = "{id=800937,Text='我也这么……',}",
  [800938] = "{id=800938,Text='哈哈，你差点上当了。',}",
  [800939] = "{id=800939,Text='有照片吗？拿来我看看！',Speaker=825296,}",
  [800940] = "{id=800940,Text='照片很不错，我非常喜欢！这是你需要的绘画原料，拿去吧！',Speaker=825296,Emoji=25,}",
  [800941] = "{id=800941,Text='谢谢你了，有空我会找你聊些家族的事情。',Speaker=825291,}",
  [800942] = "{id=800942,Text='再说吧！哼，虽然你上次放了我鸽子，但这次也就马马虎虎的补偿我了。',Speaker=825296,}",
  [800943] = "{id=800943,Text='…………（这段时间内还是不要再来找她了）',Speaker=825291,}",
  [800944] = "{id=800944,Text='这样就搜集全了绘画原料，我们可以出发去寻找德尔贡大师了！',Speaker=825291,}",
  [800950] = "{id=800950,Text='好了，您可以休息了。',}",
  [800953] = "{id=800953,Text='这是我应该做的。',Speaker=825292,}",
  [800980] = "{id=800980,Text='尤尔根大人的魅力无人可敌！',}",
  [800981] = "{id=800981,Text='我们永远爱尤尔根大人！',}",
  [800982] = "{id=800982,Text='尤尔根最强！最美丽！',}",
  [800989] = "{id=800989,Text='这里应该就是藏书地点了，机关和陷阱果然都失控了。',}",
  [800990] = "{id=800990,Text='前面存在很多陷阱，先解决面前的难题吧！',}",
  [800991] = "{id=800991,Text='跨越了陷阱，前面好像有很多失控的机关兽。',}",
  [800992] = "{id=800992,Text='如果不想办法让它们安静下来，恐怕无法前进。',}",
  [800993] = "{id=800993,Text='一鼓作气击败它们吧！',}",
  [800994] = "{id=800994,Text='机关兽们稳定下来了，继续向前出发吧！',}",
  [800995] = "{id=800995,Text='识别人物失败……开启歼灭模式！',Speaker=825310,}",
  [800996] = "{id=800996,Text='毁灭模式启动！',}",
  [800997] = "{id=800997,Text='歼灭入侵者！',}",
  [800998] = "{id=800998,Text='机关战甲稳定下来了，前面应该就是放置记事簿的地点，去看看吧。',}",
  [800999] = "{id=800999,Text='能看到里面的记事簿，不过得要先解决封印阵法。',}",
  [801000] = "{id=801000,Text='试试隆德大总管交予的钥匙，或许能解除封印阵法。',}",
  [801001] = "{id=801001,Text='封印阵法解除了，可以拿走记事簿了。',}",
  [801002] = "{id=801002,Text='记事簿到手，回去找尤尔根吧！',}",
  [801043] = "{id=801043,Text='准备好了，就来找我吧！',Speaker=825295,}",
  [801044] = "{id=801044,Text='考验分为三个部分，决定好之后上前感应权杖气息，开启试炼。',Speaker=825295,}",
  [801045] = "{id=801045,Text='疾速试炼由两部分构成，点光圈和一笔画，主要考验我族后辈的反应力，准备好了就来找我。',Speaker=825301,Option='{准备好了,3},{再等一下,2}',}",
  [801046] = "{id=801046,Text='你通过了我这部分的考验，希望你能继续造福于韦格纳家族。',Speaker=825301,}",
  [801047] = "{id=801047,Text='很可惜失败了，重新来过吧！',Speaker=825301,}",
  [801048] = "{id=801048,Text='渊博试炼主要是想考验你对韦格纳家族历史的了解，准备好了就来找我吧！',Speaker=825302,Option='{准备好了,3},{再等一下,2}',}",
  [801049] = "{id=801049,Text='韦格纳家族成功当上国王的有几位？',Speaker=825302,Option='{3位,13},{2位,12}',}",
  [801050] = "{id=801050,Text='很好，我们继续下一题。',Speaker=825302,}",
  [801051] = "{id=801051,Text='看来你对家族的历史了解还不够充分，再想想吧！',Speaker=825302,}",
  [801052] = "{id=801052,Text='韦格纳家族家族的祖训是什么？',Speaker=825302,Option='{传统即为正统,23},{欲望需要人心与利益浇灌,22}',}",
  [801053] = "{id=801053,Text='很好，我们继续下一题。',Speaker=825302,}",
  [801054] = "{id=801054,Text='看来你对家族的历史了解还不够充分，再想想吧！',Speaker=825302,}",
  [801055] = "{id=801055,Text='韦格纳家族家族的族花是什么？',Speaker=825302,Option='{海芋百合,33},{菟葵,32}',}",
  [801056] = "{id=801056,Text='不错，你全都答对了。',Speaker=825302,}",
  [801057] = "{id=801057,Text='看来你对家族的历史了解还不够充分，再想想吧！',Speaker=825302,}",
  [801058] = "{id=801058,Text='你通过了我这部分的考验，希望你能继续造福于韦格纳家族。',Speaker=825303,}",
  [801059] = "{id=801059,Text='极限考验主要是想考验你的力量，准备好了就来找我吧！',Speaker=825303,Option='{准备好了,3},{再等一下,2}',}",
  [801060] = "{id=801060,Text='稍后会出现很多投影，击败它们就算完成考核。',Speaker=825303,}",
  [801061] = "{id=801061,Text='你通过了我这部分的考验，希望你能继续造福于韦格纳家族。',Speaker=825303,}",
  [801084] = "{id=801084,Text='能证明自己“[c][ffff00]声望[-][/c]”的那件东西，或许可以让母亲明白我在家族中的地位。',Speaker=825291,}",
  [801088] = "{id=801088,Text='记载韦格纳“[c][ffff00]家族历史[-][/c]”的那件东西，可以让母亲明白家族曾经出现过很多国王。',Speaker=825291,}",
  [801091] = "{id=801091,Text='代表“[c][ffff00]曾经至高无上权力[-][/c]”的那件物品，或许可以让母亲明白胜任国王后，与此同时也需要承担对应的责任与代价。',Speaker=825291,}",
  [801103] = "{id=801103,Text='看着冒险者一路披荆斩棘，我也受到了鼓舞，以后我要的变得更强。',Speaker=825291,Option='一起加油',}",
  [801104] = "{id=801104,Text='你们已经进入韦格纳先祖们的试炼空间，激活开关开始试炼吧！',Speaker=825295,}",
  [801105] = "{id=801105,Text='机关已经开启，准备开始进行试炼吧！',}",
  [801106] = "{id=801106,Text='完成了先祖的试炼，我们回去找罗克纳多吧。',Speaker=825291,}",
  [801153] = "{id=801153,Text='看见前方巡逻的敌人了吗，这些是这座监牢中的低等囚犯，他们大多是那些强大魔王的爪牙。',Speaker=826613,}",
  [801154] = "{id=801154,Text='如果你能够将他们击败，就能开启被他们霸占的[c][ffff00]虚空遗藏[-][/c]，获得源自虚空的力量馈赠。',Speaker=826613,}",
  [801155] = "{id=801155,Text='这或许对于你挑战那些魔王是有帮助的吧？我就在这里等着你，你去给他一点小小的教训。',Speaker=826613,}",
  [801156] = "{id=801156,Text='很好，如果你准备好了，就让我们去面对更强大的魔王，让我看看你的本事。',Speaker=826613,}",
  [801157] = "{id=801157,Text='当然，如果你觉得自己实力还不够的话，也可以在这里寻找更多的[c][ffff00]虚空遗藏[-][/c]强化自己！',Speaker=826613,}",
  [801158] = "{id=801158,Text='前面就是囚禁魔王的监牢了，去召唤并击败他吧！',Speaker=826613,}",
  [801159] = "{id=801159,Text='哦，对了。杀死那些魔王虽然会给你带来不菲的奖励，但是获得这些奖励本身就是对抗虚空领域的法则，因此会大幅消耗你的体力。',Speaker=826613,}",
  [801160] = "{id=801160,Text='现在，击败魔王，向我证明你的实力吧！',Speaker=826613,}",
  [801161] = "{id=801161,Text='干得不错，要不是因为你的肉体凡胎，我真想把你留在这儿永远做我的助手！',Speaker=826613,}",
  [801162] = "{id=801162,Text='虚空领域非常古老，许多隐秘之处甚至连我都不知晓，多在这里探索一番吧！',Speaker=826613,}",
  [801192] = "{id=801192,Text='很好，下面就让我们去面对更强大的魔王，让我看看你真正的本事。',Speaker=826613,}",
  [801193] = "{id=801193,Text='快点跟上我，可千万不要掉队，千万小心那些虚空的囚徒…',Speaker=826613,}",
  [801194] = "{id=801194,Text='如果有什么不明白的，就去初始的台地上找我，有些事情我会详细跟你说！',Speaker=826613,}",
  [801195] = "{id=801195,Text='怎么样？看来奖励不错，这是仅在这块虚空领域生效的特殊效果，多多收集，在这片领域内，多提升自己的力量绝不是什么坏事！',Speaker=826613,}",
  [801196] = "{id=801196,Text='这是一点小奖励，凡人，希望你在这片虚空之地玩的开心！',Speaker=826613,}",
  [801200] = "{id=801200,Text='你个大笨蛋！',Speaker=890914,}",
  [801201] = "{id=801201,Text='我~又~来~啦~~~',Speaker=890914,}",
  [801202] = "{id=801202,Text='瞧瞧是谁来啦~~~',Speaker=890914,}",
  [801203] = "{id=801203,Text='无~聊~~~',Speaker=890914,}",
  [801205] = "{id=801205,Text='哦对了~魔王们只会在8:00-24:00出现，毕竟他们也是需要休息来恢复力量的，可别跑空了！',Speaker=826613,}",
  [801209] = "{id=801209,Text='心象世界正在崩塌重建',}"
}
Table_Dialog_Left_2.count = 2001
